/* IB SEHS focus lesson — authored layer.
   One entry per section: the summary sentences, one analogy
   (red card) and one example (blue card). Keys are the EXACT English
   section titles used by IBSEHS_NATIVE / IB_DEEP / IB_VISUALS.
   Generated by the build; edit authored*.py, not this.
   Every **term** here also appears in that section's key-term list, so the
   drill blanks a word the glossary will go on to define. */
window.IBSEHS_LESSON = {  "Communication systems": {   "sum": [    {     "en": "Your body runs on two communication systems, and the faster one is the one you never notice.",     "zh": "身体有两套通讯系统，而更快的那套你几乎察觉不到。"    },    {     "en": "The **nervous system** sends **electrical impulses** along **neurones**, and passes the message across every gap using **neurotransmitters**.",     "zh": "**神经系统**沿**神经元**传递**电脉冲**，并在每一道空隙处用**神经递质**交接信息。"    },    {     "en": "One nerve signal is therefore **electrical → chemical → electrical**: electricity down the wire, a chemical crossing each **synapse**, electricity again on the far side.",     "zh": "所以一个神经信号是**电 → 化学 → 电**：在线上是电，在每个**突触**处是化学，到了对侧又是电。"    },    {     "en": "The **endocrine system** skips the wiring entirely. A **gland** releases **hormones** straight into the **bloodstream**, and the blood carries them to every corner of the body.",     "zh": "**内分泌系统**完全不需要导线。**腺体**把**激素**直接释放进**血液**，血液再把它带到全身每个角落。"    },    {     "en": "But only **target cells** answer. A cell is a target only if it carries the matching **receptor**, which is shaped like a lock the hormone fits.",     "zh": "但只有**靶细胞**会回应。一个细胞要成为靶细胞，必须带有相应的**受体**——它的形状像一把恰好配得上的锁。"    },    {     "en": "That one difference explains the rest: nerves are **milliseconds**, **local** and precise, while hormones take **seconds to days** and reach **everywhere**.",     "zh": "这一个差别就解释了一切：神经是**毫秒级**、**局部**而精准；激素则是**秒到天**，并且**无处不到**。"    },    {     "en": "It also explains why a hormone cannot be aimed. Because there is no wire to pin it to one place, an unwanted **side effect** is felt body-wide.",     "zh": "这也解释了为什么激素无法瞄准：没有导线把它钉在某处，不想要的**副作用**就会波及全身。"    }   ],   "analogy": {    "en": "A nerve is a **light switch**. A hormone is a **notice on a board**. The switch only affects the room it is wired to, and it does it instantly. The notice reaches every corridor in the building — but only the students who read it act on it, and only when they happen to pass it.",    "zh": "神经是**电灯开关**，激素是**布告栏上的一张通知**。开关只影响它接了线的那间房，而且立刻生效；通知会传遍整栋楼的每条走廊，但只有读到的学生才会照做，而且要等他们路过时。"   },   "example": {    "en": "The gun fires in a 100 m sprint and your leg muscles are already contracting, because a nerve impulse got there in well under a second. Waiting for adrenaline to arrive would mean standing on the blocks. Adrenaline then takes over the next half-minute or so and does the slower work: heart rate up, blood sent to the muscles, glucose freed from the liver. Two systems, one race, each doing the job it is actually suited to.",    "zh": "100米短跑发枪的瞬间，你的腿部肌肉已经开始收缩，因为神经冲动在远不到一秒内就传到了。如果等肾上腺素送过来，你会一直站在起跑器上。接着肾上腺素接管接下来的大约半分钟，做那些慢的工作：心率上升、血液流向肌肉、肝脏释放葡萄糖。两套系统、一场比赛，各自做着它们真正擅长的事。"   }  },  "Neural pathways and coordination": {   "sum": [    {     "en": "The **central nervous system** is the brain and spinal cord. Everything else — every nerve running to a muscle, a gland, a piece of skin — is the **peripheral nervous system**.",     "zh": "**中枢神经系统**是脑和脊髓。其余一切——通往肌肉、腺体、皮肤的所有神经——都是**周围神经系统**。"    },    {     "en": "The spinal cord is not just a cable. It is a decision-making centre in its own right, which is why a reflex can work even when the brain never hears about it.",     "zh": "脊髓不只是一根缆索，它本身就是独立的决策中心——所以反射发生时大脑可以完全不知情。"    },    {     "en": "A **reflex** runs on a shortcut: receptor → spinal cord → muscle, with no detour to the brain and no decision required.",     "zh": "**反射**走的是一条捷径：感受器 → 脊髓 → 肌肉，不必绕道大脑，也不需要任何决策。"    },    {     "en": "**Somatic** control drives **skeletal muscle**, so it is voluntary and it moves you. **Autonomic** control runs your organs, so it is involuntary and it keeps you alive.",     "zh": "**躯体**神经支配**骨骼肌**，因此它是随意的、指挥你动作的；**自主**神经管理你的器官，因此它是不随意的、维持你生命的。"    },    {     "en": "Coordinated movement is not one system winning. It is sensory input and motor output running at the same time, with the brain adding only the timing and the fine adjustment.",     "zh": "协调的动作不是某一套系统赢了，而是感觉输入与运动输出同时进行，大脑只额外补上时机和细微的修正。"    }   ],   "analogy": {    "en": "Think of the spinal cord as a **local post office** and the brain as the **head office**. A letter from the hand to a fingertip travels to the local branch first — that is the reflex. Only if the branch thinks it matters does it escalate to head office, and only head office sends back a considered, voluntary instruction.",    "zh": "把脊髓想成**本地邮局**，大脑是**总部**。从手到指尖的“信件”先送到本地网点——那就是反射。只有网点认为这事重要，它才上报总部；也正是总部会回寄一封经过权衡的、随意的指令。"   },   "example": {    "en": "You land badly from a rebound and your knee jerks before you feel anything. That is the knee-jerk reflex: the sensory nerve fired, the spinal cord decided, and the quadriceps was told to contract, all inside about 50 milliseconds. Had the reflex been voluntary, you would have been on your way down before the decision arrived. Now compare the same athlete deliberately lifting a bar: that is somatic control, brain-led and slow enough to be corrected.",    "zh": "你抢篮板落地不稳，膝盖在你还没感觉到之前就已经弹了一下。这就是膝反射：感觉神经放电，脊髓做出决定，四头肌被命令收缩，整个过程大约只用50毫秒。如果这个反射要靠大脑随意决定，你人还在往下掉就已经落地了。再对比同一位运动员刻意举起一根杠铃：那是躯体神经控制，由大脑主导，慢到足以随时修正。"   }  },  "Systems working together": {   "sum": [    {     "en": "Your organs are not separate machines sharing a room. They are one connected system, like the departments of a hospital sharing one patient.",     "zh": "你的器官不是同处一室却互不相干的独立机器。它们是一个连通的系统，就像同一家医院里各科室共享同一个病人。"    },    {     "en": "**Interdependence** is the rule: the heart cannot pump what the lungs never oxygenated, and no muscle works what the blood never delivered.",     "zh": "**相互依存**是铁律：肺没有氧化的东西，心脏泵不出去；血液没送达的肌肉，也动不了。"    },    {     "en": "Every system also **constrains** the others. Tight muscles limit a stride; a low oxygen carrying capacity caps what the cardiovascular system can deliver.",     "zh": "每个系统也都在**限制**其他系统。紧绷的肌肉限制步幅，携氧能力不足就封顶了心血管系统能输送的上限。"    },    {     "en": "They all hold **homeostasis** together. No single system owns stability — it is the sum of everyone staying inside their limits at the same time.",     "zh": "**稳态**是它们共同维持的。没有任何一个系统独占稳定——它是所有系统同时守在各自范围内加总出来的结果。"    },    {     "en": "**Negative feedback** is the ordinary case: a change is detected, a response cancels it, and the variable returns to its normal range. Body temperature, blood glucose and blood pressure all work this way.",     "zh": "**负反馈**是常态：变化被察觉，反应把它抵消，变量回到正常范围。体温、血糖、血压都是这样工作的。"    },    {     "en": "**Positive feedback** is the rare case: the response amplifies the change until it hits a deliberate endpoint. Blood clotting and childbirth both run this way.",     "zh": "**正反馈**是少数情况：反应放大变化，直到抵达一个有意为之的终点。凝血和分娩都是这样运作的。"    },    {     "en": "Exercise moves the limits. As demand rises, every system is pushed closer to its own ceiling, and whichever one has the lowest ceiling becomes the one that decides when you have to slow down.",     "zh": "运动会移动这些上限。需求升高时，每个系统都被推向更接近自己的天花板，而天花板最低的那个系统，就决定了什么时候必须减速。"    }   ],   "analogy": {    "en": "A rowing eight is one crew, not eight individuals. If rowers three and four are not pulling to the same rhythm, the shell does not average out — it wobbles and loses speed. Stability is the sum of everyone staying inside their limits at the same time.",    "zh": "八人赛艇是一个整体，而不是八个个体。如果三号和四号桨手不在同一个节奏上，船不会互相抵消——它会摇晃、失速。稳定就是所有人在同一时间各自守在范围内加总出来的结果。"   },   "example": {    "en": "An altitude camp works because of interdependence, not because of one system. At altitude the cardiovascular system must deliver more oxygen per minute, but the respiratory system cannot simply take more in — the air is thinner. The adaptation that actually helps is made by the **respiratory system** growing mitochondria and red blood cells over weeks. Endurance then improves for one specific reason: the cardiovascular system was always capable of more, it just had nothing to carry.",    "zh": "高原训练有效，靠的是相互依存，而不是某一个系统。在高原，心血管系统每分钟必须输送更多氧气，但呼吸系统没法简单地“吸更多”——空气更稀薄。真正有帮助的适应来自**呼吸系统**：它在数周内增加了线粒体和红细胞。所以耐力之所以提升，原因很具体——心血管系统一直有能力，只是之前没有东西可运。"   }  },  "Feedback and integrated examples": {   "sum": [    {     "en": "**Negative feedback** is a correction loop. It does not aim at a number, it aims at a **range**: too hot, so sweat; too cold, so shiver; too high, so excrete.",     "zh": "**负反馈**是一个纠偏回路。它不以某个数字为目标，而以一个**范围**为目标：太热就出汗，太冷就发抖，太高就排出。"    },    {     "en": "Exercise adds a complication: the body is deliberately moved **away** from its resting set point. Core temperature rises, plasma volume falls, glucose is consumed.",     "zh": "运动增加了一层复杂性：身体被**主动**推离静息设定点。核心体温上升、血浆容量下降、葡萄糖被消耗。"    },    {     "en": "So feedback has to work against a **moving baseline**, not a fixed one.",     "zh": "所以负反馈必须对一个**移动的基线**工作，而不是固定的基线。"    },    {     "en": "That is why you feel thirst, overheating and fatigue all rising together: each one is a different variable leaving its range at the same moment.",     "zh": "这就是为什么口渴、过热和疲劳会一起冒出来：它们是三个不同的变量在同一时刻一起越出范围。"    },    {     "en": "Heart rate is the clearest example of a controlled variable. It rises because the working muscles demand more oxygen, and it is a **controlled** variable precisely because something is holding it back.",     "zh": "心率是受控变量最清楚的例子。它上升是因为工作的肌肉要更多氧气，而它之所以“受控”，正因为有东西在约束它。"    },    {     "en": "**Positive feedback** works in the opposite direction, and it is always bounded. It pushes a change until a specific endpoint is reached and then stops on purpose.",     "zh": "**正反馈**方向相反，而且始终有边界。它把变化推向某个特定终点，然后主动停止。"    },    {     "en": "Put the two together and a training session stops looking like random distress.",     "zh": "把两者放在一起看，一次训练课就不再像随意的折磨。"    },    {     "en": "Every adaptation you recover from is negative feedback rebuilding what exercise dismantled — which is precisely why recovery days are not laziness.",     "zh": "你恢复的每一项适应，都是负反馈在重建运动破坏的东西——这正是休息日不是偷懒的原因。"    }   ],   "analogy": {    "en": "Negative feedback is a **thermostat**. You do not set a thermometer to “make the room 21°” — you set a **range**, and the system pushes back toward it from whichever side it drifted. Positive feedback is a **crowd at a concert**: each person clapping makes the next person clap louder, and it keeps building until a peak, not because anyone decided where to stop but because people can only clap so hard.",    "zh": "负反馈像**恒温器**。你不是把温度计设成“让房间变成21度”，而是设一个**范围**，系统会从偏移的任何一侧把它推回来。正反馈像**演唱会的观众**：一个人鼓掌让旁边的人鼓得更响，如此层层放大直到某个峰值——停下不是因为谁决定了在哪里停，而是因为人的鼓掌力度有上限。"   },   "example": {    "en": "Take a 30-minute time trial in heat. Sweating removes more fluid than you take in, plasma volume falls, stroke volume drops, and cardiac output can no longer rise with effort — so heart rate climbs further for the same speed. Nothing is broken: the same loop that lets you handle a marathon is the loop you are now outrunning. Two things pull you back inside your range, and both cost time: drink, and slow down.",    "zh": "在高温下骑30分钟计时赛。出汗排出的液体超过摄入，血浆容量下降，每搏输出量减少，心输出量再也跟不上强度——于是同样速度下心率升得更高。哪里都没坏：你本来能应付马拉松的那套回路，就是你现在“跑赢”的那套。有两件事把你拉回范围内，而且都要付出时间：喝水，和减速。"   }  },  "Voluntary movement and reflexes": {   "sum": [    {     "en": "Every deliberate movement runs the same four stages: sensory input, central processing, motor output, and then the **effector** — the muscle or gland that actually does it.",     "zh": "每一个有意识的动作都走同样的四个阶段：感觉输入、中枢处理、运动输出，最后由**效应器**——真正执行动作的肌肉或腺体——完成。"    },    {     "en": "**Voluntary** movement is brain-led. You decide, and the instruction travels all the way out to the muscle.",     "zh": "**随意运动**由大脑主导。你先做决定，指令一路传到肌肉。"    },    {     "en": "A **reflex** is not a lesser version of that. It is a different circuit, and it exists for one reason: speed.",     "zh": "**反射**不是随意运动的“简化版”，而是另一条回路，它存在的理由只有一个：快。"    },    {     "en": "The receptor fires, the signal enters the spinal cord, an **interneuron** connects it to a **motor neurone**, and the muscle contracts. The brain is informed afterwards, if at all.",     "zh": "感受器放电，信号进入脊髓，一个**中间神经元**把它接到**运动神经元**，肌肉收缩。大脑事后才被通知——如果会被通知的话。"    },    {     "en": "That is why a knee jerk is finished before you feel the tap, and why a hand pulls off a hot surface before the pain is consciously registered.",     "zh": "这就是为什么膝反射在你感觉到敲击之前就已经完成，手也会在疼痛被意识登记之前就离开热源。"    },    {     "en": "**Reaction time** is the measurable gap between a stimulus and a response, and it is genuinely trainable. A goalkeeper who reads a penalty 50 ms earlier has a real physical advantage.",     "zh": "**反应时间**是刺激与反应之间那段可测量的间隔，而且确实可以训练。守门员若能提前50毫秒读出点球，就拥有真实的生理优势。"    }   ],   "analogy": {    "en": "A reflex is a **fire door**. The alarm sounds, the door closes itself, and nobody standing in the corridor stops to ask whether closing it is really the best idea. The building does not wait for the architect because fire does not send a memo.",    "zh": "反射像一道**防火门**。警报一响，门自动关上，走廊里没有人会停下来讨论“关是不是最好的选择”。建筑物不会等建筑师，因为火不会先发公文。"   },   "example": {    "en": "A goalkeeper in a penalty shootout is the purest case of the difference. They cannot decide whether to dive — the information is still arriving. Their hands move because the optic nerve fired, the midbrain routed it, and the motor pathway fired outward. All of it finished in around 200 milliseconds. The training that improves a keeper is not making them think faster; it is shortening that automatic route.",    "zh": "点球大战里的守门员是这一差异最纯粹的例子。他没法“决定”要不要扑——信息还在路上。他的手动了，是因为视神经放电、中脑完成中继、运动通路向外放电，整个过程约200毫秒就结束了。提升守门员水平的训练不是让他们想得更快，而是把这条自动通路缩短。"   }  },  "Hormonal influences and sport applications": {   "sum": [    {     "en": "**Hormones** are the slow half of the story, and in sport they matter most where nerves cannot help: fuel, recovery, temperature, growth, and the stress response.",     "zh": "**激素**是故事里慢的那一半，而在运动中它们最要紧的地方正是神经帮不上忙的：供能、恢复、体温、生长，以及应激反应。"    },    {     "en": "An **aerobic** response is mostly hormonal. **Adrenaline** mobilises glucose and redirects blood to muscle, while **insulin** and **glucagon** hold blood glucose steady.",     "zh": "**有氧**反应主要靠激素。**肾上腺素**动员葡萄糖并把血液调往肌肉；**胰岛素**与**胰高血糖素**则稳住血糖。"    },    {     "en": "**Growth hormone** and **testosterone** work on a longer clock, driving adaptation over weeks.",     "zh": "**生长激素**与**睾酮**的时钟更长，它们在数周尺度上驱动适应。"    },    {     "en": "The trade is a wider reach. Because a hormone travels everywhere, an unintended action is felt everywhere too — which is why doping is not a single effect but a whole set of them.",     "zh": "代价是波及更广。因为激素到处走，非预期的作用也会到处体现——所以兴奋剂从来不是一个孤立的副作用，而是一整组副作用。"    },    {     "en": "**Cortisol** sits on the other side. It is the stress and breakdown hormone: it raises blood glucose for a fight-or-flight moment and, left high, suppresses repair.",     "zh": "**皮质醇**站在另一边。它是应激与分解代谢的激素：为应激时刻升高血糖，而长期偏高则抑制修复。"    },    {     "en": "That is why **acute** stress can be useful and **chronic** stress is not: the same hormone, the same pathway, opposite consequences.",     "zh": "所以**急性**应激有用而**慢性**应激有害：同一个激素、同一条通路，后果却相反。"    },    {     "en": "The only difference is how long it stays switched on.",     "zh": "唯一的区别，是它被打开了多久。"    },    {     "en": "Practical upshot for sport: train hard, then give the hormonal side time to close the loop. The adaptation you are chasing is built by hormones while you rest, not by the hormones you spent while you worked.",     "zh": "对运动的实际启示：高强度训练，然后给激素这条回路留出完成的时间。你追求的适应，是在休息时由激素建成的，而不是在你训练时耗掉的那部分。"    }   ],   "analogy": {    "en": "Nerves are a **text message**: it arrives where you sent it, immediately. Hormones are a **radio broadcast**: it reaches everyone in range, but you cannot recall it and everyone hears it at a slightly different time. That is also why a hormone cannot be aimed, and why the side effects of a doping substance are spread so widely.",    "zh": "神经像一条**短信**：立刻送到你指定的那个人手里。激素像**电台广播**：范围内人人都收得到，但你没法撤回，而且每个人听到的时间还略有差别。这正说明激素无法瞄准，也解释了兴奋剂为什么会有如此分散的副作用。"   },   "example": {    "en": "A two-hour marathon is a hormonal event wrapped in a muscular one. The muscles are doing the work, but **adrenaline** sets the pace early, **cortisol** governs what is available after roughly ninety minutes, and fluid balance decides whether the athlete finishes at all. The runner who trains the nervous side only can have perfect recruitment and still fade after 80 kilometres, because the limiting factor moved to the hormone side.",    "zh": "两小时的马拉松是一场裹在肌肉里的激素事件。肌肉在出力，但**肾上腺素**在早期决定配速，**皮质醇**支配大约九十分钟之后还有什么可用，而水合状态决定运动员能不能跑完。只训练了神经一侧的跑者，募集可以完美，却仍在80公里后掉速——因为限制因素已经转移到了激素那一侧。"   }  },  "Functions, intake and loss": {   "sum": [    {     "en": "**Water** is the solvent your cells run in, and it also transports nutrients, wastes and heat. About 60% of body mass in a typical adult.",     "zh": "**水**是细胞赖以运转的溶剂，同时也负责运输营养、废物和热量。典型成人体重的约60%是水。"    },    {     "en": "You gain water from drinking and from **metabolic water** — the water produced as a by-product when the body oxidises fat and carbohydrate.",     "zh": "你从饮水获得水，也从**代谢水**获得——身体氧化脂肪和碳水化合物时副产生的少量水。"    },    {     "en": "You lose it from four places: **urine**, sweat, breath, and **faeces**. On a cool day at rest the urine dominates; in a hard run in heat, sweat takes over completely.",     "zh": "水从四个途径流失：**尿液**、**汗液**、**呼吸**和**粪便**。凉爽的休息日以排尿为主；高温高强度运动时则完全由出汗主导。"    },    {     "en": "**Electrolytes** are the ions that make water useful — **sodium**, potassium, calcium, chloride. They carry charge across membranes, and nerve signalling is mostly their traffic.",     "zh": "**电解质**是让水变得有用的离子——**钠**、钾、钙、氯。它们负责跨膜搬运电荷，而神经信号本质上就是它们的交通。"    },    {     "en": "Water follows salt. Where **sodium** sits, water follows it, so the body controls where fluid goes by controlling where sodium sits.",     "zh": "水随盐走。**钠**在哪里，水就跟到哪里，所以身体通过控制钠的分布来控制液体流向。"    }   ],   "analogy": {    "en": "Body water is the **water in a sponge, and the sponge itself**. Water alone would drip straight through the cells and take nutrients with it. Electrolytes are what hold the structure together, so you can carry a solution instead of losing it.",    "zh": "体内水分像是**海绵里的水，以及海绵本身**。若只有水，它会直接穿过细胞流走，还顺带带走营养物质。电解质把结构撑住，于是你携带的是一份溶液，而不是把它丢掉。"   },   "example": {    "en": "A marathoner loses around 1–1.5 litres of sweat an hour, and a hard session in summer can reach two. Replace the water but not the salt and something unhelpful happens: the sweat stays dilute, so you lose proportionally more water for the same amount of sweat, and the **sodium** you do replace keeps some of the fluid inside the vascular space. That is why ordinary water alone can leave a heavy sweater feeling worse, not better.",    "zh": "马拉松运动员每小时流失约1到1.5升汗液，夏季高强度训练时可达两升。只补水不补盐，会发生一件适得其反的事：汗液被稀释，于是等量出汗反而流失更多水；而补充进去的**钠**会把一部分水留在血管内。所以对出汗多的人来说，光喝白水反而可能更难受。"   }  },  "Imbalance and hydration monitoring": {   "sum": [    {     "en": "Water balance is a ledger: everything in has to equal everything out, and the margin you care about is roughly **2% of body mass**.",     "zh": "水分平衡是一本账：摄入必须等于排出，而你真正在意的余量大约是**体重的2%**。"    },    {     "en": "Losing about **2%** of body mass as water already measurably impairs performance, and the cost keeps rising from there rather than starting at that number.",     "zh": "以水的形式失去约**2%**体重，运动表现就已经开始下降，而且代价从此继续上升，而不是恰好从那个数字开始。"    },    {     "en": "Cross **5%** and the effect is severe: core temperature climbs, the central nervous system is dulled, and perceived exertion rises sharply for the same work.",     "zh": "越过**5%**，影响就很严重：核心体温上升，中枢神经被钝化，同样的负荷下主观疲劳感明显升高。"    },    {     "en": "The four ways to monitor are all indirect: **body mass change** is the most reliable, then urine colour and specific gravity, then thirst, and finally performance itself.",     "zh": "四种监测手段都是间接的：**体重变化**最可靠，其次是尿液颜色和比重，再次是口渴感，最后才是表现本身。"    },    {     "en": "**Urine colour is the practical one.** Pale straw means adequate; dark amber means you are already behind and have been for a while.",     "zh": "**尿液颜色**是最实用的一项。淡稻草色说明足够；深琥珀色说明你已经落后，而且已经落后了一段时间。"    },    {     "en": "**Thirst is the worst of the four.** By the time you feel it you are already typically 1–2% down.",     "zh": "**口渴感**是这四项里最差的。等到感觉到它，体内通常已经掉了1到2%。"    },    {     "en": "In other words you are already losing performance, not about to.",     "zh": "也就是说，你已经在丢表现了，而不是将要开始丢。"    },    {     "en": "This is what makes **hyponatraemia** possible: large volumes of plain water without replacing sodium dilute blood sodium, and swelling in the brain is the serious outcome.",     "zh": "这正是**低钠血症**会发生的原因：大量饮用不含钠的水会稀释血钠，严重后果是脑水肿。"    },    {     "en": "Weight is the early warning here. Thirst is not.",     "zh": "这一点的早期预警是体重，而不是口渴。"    }   ],   "analogy": {    "en": "Hydration monitoring is a **fuel gauge on a car that only has one dial and no warning light**. The needle is bodyweight, and unlike thirst, it does not lie and it does not lag — but you have to stop and actually look at it, rather than waiting for something to announce itself.",    "zh": "水合监测像**一辆只有一个仪表、没有警示灯的车**。指针是体重，它不会说谎也不会滞后——但你得停下来真的去看它，而不是等什么东西来通知你。"   },   "example": {    "en": "Two athletes weigh in before a summer training camp. One has lost 1.1% of body mass and feels fine; the other has lost 3% and insists he feels fine too. Pre-camp, a football player is advised to add fluid and salt, and weighed again the next morning. By then the reading has either come back down or it has not, and that single number tells you more than a week of asking how training felt.",    "zh": "两名运动员在夏季训练营前称重。一人掉了体重的1.1%，自我感觉良好；另一人掉了3%，同样坚称没事。营训前，教练建议其中一名足球运动员补水补盐，第二天早上再称一次。到那时读数要么回落了，要么没有——这一个数字比连问一整周的训练感受都更有说服力。"   }  },  "ADH and cardiovascular drift": {   "sum": [    {     "en": "**Anti-diuretic hormone** is released when plasma volume or blood pressure drops. Its job is to keep water: it tells the kidneys to reabsorb more and to concentrate the urine.",     "zh": "当血浆容量或血压下降时，**抗利尿激素**被释放。它的任务是保住水：告诉肾脏多回收一些，并把尿液浓缩。"    },    {     "en": "**Osmolarity** is the concentration of dissolved particles, and it is the trigger that most tightly controls ADH — not volume, even though volume is what people remember.",     "zh": "**渗透压**是溶解粒子的浓度，它才是最紧密控制抗利尿激素释放的触发因素——不是血容量，尽管人们记住的往往是容量。"    },    {     "en": "Exercising raises body temperature, and heat raises osmolarity, so ADH climbs even in a well-hydrated athlete who has not actually lost volume yet.",     "zh": "运动会让体温升高，而体温升高会推高渗透压，因此即便一个补水充足、体内容量尚未真正下降的运动员，抗利尿激素也会上升。"    },    {     "en": "**Cardiovascular drift** is the slow upward creep of heart rate at a fixed workload. It is not fitness fading — it is heat, dehydration and sympathetic compensation.",     "zh": "**心血管漂移**指的是固定负荷下心率缓慢上爬的状态。它不是你体能变差，而是高温、脱水和交感神经代偿共同作用的结果。"    },    {     "en": "Skin blood flow rises to dump heat, so cardiac output gets **split**: more blood to skin, less available for the muscles.",     "zh": "皮肤血流上升是为了散热，于是心输出量被**分流**：流向皮肤的更多，可供肌肉使用的就少了。"    },    {     "en": "That is why the same pace that felt fine in spring feels like a different effort in July, and why **pre-cooling** and drinking on a plan both help.",     "zh": "这就是为什么同样的配速在春天感觉轻松、在七月却像另一回事，也是为什么**预先降温**和按计划补水都有用。"    }   ],   "analogy": {    "en": "Drift is a **rising tide while you keep running on the beach**. Your speed has not changed, but the water is getting deeper, so the same effort now costs more. The athlete's mistake is to treat the rising heart rate as a loss of fitness and to respond by slowing down, when the actual cause is heat and fluid and the fix is different.",    "zh": "漂移就像**你在沙滩上跑步，潮水却在上涨**。你的速度没变，但水变深了，于是同样的用力现在代价更高。运动员的误区是把心率上升当成体能下降，于是用减速来应对，而真正的原因是高温与缺水，解决办法完全不同。"   },   "example": {    "en": "Two cyclists ride the same 40-minute time trial, one in October and one in July. The July rider's heart rate climbs steadily from the first ten minutes even though both are equally trained and equally hydrated. Move that trial to 6 a.m. with cold water to drink and the drift largely disappears. Nothing about fitness changed; only the temperature did.",    "zh": "两名车手骑同样的40分钟计时赛，一名在十月，一名在七月。七月的车手从第一个十分钟起心率就稳步上升，尽管两人训练水平相同、补水量也相同。把这场计时赛挪到清晨六点、再备上冷水，漂移就基本消失了。体能没有任何变化，变的只有温度。"   }  },  "Macronutrients and individual needs": {   "sum": [    {     "en": "There are three **macronutrients** — carbohydrate, fat and protein — and the body will run out of two of them within hours while it can store the third for months.",     "zh": "人体有三种**宏量营养素**——碳水化合物、脂肪和蛋白质。其中两种几小时内就会耗尽，第三种却能储存数月。"    },    {     "en": "**Carbohydrate** stores as **glycogen**, and glycogen is the only fuel the body can burn without oxygen. Store about 400 g and you have roughly 90 minutes of hard work in reserve.",     "zh": "**碳水化合物**以**糖原**形式储存，而糖原是身体唯一无需氧气即可燃烧的燃料。储存约400克，大约相当于储备了90分钟高强度工作所需。"    },    {     "en": "**Fat** is far more energy-dense — about 9 kcal per gram against carbohydrate's 4 — so it is the body's long-term fuel and its main energy reserve.",     "zh": "**脂肪**的能量密度高得多——每克约9千卡，而碳水化合物是4千卡——因此它是身体的长期燃料，也是主要能量储备。"    },    {     "en": "**Protein** is not mainly a fuel. It is the raw material for enzymes, antibodies and muscle tissue, and it is used for energy only when carbohydrate and fat are already short.",     "zh": "**蛋白质**主要不是燃料。它是酶、抗体和肌肉组织的原料，只有在碳水化合物和脂肪都不足时才被拿来供能。"    },    {     "en": "**Essential** means the body cannot synthesise it and must get it from food. All nine amino acids, plus the essential fatty acids and a set of vitamins and minerals.",     "zh": "**必需**的意思是身体无法自行合成，必须从食物中获得。包括九种氨基酸、必需脂肪酸，以及一组维生素和矿物质。"    },    {     "en": "There is no single correct ratio for everybody. Needs shift with training load, body size, sex, age, climate and any medical condition, so a percentage is a starting point rather than a rule.",     "zh": "并不存在适合所有人的唯一比例。需求会随训练负荷、体重、性别、年龄、气候和任何疾病状况改变，所以某个百分比只是起点，不是规则。"    }   ],   "analogy": {    "en": "Carbohydrate, fat and protein are a **sprint pack, a touring tank and a tool kit**. You burn the pack in the first hour, the tank is what gets you across a continent, and the tool kit is not fuel at all — it is what repairs the car on the way. Mistaking the tool kit for fuel is exactly the mistake of loading an athlete with protein and calling it energy.",    "zh": "碳水化合物、脂肪和蛋白质像是**冲刺背包、旅行油箱和工具箱**。背包在第一个小时就烧完，油箱是你横穿一大陆的东西，而工具箱根本不是燃料——它是在路上修车的。用工具箱当燃料，正是给运动员猛塞蛋白质然后称之为能量的那个错误。"   },   "example": {    "en": "A marathoner who eats no carbohydrate on race morning relies almost entirely on fat, because without glycogen the aerobic system cannot access it quickly. The result is a fast start followed by heavy legs around 30 kilometres, and a “hitting the wall” that is a fuel-availability problem rather than a fitness one. The same athlete eating breakfast two to three hours before the race starts comfortably well into the second half.",    "zh": "马拉松运动员比赛当天早上不吃碳水，几乎完全依赖脂肪，因为在没有糖原的情况下有氧系统无法快速取用它。结果是起跑很快，然后在30公里左右双腿沉重，撞上“撞墙”——那是燃料可及性的问题，而不是体能问题。同样这位运动员在赛前两到三小时吃早餐，就能轻松撑到后半程。"   }  },  "Pre-exercise, during-exercise and recovery": {   "sum": [    {     "en": "The **4–5 hours before** a session is about **glycogen loading**: 1–4 g of carbohydrate per kilogram of body mass, finishing 2–4 hours out so it is digested and stored rather than sitting in your gut.",     "zh": "训练**前4到5小时**的重点是**糖原填充**：每公斤体重1到4克碳水化合物，并在开练前2到4小时结束，好让它被消化储存，而不是还堵在胃里。"    },    {     "en": "**30–60 minutes before**, go smaller and liquid: 1–2 g per kilogram is plenty, and the goal is blood glucose availability rather than a full stomach.",     "zh": "**开练前30到60分钟**，要少而要液体：每公斤1到2克就够，目标是让血糖可用，而不是塞满胃。"    },    {     "en": "**During exercise**, replace sweat fluid and little else. Carbohydrate during a session only starts to matter past about 60–90 minutes, where it spares muscle glycogen and delays fatigue.",     "zh": "**运动中**，要补的主要是汗液流失的液体，其他都靠后。碳水化合物在运动中要到约60到90分钟之后才开始起作用——那时它才能节省肌肉糖原并延缓疲劳。"    },    {     "en": "**Sodium** matters most when sweat rate is high and the session is long, because it is what the fluid will actually be absorbed from.",     "zh": "当出汗率高且训练时间较长时，**钠**最关键，因为水能否被吸收真正取决于它。"    },    {     "en": "**After exercise**, recovery nutrition has a window: roughly **0–4 hours**, while glycogen synthase is still elevated and the muscle is most willing to take glucose back up.",     "zh": "**运动后**，恢复营养有一个窗口期：大约**0到4小时**，此时糖原合酶仍处于较高活性，肌肉最愿意重新摄取葡萄糖。"    },    {     "en": "That window is why the advice is not “eat more eventually” but “eat within the window, then again within a few hours”, especially across a multi-day competition.",     "zh": "这个窗口就是为什么建议不是“最终多吃一点”，而是“在窗口内吃，几小时内再吃一次”——在多日赛事中尤其如此。"    }   ],   "analogy": {    "en": "Fuel strategy is **fuel for a journey, not fuel for a fire**. The car needs a full tank before the motorway and a drink on it, and it needs the tank refilled before the engine is cold again. Pouring all the fuel in at the start of a marathon is like filling a jerry can at the start line and carrying it the whole way: heavy, and it does not refuel itself.",    "zh": "供能策略是**为旅途准备燃料，不是为篝火准备燃料**。上高速前要加满油，路上要补水，而且在发动机凉下来之前要补上。马拉松一开始就灌满燃料，就像在起跑线灌满一只油壶然后一路提着那它走：沉，而且它不会自己给自己加油。"   },   "example": {    "en": "In a tournament where rounds are 40 minutes apart across three days, the decision that matters is what goes in the 3–4 hours after round one. An athlete who eats within that window refills the glycogen between rounds and treats the last round as just another round. One who eats “properly” only at dinner has run out by round two, and finishes the day slower than they started.",    "zh": "在三天赛制、每轮间隔40分钟的比赛中，真正起决定作用的是第一轮结束后3到4小时吃的东西。在窗口内进食的运动员，能在两轮之间补回糖原，把最后一轮当成普通一轮；而只在晚餐“好好吃”的人，到第二轮就见底了，最后一天会比开始时更慢。"   }  },  "Micronutrients, RED-S and microbiome": {   "sum": [    {     "en": "**Micronutrients** are needed in small amounts but they are not optional: they are cofactors the enzymes cannot work without.",     "zh": "**微量营养素**需要量很小，但并非可有可无：它们是酶发挥作用的辅助因子。"    },    {     "en": "**Vitamins** are organic, **minerals** are inorganic, and both are involved in oxygen transport, energy release and bone.",     "zh": "**维生素**是有机的，**矿物质**是无机的，两者都参与氧的运输、能量释放和骨骼构建。"    },    {     "en": "Deficiency shows up slowly and specifically. A lack of iron shows as fatigue long before anything else, and a lack of vitamin D shows up in bone and immunity rather than as an obvious illness.",     "zh": "缺乏的表现缓慢而具体。缺铁最先表现为疲劳，缺维生素D则体现在骨骼和免疫上，而不是某种明显的疾病。"    },    {     "en": "**Toxicity** is the opposite risk, and fat-soluble vitamins in particular accumulate rather than being excreted.",     "zh": "**中毒**是相反方向的风险，尤其是脂溶性维生素——它们会累积，而不是被排出。"    },    {     "en": "**RED-S** is **Relative Energy Deficiency in Sport**: not enough energy intake for the training actually being done.",     "zh": "**RED-S**指**运动中的相对能量缺乏**：摄入的能量不足以支撑实际完成的训练。"    },    {     "en": "The name matters because the problem is relative. An athlete eating enough for a light week can still be under-fuelled during a heavy one.",     "zh": "这个名称的重点在于“相对”。按轻负荷周摄入足够的运动员，在重负荷周仍然可能吃不够。"    },    {     "en": "It shows up far from sport: immunity falls, bone density falls, mood drops, and for some athletes hormonal function is disrupted.",     "zh": "它的表现离运动很远：免疫力下降、骨密度下降、情绪低落，对部分运动员还会扰乱激素功能。"    },    {     "en": "The **microbiome** — gut bacteria — is a second line worth knowing. Some organisms synthesise vitamins and short-chain fatty acids that the host absorbs.",     "zh": "**肠道微生物组**——肠道细菌——是值得了解的第二条线。部分菌种能合成维生素和短链脂肪酸，并被人体吸收。"    },    {     "en": "So the gut is part of nutrition, not just a tube that happens to sit there.",     "zh": "所以肠道是营养的一部分，而不只是恰好摆在那里的管道。"    }   ],   "analogy": {    "en": "Macronutrients are the **fuel in the tank**. Micronutrients are the **oil and the spark plug**: in tiny quantities, and the difference between a working engine and a seized one is entirely down to them. RED-S is running the engine on fumes because the driver is convinced the tank is fine.",    "zh": "宏量营养素是**油箱里的燃料**；微量营养素则是**机油和火花塞**：量很小，但引擎能跑还是抱死全看它们。而RED-S就像司机坚信油箱没问题，却让引擎在几乎没油的状态下硬跑。"   },   "example": {    "en": "A distance runner training twice a day, travelling, and controlling weight hits RED-S without ever feeling hungry in any obvious way. The early signals are a falling immune response — one cold after another — and a stalled bone-density profile, both attributed to “a hard block of training”. Raising total energy availability usually restores both, and it is the first thing to check before adding anything else to the programme.",    "zh": "一位每天训练两次、需要出差、同时还在控制体重的耐力运动员，可能落入RED-S，却完全没有明显的饥饿感。早期信号是免疫反应下滑——反复感冒——以及骨密度停滞，两者常被归因为“训练强度大的一段”。提高总能量可及性通常能同时修复两者，而且这是往计划里加任何其他东西之前该先查的第一项。"   }  },  "ATP and the energy continuum": {   "sum": [    {     "en": "**ATP** is the cell’s usable energy. It is not stored like fuel — there are only about 100 milliseconds of it in your body at any moment.",     "zh": "**ATP**是细胞可直接使用的能量。它并不像燃料那样储存——任何时刻你体内只有大约100毫秒的量。"    },    {     "en": "So ATP is **continuously resynthesised**, and the question that matters is not “how much” but **“how fast can it be made”**.",     "zh": "所以ATP在**不断重新合成**，而真正关键的问题不是“有多少”，而是**“能以多快的速度被造出来”**。"    },    {     "en": "**Phosphagen**: stored directly in muscle as creatine phosphate, rebuilt in about 3–5 seconds, and gone in roughly 10. This is sprinting and heavy lifting.",     "zh": "**磷酸原系统**：以肌酸磷酸酯形式直接储存在肌肉里，约3到5秒即可重建，大约10秒就耗尽。它对应冲刺和大力举。"    },    {     "en": "**Glycolytic**: carbohydrate broken down without oxygen, giving about 2 minutes of hard work and building up lactate as a by-product.",     "zh": "**糖酵解系统**：在无氧条件下分解碳水化合物，可支撑约2分钟高强度工作，同时副产物乳酸开始堆积。"    },    {     "en": "**Aerobic**: carbohydrate and fat with oxygen, giving the highest **total** output and the ability to keep going for hours.",     "zh": "**有氧系统**：在有氧条件下利用碳水化合物和脂肪，总输出最高，且能维持数小时。"    },    {     "en": "This is the **continuum**: all three run at once in every activity, and what changes is the **proportion**.",     "zh": "这就是所谓的**连续体**：三项在每种活动中都同时工作，变化的是各自的**比例**。"    },    {     "en": "The three systems are also limited by different things — phosphogen by stored substrate, glycolytic by rate and pain, aerobic by delivery of oxygen.",     "zh": "三套系统的限制因素也不同——磷酸原受储存基质限制，糖酵解受速率和疼痛限制，有氧受氧的输送限制。"    }   ],   "analogy": {    "en": "Think of three **tanks with three different taps**. The phosphagen tank is small but its tap is a fire hose. The glycolytic tank is bigger but the tap is narrower. The aerobic tank is enormous but the tap is a straw — which is fine, because you never empty it quickly.",    "zh": "把这三套系统想成**三个水箱配三种不同的水龙头**。磷酸原的水箱小，但水龙头是消防水带；糖酵解的水箱大一些，龙头却细一些；有氧的水箱极其庞大，但龙头只是一根吸管——不过没关系，因为你从来不会很快把它抽干。"   },   "example": {    "en": "In a 1500 m race the first 200 m are paid for from phosphagen and feel almost free, the middle 1000 m run on glycolysis and lactate is climbing, and the last 300 m are aerobic. Ask the same athlete to hold the opening 200 m pace for 800 m and the phosphagen tank is empty, glycolysis cannot sustain that rate, and the aerobic contribution arrives far too slowly to compensate.",    "zh": "在1500米比赛中，前200米由磷酸原支付，几乎不费劲；中间1000米靠糖酵解，乳酸一路攀升；最后300米则是有氧系统在工作。让同一位运动员把前200米的配速维持800米试试：磷酸原的水箱见底，糖酵解撑不住那个速率，而有氧系统的贡献到得太慢，补不回来。"   }  },  "Comparing the three systems": {   "sum": [    {     "en": "No activity uses one system. Even a 100 m sprint uses aerobic metabolism — just at a tiny proportion.",     "zh": "没有哪项活动只用一套系统。就算是100米短跑也有有氧代谢参与，只是比例很小。"    },    {     "en": "What changes is the **duration**, and duration is what determines the proportion.",     "zh": "改变的是**持续时间**，而正是持续时间决定了三者的比例。"    },    {     "en": "Under about **10 seconds**, the contribution is almost entirely phosphagen.",     "zh": "短于约**10秒**时，能量贡献几乎全部来自磷酸原。"    },    {     "en": "From roughly **10 seconds to 2 minutes**, glycolysis dominates and lactate accumulates fastest.",     "zh": "从约**10秒到2分钟**，糖酵解占主导，乳酸堆积最快。"    },    {     "en": "Beyond about **2 minutes**, the aerobic system supplies the larger and larger share.",     "zh": "超过约**2分钟**后，有氧系统提供的份额越来越大。"    },    {     "en": "This is why recovery between efforts matters: ATP-PCrresynthesis is **fastest when lactate is low**, and rest is when the tap refills.",     "zh": "这正是组间恢复很重要的原因：乳酸低时磷酸原的再合成**最快**，而休息正是水箱被重新灌满的时候。"    },    {     "en": "The practical test is simple: if effort cannot be repeated at the same rate, the limiting system is glycolytic or aerobic. If it can, it was phosphagen.",     "zh": "有一个简单的判断方法：如果同样的强度无法重复同样的速率，限制系统就是糖酵解或有氧；如果可以，那就是磷酸原。"    }   ],   "analogy": {    "en": "Three cars on the same journey, but with different fuel and different tanks. The sports car refuels in seconds and then has to stop. The saloon is slower but can run a couple of hours. The truck carries enough to cross a country but accelerates like a barge. Nobody asks the truck to win the sprint.",    "zh": "同一段旅程上的三辆车，燃料和油箱各不相同。跑车几秒就能加满油，然后必须停下来；轿车慢一些，但能跑上两个小时；卡车油量足够横穿一个国家，却像驳船一样起步加速。没人会要求卡车去拿短跑冠军。"   },   "example": {    "en": "Interval training works because of the continuum, not despite it. A 400 m rep is glucolytic, so the second rep is harder than the first even with identical pace — the ATP-PCr stores are only partly rebuilt and lactate is still present. Extend the rest and the same rep becomes repeatable, because phosphagen has recovered and lactate has cleared.",    "zh": "间歇训练之所以有效，是因为这个连续体，而不是与它无关。400米的一组属于糖酵解主导，所以即使配速完全相同，第二组也比第一组更难——磷酸原只恢复了一部分，乳酸也还在。把组间休息拉长，同一组就变得可重复，因为磷酸原恢复了，乳酸也清掉了。"   }  },  "VO₂max, movement economy, LIP and EPOC": {   "sum": [    {     "en": "**VO₂max** is the maximum rate the body can take in and use oxygen, and it is the best single laboratory measure of aerobic fitness.",     "zh": "**最大摄氧量**是身体摄取并利用氧气的最大速率，是衡量有氧体能的最好单项实验室指标。"    },    {     "en": "Higher VO₂max means more oxygen arrives at working muscle per minute, so a given pace costs less of your ceiling.",     "zh": "最大摄氧量越高，每分钟到达工作肌肉的氧气就越多，因此同样的配速占用的上限比例就更小。"    },    {     "en": "**Movement economy** is separate from VO₂max. It is how much oxygen a given movement costs — two athletes with identical VO₂max can burn very different amounts doing the same task.",     "zh": "**动作经济性**与最大摄氧量是两回事。它指的是完成某个动作要花多少氧气——两位最大摄氧量完全相同的运动员，做同一件事可以消耗差别很大的氧气。"    },    {     "en": "**Lactate threshold** is the point where lactate begins to build faster than it is cleared, and it is a better predictor of performance than VO₂max for most endurance events.",     "zh": "**乳酸阈**是乳酸产生速度开始超过清除速度的那个点，对大多数耐力项目来说，它比最大摄氧量更能预测表现。"    },    {     "en": "**EPOC** is **excess post-exercise oxygen consumption** — the oxygen debt, repaid after you stop, and the reason heart rate stays up for minutes after a hard effort.",     "zh": "**EPOC**指**运动后过量氧耗**，也就是氧债——它在运动结束后偿还，也正是高强度运动后心率仍会升高好几分钟的原因。"    },    {     "en": "EPOC is why **active recovery** beats sitting still: keeping the muscles working slightly keeps the elevated rate going and clears lactate faster.",     "zh": "这正是**主动恢复**优于完全静止的原因：让肌肉继续轻微活动，可以维持升高的代谢率，并更快清除乳酸。"    },    {     "en": "Together they separate **fitness** (VO₂max, threshold) from **efficiency** (economy) and from **the cost of finishing a session** (EPOC).",     "zh": "三者合起来，把**体能**（最大摄氧量、乳酸阈）、**效率**（动作经济性）和**结束一次训练的代价**（EPOC）区分开来。"    }   ],   "analogy": {    "en": "VO₂max is the size of the **pipes** into the house. Movement economy is how **well the taps are fitted** — same water, less wasted. EPOC is the **debt on the bill** for the water you used, which you pay back long after you stop running the tap.",    "zh": "最大摄氧量是通往房子的**管道口径**；动作经济性则是**水龙头装得好不好**——同样的水，浪费更少；而EPOC就是你用掉的水所欠下的**账单**，在你关掉龙头很久之后才还清。"   },   "example": {    "en": "Two runners finish a 10 km with the same split, but one is cooler and recovers faster. Same threshold, different economy and different EPOC — the first spends less oxygen per step, so less debt is incurred and less has to be repaid afterwards. Over a race that difference is worth seconds, and over a training week it is worth the difference between a third session and a fourth.",    "zh": "两名跑者跑完10公里，配速相同，但其中一位体温更低、恢复更快。乳酸阈相同，动作经济性与EPOC不同——前者每一步花的氧气更少，于是欠下的“账”更少，之后要还的也更少。放在一场比赛里，这个差距值几秒；放在一周训练里，它决定你还能练第三节还是第四节。"   }  },  "Six qualities and FITT": {   "sum": [    {     "en": "A training session is described by **FITT**: frequency, intensity, time and type.",     "zh": "一次训练课由**FITT**四个要素描述：频率、强度、时间和类型。"    },    {     "en": "**Frequency** is how often you train. It matters because recovery takes **24–48 hours** after a session that works a muscle hard.",     "zh": "**频率**指训练多频繁。它之所以重要，是因为一次高强度使用某组肌群后的恢复需要**24到48小时**。"    },    {     "en": "**Intensity** is the hardest to measure honestly. **%HRmax** is too variable day to day, so heart-rate reserve or lactate threshold describe it better.",     "zh": "**强度**是最难诚实测量的。**%最大心率**天与天之间波动太大，所以心率储备法或乳酸阈更能描述它。"    },    {     "en": "**Time** is the duration of the session, and it interacts with intensity: long and hard is a different session from short and hard.",     "zh": "**时间**是单次训练的时长，它与强度相互作用：又长又难和又短又难是两种完全不同的训练。"    },    {     "en": "**Type** is what you actually did — and it is the one most often ignored. Endurance work does not build the same thing as maximal strength work.",     "zh": "**类型**是你实际做的内容，也是最常被忽略的一项。耐力训练和最大力量训练建立的不是同一种东西。"    },    {     "en": "The **six qualities of training** are the goals any programme aims at: strength, endurance, speed, power, agility and flexibility.",     "zh": "**训练的六大品质**是任何训练计划想要达成的目标：力量、耐力、速度、爆发力、敏捷和柔韧。"    },    {     "en": "The point of naming them is that **one session cannot build all six**, and a programme that tries usually over-trains one and neglects the rest.",     "zh": "点出它们的意义在于：**一节训练课不可能同时练成这六项**，而试图全都兼顾的计划，通常只是把其中一项练过头、其余的撂下。"    }   ],   "analogy": {    "en": "FITT is the **recipe card** for a dish, and the six qualities are the **menus you actually cook over a season**. A chef who only ever makes one dish well still has a menu, but no restaurant survives on it.",    "zh": "FITT是菜谱卡，而六大品质是你整个赛季真正做过的菜单。只反复做一道菜的厨师当然也算有菜单，但餐厅靠单一菜式是活不下去的。"   },   "example": {    "en": "A beginner runs three times a week, feels fit within a month, and then stalls. Nothing is wrong with frequency — the type was wrong. Running alone builds aerobic fitness and leaves **strength**, **speed** and **power** untrained, which for most sports is where the biggest gains remain. Two sessions a week spent on those qualities would have cost little and changed everything.",    "zh": "一位初学者每周跑三次，一个月内感觉体能上去了，然后停滞。频率没问题，错的是**类型**。只跑步能练到有氧，而**力量**、**速度**和**爆发力**基本没练——对多数项目来说，那才是提升空间最大的地方。每周花两节课练这几项，代价很小，回报却很大。"   }  },  "Periodization, overload and overtraining": {   "sum": [    {     "en": "**Progressive overload** is the only non-negotiable principle: do a little more than last time, in some measurable way.",     "zh": "**渐进超负荷**是唯一不可谈判的原则：在某个可测量的指标上，比上次多做一些。"    },    {     "en": "**Periodization** is planning that overload on purpose rather than by accident. **Macrocycles** are the big blocks — a season or a phase.",     "zh": "**周期化**是有计划地安排超负荷，而不是碰运气。**大周期**是大的段落，比如一个赛季或一个阶段。"    },    {     "en": "**Mesocycles** are the weeks inside a block, and **microcycles** are the individual sessions.",     "zh": "**中周期**是一个大块内部的若干周，**小周期**则是单次训练课。"    },    {     "en": "A **peaking** phase arrives before competition: volume drops, intensity rises, so the athlete arrives fresh and sharp.",     "zh": "比赛之前会出现一个**巅峰期**：训练量下降、强度上升，让运动员既恢复过来又状态正佳。"    },    {     "en": "Overtraining is usually **accumulation, not one session**. It appears when load rises faster than recovery.",     "zh": "过度训练通常是**累积的结果，而不是某一节课造成的**。它出现在负荷上升快于恢复时。"    },    {     "en": "The early signals are the ones coaches miss: resting heart rate up, sleep worse, mood flat, performance down while fitness holds.",     "zh": "早期信号恰恰是教练最容易忽略的：静息心率升高、睡眠变差、情绪平淡，而体能仍在但表现下滑。"    },    {     "en": "**Acute:chronic workload ratio** compares your last week with your recent average. A spike is not automatically bad, but a spike that keeps climbing is.",     "zh": "**急慢性负荷比**把最近一周和近期平均值作比较。突增本身未必是坏事，但持续攀升的突增就是。"    }   ],   "analogy": {    "en": "Progressive overload is **adding weight to a barbell when you can already lift it cleanly**. If you never add, you never get stronger, and if you add too fast, the bar lands on your chest. Periodization is simply **planning those increases across weeks** instead of discovering them by dropping the bar.",    "zh": "渐进超负荷就像**能干净举起杠铃之后就再加重量**。从不加重量就永远不会变强，加得太快杠铃就会砸到胸口。而周期化不过是**把增量规划到各周里**，而不是靠砸杠铃去发现。"   },   "example": {    "en": "A club squad’s season is one macrocycle. Within it, four weeks of higher volume build fitness, then a lighter week, then the peak: reduced volume, near-maximal intensity. Miss the light week and the final fortnight is the peak plus the accumulated fatigue, which is exactly how a team arrives for its biggest competition already three percent slower than in training.",    "zh": "一支俱乐部队伍的赛季就是一个大周期。其中四周高训练量建立体能，接着一周减量，然后进入巅峰期：量下降、强度接近最大。漏掉那一周减量，最后两周就变成“巅峰期加上累积疲劳”——这正是一支球队在最重要的比赛前就已经比训练时慢3%的原因。"   }  },  "Individualisation and the monitoring loop": {   "sum": [    {     "en": "A programme is a **hypothesis**. You measure, you compare against the model, and you adjust — that loop is the whole job.",     "zh": "训练计划是一个**假设**。你去测量、和模型对照、再做调整——这个循环就是全部的工作。"    },    {     "en": "What is **individualised** is not the plan’s name but its inputs: starting fitness, injury history, schedule, and what the athlete can actually sustain.",     "zh": "被**个体化**的不是计划的名字，而是它的输入：起始体能、伤病史、时间安排，以及这位运动员真正能坚持的量。"    },    {     "en": "**Heart rate** is the workhorse measure, but raw readings are noisy. A trend over **7 days** says far more than any single session.",     "zh": "**心率**是主力指标，但单次读数噪声很大。**7天**的趋势远比任何单节课更有意义。"    },    {     "en": "External load is what you do — distance, volume, sessions. Internal load is what it cost — heart rate, RPE, soreness.",     "zh": "外部负荷是你做了什么——距离、总量、课次；内部负荷是它让你付出了多少——心率、主观用力感觉、肌肉酸痛。"    },    {     "en": "The pair only works together. High external with low internal is adaptation; both high is fatigue; external low with internal high is usually illness or life stress.",     "zh": "两者只有合起来才有用。外部高而内部低是适应；两者都高是疲劳；外部低而内部高通常是生病或生活压力。"    },    {     "en": "**RPE** (rate of perceived exertion) is the cheapest internal measure there is, and the most useful precisely because it needs no equipment.",     "zh": "**主观用力感觉**是最便宜的内部指标，也正因为不需要任何设备而格外有用。"    }   ],   "analogy": {    "en": "Individualisation is **fitting a suit**. The pattern is the same programme for everyone, but the arm length, the shoulder width and the inseam are measured on the person in front of you. A suit cut from the average fits the average perfectly and everybody else badly.",    "zh": "个体化就是**量体裁衣**。纸样是给所有人通用的同一份计划，但袖长、肩宽和裤长是照着你面前这个人量的。按平均体型裁的衣服，只有平均身材穿着完美，其他所有人都很别扭。"   },   "example": {    "en": "Two footballers are given the same 8 × 400 m session. The first finishes the final rep at 165 bpm; the second at 188. Same session, same intent, and the coach now knows the second athlete is under-recovered and that the next session must be reduced. Without the internal measure the coach would have logged “session completed” for both and learned nothing until the injury.",    "zh": "两名足球运动员被安排同样的8 × 400米训练。第一位最后一组结束时心率165次/分，第二位188次/分。同样的课、同样的意图，而教练现在知道第二位恢复不足、下一节必须减量。如果没有这个内部指标，教练只会为两人各记上一句“训练已完成”，直到伤病出现才学到东西。"   }  },  "Life stage, sex and energy balance": {   "sum": [    {     "en": "Energy balance is simple arithmetic: energy in versus energy out. **Surplus** stores as fat, **deficit** draws on it, and **balance** holds it steady.",     "zh": "能量平衡是一道简单算术：摄入减去消耗。**盈余**储存为脂肪，**亏空**动用脂肪，**平衡**则保持不变。"    },    {     "en": "The **basal metabolic rate** is what you burn just to stay alive, and it typically falls by about **1–2% per decade** from adulthood.",     "zh": "**基础代谢率**是维持生命本身所需消耗，从成年开始通常每十年下降约**1到2%**。"    },    {     "en": "**Thermogenic effect of food** is the cost of digesting what you eat, around **10%** of intake, and it varies with how much protein the meal contains.",     "zh": "**食物热效应**是消化食物本身的开销，约占摄入的**10%**，并随一餐中蛋白质含量而变化。"    },    {     "en": "**Energy balance changes across the lifespan**: children grow, adolescent growth spurts raise needs sharply, and needs fall again in later life.",     "zh": "**能量平衡会随生命阶段改变**：儿童在生长，青少年生长突增使需求急升，而成年后期需求再次下降。"    },    {     "en": "**Sex** changes the equation mainly through body composition and hormones, which is why energy prescriptions are not a single number for all.",     "zh": "**性别**主要通过身体成分和激素改变这道等式，因此能量建议不是对所有人都通用的一个数字。"    },    {     "en": "The practical error is **underestimating expenditure**. Added training, spontaneous activity and the thermic effect of a larger diet are all easy to leave out of the account.",     "zh": "实践中最常见的错误是**低估消耗**。增加了训练、自发活动，以及更大饮食带来的食物热效应，都很容易被漏算。"    }   ],   "analogy": {    "en": "Energy balance is a **bank account with two sides**: deposits and withdrawals. You do not go negative by spending much once — you go negative by repeatedly misjudging the withdrawals. An athlete who “eats the same as before” after adding three sessions a week is not in balance; the deposits did not move.",    "zh": "能量平衡是一个**有两边的银行账户**：存入和支取。你不会因为偶尔多花一点就透支；你透支是因为反复低估了支取量。一位每周增加三节课之后仍然“和以前吃一样”的运动员并不处于平衡——因为存入那一侧根本没动。"   },   "example": {    "en": "An athlete adds two evening sessions a week, keeps her food diary identical, and expects weight to hold. Expenditure has risen by several hundred kilocalories a week and intake has not moved, so the balance tips gradually — too slowly to notice week to week and too consistently to argue with over a season. The correct response is to measure, not to cut harder.",    "zh": "一位运动员每周增加两节晚间训练，饮食记录保持不变，指望体重不变。消耗每周上升了几百千卡而摄入没动，于是平衡被一点点推向亏空——逐周看不出来，但整个赛季累积下来足以推翻任何争辩。正确的应对是去测量，而不是更狠地节食。"   }  },  "System benefits, chronic disease and progression": {   "sum": [    {     "en": "Exercise is a **multisystem** intervention. The heart, the vessels, the lungs, the bones, the muscles and the brain all respond, and not to the same dose.",     "zh": "运动是一种**多系统**干预。心脏、血管、肺、骨骼、肌肉和大脑都会响应，而且所需的剂量并不相同。"    },    {     "en": "The strongest and most consistent effect is on **cardiovascular risk**: lower blood pressure, better lipids, and improved endothelial function.",     "zh": "最稳定、也最一致的作用在**心血管风险**上：血压更低、血脂更好、内皮功能改善。"    },    {     "en": "Insulin sensitivity improves with almost any activity that engages large muscle mass, which is why **resistance work** matters as much as aerobic work here.",     "zh": "只要动用大肌群，胰岛素敏感性就会改善，因此在这方面**抗阻训练**和 aerobic 训练同样重要。"    },    {     "en": "Bone is **specific-adaptive**: it responds to impact and to unusual loading, so the exercise that builds bone is the one that feels unfamiliar.",     "zh": "骨骼遵循**特异适应**原则：它对冲击和不寻常的负荷产生反应，因此真正能练到骨的运动，是那种感觉不熟悉的运动。"    },    {     "en": "Chronic disease changes the prescription, not the principle. The aim is still overload progression, but the starting point is lower and the monitoring is closer.",     "zh": "慢性病改变的是处方，不是原则。目标仍然是超负荷递进，只是起点更低、监测更密。"    },    {     "en": "**Inflammation** falls with regular activity and rises with inactivity, which is why the daily habit matters more than the single heroic session.",     "zh": "规律活动会降低**炎症**水平，久坐则使它升高，因此日常习惯比某次拼命的训练更重要。"    }   ],   "analogy": {    "en": "Training adaptations are **specific**. A runner who only runs builds a runner: strong aerobic capacity, and bones and tendons that have been asked for nothing unusual. Add lifting and suddenly the bones and the connective tissue get a different instruction — and that is the point.",    "zh": "训练适应是**有特异性的**。只跑步的跑者会练成一个跑者：有氧能力很强，而骨骼和肌腱从未被要求做任何不寻常的事。加上举重，骨骼和结缔组织突然收到了不同的指令——而这正是重点。"   },   "example": {    "en": "A hypertensive 58-year-old walks 30 minutes five days a week and lifts twice. The walking alone moves blood pressure and lipids; the lifting is what protects bone density and keeps glucose handling sharp. Remove the lifting and the programme becomes a good cardiovascular intervention with a silent cost to bone — the kind of cost that only shows up as a fracture twenty years later.",    "zh": "一位58岁的高血压患者每周五天快走30分钟，加每周两次举重。快走本身改善血压和血脂；而举重才保护骨密度、维持血糖处理能力。去掉举重，这个计划就变成一个很好的心血管干预，却给骨骼留下了一笔看不见的账——而这笔账往往二十年后才以骨折的形式出现。"   }  },  "HL exercise prescription for populations": {   "sum": [    {     "en": "An **HL** prescription must be specific enough to be tested. Vague advice cannot be measured, so it cannot be adjusted.",     "zh": "**高阶（HL）**运动处方必须具体到可以被检验。含糊的建议无法测量，也就无法调整。"    },    {     "en": "**Pre-exercise screening** is the first step. Risk is judged from current activity level, not age alone.",     "zh": "**运动前筛查**是第一步。风险要依据**当前活动水平**判断，而不能只看年龄。"    },    {     "en": "**Overriding symptoms** matter more than any number: chest pain, unexplained breathlessness, dizziness, palpitations.",     "zh": "**危险信号**比任何数字都重要：胸痛、不明原因的气促、头晕、心悸。"    },    {     "en": "**FITT must be justified**, not defaulted. Intensity is chosen from a test — often a **one-mile walk test** or a submaximal HR estimate.",     "zh": "**FITT必须有依据**，而不是照搬默认值。强度来自某项测试——常用**一分钟步行试验**或次极量心率估算。"    },    {     "en": "**Progression** is the mechanism of the programme, so it is written into the prescription rather than left to chance.",     "zh": "**递进**是这个计划的机制，因此必须写进处方里，而不是交给运气。"    },    {     "en": "Population prescriptions carry two responsibilities: the intensity must suit the person, and the programme must be **individually appropriate** for that person’s goals.",     "zh": "人群处方承担两项责任：强度要适合这个人，而计划必须**因人制宜**，切合此人的目标。"    }   ],   "analogy": {    "en": "A prescription is a **route drawn on a map, not a slogan**. “Exercise more” is a slogan. “30 minutes brisk walking, 5 days, intensity so that talking is difficult, progress by 5 minutes per week” is a route — someone can follow it, and someone can check whether it worked.",    "zh": "处方是**地图上画出的路线，而不是一句口号**。“多运动”是口号；“每周五天、每次快走30分钟，强度到说话费劲，每周增加5分钟”才是路线——有人能照着走，也有人能核查是否有效。"   },   "example": {    "en": "A sedentary 45-year-old with high blood pressure. Screening shows regular activity and no overriding symptoms, so testing continues. A submaximal test sets intensity; the starting prescription is 20 minutes on 5 days with a clear progression rule. At the 6-week review the walking time increases only if blood pressure, rate of perceived exertion and adherence all allow it — the test comes before the progression.",    "zh": "一位久坐的45岁高血压患者。筛查显示他有规律活动且无危险信号，于是继续做测试。用次极量测试确定强度；起始处方是每周五天、每天20分钟，并附带明确的递进规则。第6周复查时，只有当血压、主观用力感觉和依从性都允许时才增加步行时间——测试走在递进前面。"   }  },  "Central and peripheral fatigue": {   "sum": [    {     "en": "**Fatigue** is reversible performance loss from exercise, and it is useful to split it by **where in the body it is generated**.",     "zh": "**疲劳**是运动造成的、可逆的表现下降，按**在身体的哪个部位产生**来分类会很有用。"    },    {     "en": "**Central fatigue** is cognitive: reduced motivation, slower decisions, lower perceived effort. Its mechanisms are still debated.",     "zh": "**中枢疲劳**是认知层面的：动力下降、决策变慢、主观努力感降低。其机制仍在争论中。"    },    {     "en": "Because perceived effort is central, the athlete usually reports it before the muscles actually fail — and that self-report is often accurate.",     "zh": "由于主观努力感属于中枢，运动员往往在肌肉真正力竭之前就先报告疲劳——而这种自报通常相当准确。"    },    {     "en": "**Peripheral fatigue** is muscular: accumulated metabolites, altered ion balance, and substrate depletion. Power output falls even when effort still feels high.",     "zh": "**外周疲劳**是肌肉层面的：代谢物累积、离子平衡改变、基质耗竭。即使主观努力感仍然很高，功率输出已经下降。"    },    {     "en": "The **interference effect** is central fatigue limiting peripheral performance — the head telling the muscles to stop before the muscle itself is out.",     "zh": "**干扰效应**指中枢疲劳限制外周表现——大脑在肌肉自己还没用尽之前就命令它停下。"    },    {     "en": "**Central fatigue** is best reduced by sleep, easy movement and daylight; **peripheral** fatigue by active recovery, refuelling and mobility work.",     "zh": "**中枢疲劳**最有效的恢复是睡眠、轻松活动和日照；**外周疲劳**则靠主动恢复、补充燃料和灵活性练习。"    },    {     "en": "Grouping strength, speed and power in the same session creates **peripheral** fatigue, which then raises the **central** component — which is why power quality drops faster than strength.",     "zh": "把力量、速度和爆发力放在同一节课，会制造**外周**疲劳，而它又会推高**中枢**成分——这就是为什么爆发力的质量掉得比力量更快。"    }   ],   "analogy": {    "en": "Central and peripheral fatigue are a **referee and the legs**. The referee decides how hard the effort looks and how long the runner pushes; the legs decide whether they can still deliver. When the legs are gone but the runner still judges it “easy”, something is wrong. When the referee calls it quits while the legs are fine, that is central fatigue.",    "zh": "中枢与外周疲劳像是**裁判和双腿**。裁判决定这段努力看起来有多吃力、跑者会坚持多久；双腿决定还能不能交付。当双腿已经没了，跑者却还觉得“轻松”，那就出问题了；而裁判在双腿没问题时鸣哨结束，那就是中枢疲劳。"   },   "example": {    "en": "An athlete completes a heavy strength session and then tries to add 10 km on a treadmill. Peripheral fatigue from the lifting means the legs simply cannot deliver the power. But the athlete usually blames the treadmill, rates the session “easy”, and drops the extra work entirely — losing the aerobic stimulus and never diagnosing a recoverable problem.",    "zh": "一位运动员做完高强度力量训练后，想再加10公里跑台。外周疲劳让双腿根本无法输出功率。但运动员往往会怪跑台、把训练评价为“轻松”，然后彻底放弃这部分——既丢掉了有氧刺激，也从未诊断出一个本来完全可以恢复的问题。"   }  },  "Recovery nutrition and methods": {   "sum": [    {     "en": "**Protein** needs to be spread: roughly **1.6–2.0 g per kilogram per day** for most training, and about **0.3 g per kilogram per meal** to actually trigger muscle protein synthesis.",     "zh": "**蛋白质**需要分散摄入：多数训练者每天每公斤体重约**1.6到2.0克**，而每一餐约**每公斤0.3克**才真正触发肌肉蛋白合成。"    },    {     "en": "**Carbohydrate** refills glycogen. The target is about **1.0–1.2 g per kilogram per hour** in the first hours after a session.",     "zh": "**碳水化合物**用来补糖原。训练后最初几小时的目标约为**每小时每公斤1.0到1.2克**。"    },    {     "en": "**Fluid and sodium** replace sweat. Aim to lose no more than about **2% of body mass**, and weigh before and after to know your own rate.",     "zh": "**液体和钠**用来补回汗液。目标是不超过约**体重的2%**，并在训练前后称重以掌握自己的出汗速率。"    },    {     "en": "**Active recovery** — easy movement after a session — speeds lactate clearance without adding fatigue.",     "zh": "**主动恢复**——训练后轻松活动——能在不增加疲劳的前提下加快乳酸清除。"    },    {     "en": "**Massage, compression and cold water immersion** all reduce soreness. The evidence for lasting performance benefit is weaker than the evidence for feeling better.",     "zh": "**按摩、压力压缩和冷水浸泡**都能减轻酸痛。但它们带来持久表现提升的证据，远弱于“感觉好些了”的证据。"    },    {     "en": "**Sleep** is the one recovery tool with no credible substitute, because growth hormone release and tissue repair concentrate in deep sleep.",     "zh": "**睡眠**是唯一没有可信替代品的恢复工具，因为生长激素的释放与组织修复集中在深度睡眠期。"    }   ],   "analogy": {    "en": "Recovery is **repaying three different loans**. You owe a fuel loan (**glycogen**), a building loan (**protein**) and a water loan (**fluid and sodium**). They are paid off with different currencies, on different timescales, and paying one does not clear another. Which is why “ate a big meal” is not a recovery plan.",    "zh": "恢复就像**还三种不同的债**：一笔燃料债（**糖原**）、一笔建材债（**蛋白质**）、一笔水债（**液体和钠**）。它们用不同的货币、在不同的时间尺度上偿还，还清其中一笔并不会自动清掉另一笔。这就是为什么“吃了一顿大餐”不构成一个恢复方案。"   },   "example": {    "en": "A footballer finishes a match, weighs himself, and finds he is 1.8 kg lighter on a 78 kg body — about 2.3%. He drinks a sports drink but eats nothing, then sleeps. He wakes feeling reasonable and plays a full training week on stored glycogen, because the fuel loan was never cleared. Same athlete, same recovery window, but the difference is a sandwich.",    "zh": "一名足球运动员踢完比赛一称，重了1.8公斤，而他的体重是78公斤——约2.3%。他喝了一瓶运动饮料，却什么都没吃，然后睡下。他醒来感觉还行，于是在仍然欠着糖原的情况下打了一整周训练。同一个人、同样的恢复窗口，差别就在一个三明治。"   }  },  "Recovery indicators, sleep and travel": {   "sum": [    {     "en": "Recovery is what you **measure**, not what you hope for. Without a marker you are guessing, and guessing does not adapt to your schedule.",     "zh": "恢复是你**测量**到的东西，不是你希望它发生的事。没有指标就只是在猜，而猜测不会跟着你的作息调整。"    },    {     "en": "The practical markers are **resting heart rate**, **HRV**, sleep quality and duration, **soreness**, mood, and performance on a standard test.",     "zh": "实用的指标是**静息心率**、**心率变异性**、睡眠质量与时长、**肌肉酸痛**、情绪，以及一项标准测试中的表现。"    },    {     "en": "**HRV** is the most sensitive of them, because it reflects autonomic balance — and it is the one that falls before you notice.",     "zh": "**心率变异性**是其中最敏感的，因为它反映自主神经平衡——而且它总是在你察觉之前就先掉下去。"    },    {     "en": "**Resting heart rate** is cruder but far easier to take. A rise of **5–10 bpm** above your own baseline is a common early warning.",     "zh": "**静息心率**更粗糙但容易测得多。比自己的基线高出**5到10次/分**，是一个常见的早期预警。"    },    {     "en": "**Sleep** is the highest-yield recovery variable: extension can help, and even a nap of **30–60 minutes** can offset a short night.",     "zh": "**睡眠**是回报最高的恢复变量：延长睡眠确实有帮助，而**30到60分钟**的一次小睡甚至可以抵消一个短夜。"    },    {     "en": "**Travel** adds three problems at once: displaced sleep, changed time zones, and disrupted food timing. Jet lag is mostly a light problem.",     "zh": "**旅行**同时带来三个问题：睡眠被打乱、时区改变、进餐时间中断。时差反应主要是一个光照问题。"    },    {     "en": "So the practical response to travel is **light and meal timing first**, training load second — and one bad night is not evidence that the athlete is detraining.",     "zh": "所以应对旅行的实用做法是**先调光照和进餐时间，再调训练量**——而一个糟糕的夜晚并不是运动员正在退化的证据。"    }   ],   "analogy": {    "en": "Recovery monitoring is a **dashboard warning light**. You do not need to know why the engine is overheating to know you should stop and check the coolant. A rising resting heart rate is that light: it tells you something changed, and it does not require you to diagnose it before acting on it.",    "zh": "恢复监测就像**仪表盘上的警示灯**。你不必知道发动机为什么过热，也知道该停下来检查冷却液。上升的静息心率就是那盏灯：它告诉你有东西变了，而且不要求你先诊断清楚才采取行动。"   },   "example": {    "en": "A swimmer crosses five time zones. On arrival her resting heart rate is 8 bpm above baseline and her morning HRV is down. Her coach could either ignore it or train her through it. The markers argue for one light day, no hard sets, normal meal timing, and strong morning light exposure — and by day three the numbers return to baseline and training resumes.",    "zh": "一位游泳运动员跨越五个时区。到达后她的静息心率比基线高8次/分，早晨心率变异性也下降。教练可以无视，也可以硬练。而这些指标支持的做法是：先安排一天轻松训练、不上高强度课、保持正常进餐时间、并加强晨间光照——到第三天数值回到基线，训练即可恢复。"   }  },  "Skeleton, position and directional terms": {   "sum": [    {     "en": "The **skeleton** is a framework of 206 bones that carries weight, protects organs and stores minerals. Its shape decides where muscle can pull and where a break is most likely.",     "zh": "**骨骼**是由206块骨头构成的框架，承担重量、保护器官并储存矿物质。它的形态决定了肌肉可以从哪里发力，也决定了骨折最容易发生在哪里。"    },    {     "en": "Everyone is described from the same reference: standing upright, feet together, arms at your sides and palms facing forward. That is the **anatomical position**, and every directional term is measured from it.",     "zh": "所有人都以同一个参照姿势来描述：直立、双脚并拢、双臂置于体侧、手掌朝前。这就是**解剖学姿势**，所有方位术语都以此为基准。"    },    {     "en": "Terms come in pairs and each pair is a **contrast**: superior/inferior, anterior/posterior, medial/lateral, proximal/distal, superficial/deep.",     "zh": "术语总是成对出现，每一对都是**对照关系**：上/下，前/后，内/外，近/远，浅/深。"    },    {     "en": "The pairs are not interchangeable. The knee is **proximal** to the ankle and **distal** to the hip; the kneecap is **anterior** to the femur and **superior** to the tibia.",     "zh": "这些词不能互换。膝关节位于踝关节的**近端**、髋关节的**远端**；髌骨位于股骨的**前方**、胫骨的**上方**。"    },    {     "en": "So a hamstring strain is described precisely: a tear in the muscle **posterior** to the femur and **proximal** to the knee. The words carry the location.",     "zh": "所以腘绳肌拉伤可以被精确描述：大腿**后方**、膝关节**近端**的肌肉撕裂。这些术语本身就承载了位置信息。"    }   ],   "analogy": {    "en": "Directional terms are a map legend, not a decoration. North and south only mean something because everyone agrees which way is north — and the body only works because everyone agrees which way is anterior.",    "zh": "方位术语就像地图图例，而不是装饰。南北只有在大家一致认为哪边是北的时候才有意义；而人体之所以能被描述，正是因为大家一致约定哪边是前方。"   },   "example": {    "en": "A physio reads a scan note that says the injury is on the lateral side of the knee. Lateral means away from the midline, so the outside edge — not the inside, which would be medial. One word halves the search area.",    "zh": "理疗师读到一份报告，说损伤位于膝关节的外侧。外侧（lateral）指远离身体中线，因此是外缘，而不是内侧（medial）。一个词就把搜索范围减半。"   }  },  "Planes, axes and movement": {   "sum": [    {     "en": "Every movement happens in, or across, one of three **planes** — and each plane has one axis perpendicular to it.",     "zh": "每一个动作都发生在某一个**平面**内或跨越某个平面，而每个平面都有一个与之垂直的**轴**。"    },    {     "en": "**Sagittal** divides left from right (the axis runs front to back). Flexion and **extension** happen here: bending and straightening.",     "zh": "**矢状面**把身体分成左右两部分（轴线由前向后）。屈曲与**伸展**在此发生：即弯曲与伸直。"    },    {     "en": "**Frontal** divides front from back (the axis runs side to side). **Abduction** and **adduction** happen here: moving a limb away from, or toward, the midline.",     "zh": "**额状面**把身体分成前后两部分（轴线由左向右）。**外展**与**内收**在此发生：肢体远离或靠近中线。"    },    {     "en": "**Transverse** divides top from bottom (the axis runs vertically). Rotation happens here — twisting the trunk, or rotating the shoulder.",     "zh": "**水平面**把身体分成上下两部分（轴线垂直向上）。旋转在此发生——躯干的扭转或肩关节的旋转。"    },    {     "en": "Most real movement is **multiplanar**. A tennis serve is not one action; it is a chain that winds through all three planes, and a knee that only works in one of them is a knee that will not last a season.",     "zh": "大多数实际动作都是**多平面**的。网球发球不是单一动作，而是一条穿越三个平面的动作链；只能在一个平面上工作的膝关节，撑不过一个赛季。"    }   ],   "analogy": {    "en": "Planes are the three sheets of a transparent folder, and the axes are the three rods that pass through it. A movement that stays in one plane is a line drawn on one sheet; a sprint that changes direction is the pen jumping between sheets.",    "zh": "平面就像透明文件夹里的三张纸，而轴就是穿过它的三根杆。只在一个平面内的动作，是画在其中一张纸上的一条线；而改变方向的冲刺，就相当于笔在三张纸之间跳动。"   },   "example": {    "en": "When a clinician asks why a hamstring tears, the answer is usually about the hip: sprinting extends the hip in the sagittal plane and swings it forward again, so the muscle is asked to control its own length while it is lengthening. The plane tells you which movement to test.",    "zh": "当临床人员追问腘绳肌为何撕裂时，答案通常与髋关节有关：冲刺时髋关节在矢状面内伸展，随后又向前摆回，因此这块肌肉必须在被拉长的同时控制自身长度。平面信息告诉你该测试哪一个动作。"   }  },  "HL anthropometry and ergonomics": {   "sum": [    {     "en": "**Anthropometry** is the measurement of the human body. Static measures (stature, limb lengths, masses) set the frame; girths and skinfolds describe the tissue on that frame.",     "zh": "**人体测量学**是对人体的测量。静态测量值（身高、肢长、体重）构成基本框架；而围度和皮褶则描述这个框架上的组织量。"    },    {     "en": "Body mass alone is a poor description. A percentile table is better because it compares you with same-age, same-sex peers rather than with an absolute scale.",     "zh": "单看体重是很差的描述方式。百分位表更好，因为它把你与同龄同性别的人群相比，而不是与一个绝对标准相比。"    },    {     "en": "**Ergonomics** applies those measurements to the task: can this person, with these dimensions, do this job repeatedly without exceeding their tissue capacity?",     "zh": "**人体工程学**把这些测量值应用于任务：具备这些身体尺寸的人，能否反复完成这项工作而不超过其组织承受限度？"    },    {     "en": "The classic worked example is the desk-chair-height problem. A work surface fixed at one height suits a percentile range; outside it, the shoulder and the low back take the compensation.",     "zh": "经典的例子是桌与椅的高度问题。固定在某一高度的桌面只适合某个百分位区间；超出该区间，肩部和下背部就要承担代偿。"    },    {     "en": "Equipment design, protective padding and load prescription are all the same idea applied at different scales: match the demand to the capacity, and redesign the demand where you cannot change the capacity.",     "zh": "器材设计、防护护具和负荷处方，本质上是同一个理念在不同尺度上的应用：让需求匹配能力；当能力无法改变时，就重新设计需求。"    }   ],   "analogy": {    "en": "Ergonomics is a translation problem. The body says what it can sustain; the equipment was designed around an average person that nobody actually is. Every awkward movement on a court or in a clinic is an untranslated sentence.",    "zh": "人体工程学是一道翻译题。身体说明了自己能承受什么，而器材却是围绕着一个并不存在的“平均人”设计的。球场或诊室里每一个别扭的动作，都是一句没有翻译好的话。"   },   "example": {    "en": "A goalkeeper whose arm span exceeds their standing height can reach a higher crossbar than one whose span does not. Nothing about that goalkeeper changed — the measurement explains why the clearance looks routine for them and impossible for a shorter keeper on the same crossbar.",    "zh": "一名臂展超过身高的守门员，能比臂展不足的守门员够到更高的横梁。他本人没有任何改变——这个测量值解释了为什么同样的横梁对他来说轻松，而对更矮的守门员却几乎不可能。"   }  },  "Connective tissues and articulations": {   "sum": [    {     "en": "Bone is not the only tissue in the system. Four connective tissues do the structural work, and each one has one dominant property.",     "zh": "系统中并非只有骨组织。承担结构功能的是四种结缔组织，每一种都有其主导属性。"    },    {     "en": "**Ligament** — bone to bone, and the constraints are always tight. It is what stops the knee hyperextending and the elbow hyperextending.",     "zh": "**韧带**——连接骨与骨，其约束始终很紧。它阻止膝关节与肘关节过度伸展。"    },    {     "en": "Tendon — muscle to bone, transmits the pull, and is comparatively compliant so it can store and return elastic energy.",     "zh": "**肌腱**——连接肌肉与骨，传递拉力，且相对柔顺，因此能够储存并回弹弹性势能。"    },    {     "en": "Cartilage — takes load with very low friction and has no blood supply of its own, so it heals slowly. Articular cartilage is the surface that wears.",     "zh": "**软骨**——承受负荷且摩擦极低，本身没有血供，因此修复缓慢。关节软骨就是会磨损的表面。"    },    {     "en": "An **articulation** is simply any joint where two bones meet, whether or not it actually moves. Most of the 206 bones articulate somewhere; only a minority are freely mobile.",     "zh": "**关节**就是两块骨相接之处，无论它是否真的能动。206块骨中的大多数都存在关节连接，只有少数是高度活动的。"    }   ],   "analogy": {    "en": "Ligament is a rope tied between two posts, tendon is a rope tied to a motor, and cartilage is the greased slider between them. A rope will not stretch; a motor drive will.",    "zh": "韧带像是两根柱子之间系的绳索，肌腱像是连在马达上的绳索，而软骨就是它们之间上了润滑脂的滑块。绳索不会伸长，马达的传动轴会。"   },   "example": {    "en": "Landing from a jump, the quadriceps tendon has to transmit several times body weight while the patella presses into the femoral groove. When the landing foot rolls inward, the patella is pushed sideways off that groove and the tendon is asked to carry load it was never aligned for.",    "zh": "跳跃落地时，股四头肌肌腱要传递数倍体重的负荷，同时髌骨正压在股骨滑车槽内。当落地时足部内翻，髌骨被推向滑车槽的一侧，肌腱被迫承担它从未被设计过的受力方向。"   }  },  "Synovial structure and joint classes": {   "sum": [    {     "en": "A **synovial joint** is a solved engineering problem: bone-on-bone contact must carry load, but bone rubbing on bone would wear out in years.",     "zh": "**滑膜关节**是一个已被解决的工程问题：骨与骨直接接触必须承重，但骨与骨摩擦会在数年内磨毁。"    },    {     "en": "The solution is five parts: articular cartilage to spread the load, **synovial fluid** to lubricate, a joint capsule to contain the joint, ligaments to restrict it, and accessory ligaments for extra stability.",     "zh": "解决方案由五部分构成：铺展负荷的关节软骨、起润滑作用的**滑液**、包裹关节的关节囊、限制活动的韧带，以及提供额外稳定的副韧带。"    },    {     "en": "Joints are then sorted by how much movement they allow: **arthrodial** (gliding, e.g. the vertebrae), **ginglymus** (a hinge, e.g. the elbow), and **enarthrodial** (ball and socket, e.g. the shoulder).",     "zh": "随后按允许的活动幅度对关节分类：**平面关节**（如椎骨间的滑动）、**铰链关节**（如肘关节）和**球窝关节**（如肩关节）。"    },    {     "en": "Shoulder mobility is bought with **stability** — it has no bony lock at all. Hip is the opposite: deep socket, powerful muscles, far less range.",     "zh": "肩关节的活动度是用**稳定性**换来的——它完全没有骨性锁定。髋关节正相反：髋臼深陷，肌肉强大，活动范围小得多。"    },    {     "en": "That trade is why the shoulder dislocates forward and down, and why an anterior shoulder problem is almost always a stability problem before it is a strength problem.",     "zh": "这种取舍正是肩关节容易向前下方脱位的原因，也是肩关节前方问题几乎总是稳定性问题、而非力量问题的原因。"    }   ],   "analogy": {    "en": "A synovial joint is a drawer that has to slide silently and hold heavy things at the same time. The rails are cartilage, the grease is synovial fluid, the frame is the capsule, and the stops are the ligaments.",    "zh": "滑膜关节就像一个既要滑动无声、又要承重的抽屉。滑轨是软骨，润滑脂是滑液，框架是关节囊，限位装置就是韧带。"   },   "example": {    "en": "Throwing a cricket ball maximally would need the shoulder to rotate roughly 180 degrees. It can, because the ball arm can sacrifice stability for that range. The cost is that almost all of that rotation is muscle-held, so a rotator cuff that is not working leaves the joint relying on ligaments that were never meant to carry that load.",    "zh": "全力投掷板球需要肩关节旋转约180度。它能做到，是因为投掷臂可以用稳定性换取这个活动范围。代价是其中几乎全部旋转都由肌肉维持，因此一旦肩袖失效，关节就只能依赖那些本不该承担此类负荷的韧带。"   }  },  "Mobility, stability and injury": {   "sum": [    {     "en": "The useful way to think about a joint is the trade it makes: range of movement bought against control. Neither end of that trade is safe on its own.",     "zh": "理解关节的实用方式，是看它做出的取舍：以控制能力换取活动范围。这个取舍的两端单独看都不安全。"    },    {     "en": "Too little **mobility** and the body compensates somewhere else — a stiff hip turns into a low back that twists, and a stiff ankle turns into a knee that collapses inward.",     "zh": "**活动度**不足，身体就会在别处代偿——僵硬的髋关节会变成会扭转的下背部，僵硬的踝关节会变成内翻塌陷的膝关节。"    },    {     "en": "Too little **stability** and the joint moves somewhere it was never meant to. That is a sprain, a subluxation or a dislocation, and it is a mechanical event rather than a weakness of character.",     "zh": "**稳定性**不足，关节就会向它本不应到达的方向移动。结果是扭伤、半脱位或脱位——这是力学事件，而不是意志薄弱。"    },    {     "en": "The two extremes also present differently over time: instability tends to be acute and obvious, whereas lost mobility builds slowly and is often mistaken for age or for stubbornness.",     "zh": "这两种极端在表现上也不同：不稳定通常来势突然且症状明显；而活动度丧失则发展缓慢，常被误认为是年纪大了或性格固执。"    },    {     "en": "Assessment therefore has to ask both questions in the same session: can this joint go where it should, and can it stay where it should?",     "zh": "因此评估必须在同一次检查中同时问两个问题：这个关节能否到达应有的范围，以及能否保持在应有的位置？"    }   ],   "analogy": {    "en": "A joint is a door on a hinge. Too little mobility is a door painted shut; too little stability is a door with no latch. Neither a jammed door nor a door that swings into the wall is a safe door.",    "zh": "关节就是带铰链的门。活动度不足是门被漆死了；稳定性不足是门没有门闩。卡死的门和会撞上墙的门，都不是安全的门。"   },   "example": {    "en": "A ballet dancer with a restricted ankle dorsiflexion will still be able to land, but will land with the knee collapsing inward on every take-off. The ankle was the stiff joint; the knee pays for it on every rep.",    "zh": "一名踝背屈受限的芭蕾舞者仍然可以落地，但每次起跳都会让膝关节向内塌陷。僵硬的是踝关节，而膝关节要为每一次重复付出代价。"   }  },  "Motor units and fibre types": {   "sum": [    {     "en": "A **motor unit** is one motor neurone plus every muscle fibre it reaches. The brain's control system is built from this repeating unit, not from single cells.",     "zh": "**运动单元**是一个运动神经元及其支配的所有肌纤维。大脑的运动控制系统正是由这个可重复的单元构成，而不是由单个细胞构成。"    },    {     "en": "Motor neurones are sorted by size, and size decides recruitment order: small first, large last. This is **Henneman's size principle**.",     "zh": "运动神经元按直径分类，而直径决定募集顺序：先小后大。这就是**赫纳曼尺寸原则**。"    },    {     "en": "So light loads are handled by small units with slow, fatigue-resistant **type I** fibres; heavy loads recruit large units with fast **type IIx** fibres.",     "zh": "因此，轻负荷由小运动单元中的慢速、耐疲劳的**I型**纤维承担；大负荷则募集含快速**IIx型**纤维的大运动单元。"    },    {     "en": "Human skeletal muscle has types I, IIa and IIx. There is **no IIb** in humans — IIb is a rodent type; what textbooks call 2B in humans is IIx.",     "zh": "人体骨骼肌含有I型、IIa型和IIx型。人类**没有IIb型**——IIb是啮齿动物的类型；教科书在人体中所称的2B型实为IIx型。"    },    {     "en": "The functional consequence: **hypertrophy** comes from recruiting high-threshold units, and **atrophy** shows first in the low-threshold ones — which is why a casted limb loses the small, slow fibres before the fast ones.",     "zh": "功能上的推论是：**肌肥大**来自高阈值运动单元的募集，而**萎缩**最先出现在低阈值的那些单元——这正是石膏固定肢体时，慢速小纤维比快速纤维先萎缩的原因。"    }   ],   "analogy": {    "en": "A motor unit is one foreman with a gang of builders. The foreman only calls in the big crews when the job genuinely needs them, so a small job never wakes the most expensive crew.",    "zh": "运动单元就像一位工头带着一队建筑工人。工头只有在活儿确实需要时才会召集大队伍，因此小活儿从来不会惊动最昂贵的那支队伍。"   },   "example": {    "en": "Holding a racket still needs only a handful of small type I units, so fatigue is minimal. The final overhead smash recruits the large IIx units, and those are the ones that generate lactate and that take longest to recover.",    "zh": "稳稳握住球拍只需要少量小型I型运动单元，因此几乎不会疲劳。而最后一记头顶扣杀会募集大型IIx单元，正是这些单元产生乳酸、且恢复最慢。"   }  },  "Contractions and muscle interaction": {   "sum": [    {     "en": "A muscle does not simply get shorter. It changes **tension** while it is changing length, and the kind of work it is doing depends on which of the two is happening.",     "zh": "肌肉并非简单地变短。它在改变长度的同时改变**张力**，而它所做的功取决于这两者中哪一个正在发生。"    },    {     "en": "**Concentric**: the muscle shortens against a load and does positive work — lifting, pushing, accelerating.",     "zh": "**向心收缩**：肌肉在负荷作用下缩短并做正功——如举起、推、加速。"    },    {     "en": "**Eccentric**: the muscle lengthens while still under tension and absorbs energy — braking, lowering, landing.",     "zh": "**离心收缩**：肌肉在仍有张力的情况下被拉长并吸收能量——如制动、下放、落地。"    },    {     "en": "**Isometric**: length and joint angle do not change, but tension rises — the plank, the wall sit, the mid-lift hold.",     "zh": "**等长收缩**：长度与关节角度都不变，但张力上升——如平板支撑、靠墙静蹲、动作中途的保持。"    },    {     "en": "The interactions matter because most movements are combinations: the **quadriceps** is **concentric** on the way up, **eccentric** on the way down, and **isometric** for a beat at the bottom of a squat.",     "zh": "这些相互作用之所以重要，是因为大多数动作都是它们的组合：**股四头肌**在上蹲时**向心**、在下蹲时**离心**，并在蹲底停留片刻做**等长**收缩。"    },    {     "en": "Eccentric contractions generate the most force of the three and are the most damaging when they exceed capacity, which is why soreness appears a day or two after unfamiliar downhill work rather than immediately.",     "zh": "离心收缩产生的力最大，超出承受限度时损伤也最重，因此陌生下坡训练后的酸痛往往要在一两天后才出现，而不是立刻发生。"    }   ],   "analogy": {    "en": "Pushing a stalled car is a concentric contraction: the muscle shortens and does work. Braking while it rolls is eccentric: the muscle lengthens while absorbing the energy the body is generating. Holding the car still with the engine off is isometric.",    "zh": "推一辆熄火的车是向心收缩：肌肉缩短并做功。让它在滚动中减速是离心收缩：肌肉在身体产生能量的同时被拉长吸收能量。熄火后把车顶住不动则是等长收缩。"   },   "example": {    "en": "Landing from a jump, the quadriceps lengthens on impact and absorbs the energy of the fall, then shortens to push you back up. The lengthening is the phase that limits how hard you can land, and the one that takes the most damage when the load is beyond the muscle.",    "zh": "跳跃落地时，股四头肌在冲击下被拉长以吸收下落的能量，随后缩短把你推回地面。拉长阶段限制了你落地时能承受的冲击强度；当负荷超出肌肉能力时，损伤也主要发生在这一阶段。"   }  },  "Recruitment, adaptations and sliding filament": {   "sum": [    {     "en": "Force is graded two ways: **recruitment** (how many motor units join) and **frequency summation** (how often they fire). Neither changes the force of a single fibre.",     "zh": "力量的调节有两个途径：**募集**（加入多少个运动单元）与**频率总和**（放电频率多高）。两者都不会改变单根纤维自身的收缩力。"    },    {     "en": "The **all-or-none principle** means a fibre either fires completely or not at all. Graded control is therefore a population problem, not a volume one.",     "zh": "**全或无定律**意味着单根纤维要么完全放电，要么完全不放电。因此分级控制是一个群体问题，而不是强度问题。"    },    {     "en": "At the fibre level, contraction happens by the **sliding filament** mechanism: thin actin filaments slide over thick myosin, and the overlap increases. The filaments themselves never shorten.",     "zh": "在纤维层面，收缩通过**肌丝滑动机制**发生：细的肌动蛋白滑过粗的肌球蛋白，重叠增加。肌丝本身从不缩短。"    },    {     "en": "Cross-bridges form, pull one power stroke powered by ATP, then detach. More overlap means more cross-bridges, which is why a contracted muscle is stiffer and stronger.",     "zh": "横桥形成后，利用ATP完成一次力量性的划动，然后分离。重叠越多，横桥越多，因此收缩的肌肉更硬更强。"    },    {     "en": "Training adaptations act mainly through **hypertrophy** — more fibres, not thicker ones — and through more mitochondria and capillaries for endurance.",     "zh": "训练适应主要通过**肌肥大**实现——是纤维数量增加，而不是单根变粗；耐力方面则表现为线粒体与毛细血管增多。"    }   ],   "analogy": {    "en": "Sliding filaments are two hands pulling on two ropes that run past each other: the hands never get shorter, they just grip more rope. Strength is about how much rope is gripped, not how long the arms are.",    "zh": "肌丝滑动就像两只手拉着两条互相穿过的绳索：手本身并没有变短，只是抓住了更多的绳索。力量取决于抓住了多少绳索，而不是手臂有多长。"   },   "example": {    "en": "Holding a 1 kg weight and a 20 kg weight uses the same single fibres at the same strength. The difference is entirely how many units are switched on — which is why a 20 kg hold exhausts you and a 1 kg hold does not.",    "zh": "握住1公斤重物和20公斤重物时，单根纤维的强度完全相同。差别完全在于开启了多少个运动单元——这正是20公斤的静止支撑会让人精疲力竭，而1公斤不会的原因。"   }  },  "Components and lever classes": {   "sum": [    {     "en": "A **lever** is any rigid body that turns about a pivot. Every bone in the body is a lever, and every one can be described with the same four parts.",     "zh": "**杠杆**是绕支点转动的任何刚体。人体内每一块骨都是杠杆，且每一块都可以用同样的四个组成部分来描述。"    },    {     "en": "The **effort arm** is the distance from the pivot to the effort (the muscle's insertion). The **load arm** is the distance from the pivot to the load (usually the centre of mass of the segment).",     "zh": "**动力臂**是支点到动力（肌肉附着点）之间的距离。**阻力臂**是支点到负荷（通常是该节段的质心）之间的距离。"    },    {     "en": "The **pivot** is the joint or the point where a body part is supported. The **effort** is the muscle force; the **load** is the resistance you are moving.",     "zh": "**支点**是关节或身体部位受到支撑之处。**动力**是肌肉产生的力；**负荷**是你要克服的阻力。"    },    {     "en": "Third class: effort arm shorter than the load arm, so the muscle always loses (speed and range win; force is sacrificed). The **biceps** bending the elbow is the standard example.",     "zh": "第三类杠杆：动力臂短于阻力臂，因此肌肉总是吃亏（速度和幅度占优，力量被牺牲）。屈肘时的**肱二头肌**就是典型例子。"    },    {     "en": "First class: the pivot sits between effort and load, as in the neck when it balances the head. Second class: the load sits between pivot and effort, as in **calf raise**.",     "zh": "第一类杠杆：支点位于动力与负荷之间，如头部平衡时的颈部。第二类杠杆：负荷位于支点与动力之间，如**提踵**。"    }   ],   "analogy": {    "en": "A lever is a see-saw: the only thing that decides which way it tips is the ratio of the two arm lengths, not how hard you push. A long effort arm is a longer handle on the same effort.",    "zh": "杠杆就是一块跷跷板：决定它向哪边倾倒的，只有两条臂长之比，而不是你推得多用力。较长的动力臂，相当于同样的力量多了一截把手。"   },   "example": {    "en": "Holding a 10 kg weight in your hand with the elbow bent is harder than holding it with the elbow straight, because bending shortens the biceps effort arm. The load has not changed; the lever has.",    "zh": "屈肘时手中持10公斤重物比伸肘时更费力，因为屈肘缩短了肱二头肌的动力臂。负荷没有变，变的是杠杆。"   }  },  "Mechanical advantage and equipment": {   "sum": [    {     "en": "**Mechanical advantage** is the ratio of load to effort. Above 1 the lever wins, below 1 the muscle pays.",     "zh": "**机械优势**是负荷与动力之比。大于1时杠杆占优，小于1时由肌肉买单。"    },    {     "en": "Most human joints sit below 1 — that is why muscles are large and why we fatigue. But it buys something worth paying for: **speed** and **range of movement** at the end of the limb.",     "zh": "人体大多数关节的机械优势小于1——这就是肌肉如此发达、也如此容易疲劳的原因。但它换来了值得付出的东西：肢体末端的**速度**与**活动幅度**。"    },    {     "en": "Equipment works on the same principle. A lighter **racket**, a longer lever on a **pole vault**, a lighter **implement** in throwing, and a lower **centre of gravity** in a wheelchair all shift the ratio in the athlete's favour.",     "zh": "器材遵循同一原理。更轻的**球拍**、撑竿跳中更长的杠杆、投掷中更轻的**器械**，以及轮椅中更低的**重心**，都在把比值向运动员有利的方向调整。"    },    {     "en": "The trade is usually speed or durability: a high mechanical advantage means the load moves slowly and the structure sees higher forces.",     "zh": "这种交换通常以速度或耐久为代价：机械优势越高，负荷移动越慢，结构承受的力也越大。"    },    {     "en": "So prescribing equipment is not free performance. It is a decision about which limit you are willing to accept.",     "zh": "因此，开具器材并不是白得的提升，而是一个关于你愿意接受哪一种限制的决定。"    }   ],   "analogy": {    "en": "A wheelbarrow is a second-class lever: the load sits between the wheel and your hands, so you lift less than you carry. It is no faster and it is not lighter — it just moves the effort to a better place.",    "zh": "独轮车是第二类杠杆：负荷位于轮子与你的双手之间，因此你提起的力小于你搬运的重量。它不会更快，也不更轻——只是把施力点换到了更好的位置。"   },   "example": {    "en": "Using a longer pole vault does not let you clear more height for free. You gain clearance, but the pole has to resist a much larger bending moment, and a pole that is too light for the athlete simply bends and returns less height.",    "zh": "使用更长的撑竿并不是免费让你跳得更高。你获得了过杆高度，但撑竿必须承受更大的弯矩；而对某位运动员来说过轻的撑竿只会弯曲，返还的高度反而更少。"   }  },  "Three laws and motion variables": {   "sum": [    {     "en": "Newton's **first law**: a body stays at rest, or in uniform motion, until a net force acts on it. This is **inertia**, and it is why you must push to start and push again to stop.",     "zh": "牛顿**第一定律**：物体保持静止或匀速直线运动，直到有合外力作用。这就是**惯性**，也是为什么起步要用力、停止也要再用力。"    },    {     "en": "Newton's **second law**: force equals mass times acceleration. For a fixed push, a heavier mass changes speed more slowly; that is why **momentum** (mass × velocity) matters in a tackle.",     "zh": "牛顿**第二定律**：力等于质量乘以加速度。在推力一定时，质量越大速度变化越慢；这正是擒抱中**动量**（质量乘速度）至关重要的原因。"    },    {     "en": "Newton's **third law**: every action has an equal and opposite reaction. You push the ground backwards, the ground pushes you forwards; a **ground reaction force** is what actually moves you.",     "zh": "牛顿**第三定律**：每个作用力都有一个大小相等、方向相反的反作用力。你向后蹬地，地面向前推你；真正使你前进的正是**地面反作用力**。"    },    {     "en": "The three variables are force, mass and velocity. Video analysis lets you measure all three in two dimensions, which is what makes biomechanics quantitative rather than descriptive.",     "zh": "这三个变量是力、质量与速度。影像分析可以让你在二维平面内测量三者，这正是生物力学成为定量科学而非仅仅描述性科学的原因。"    }   ],   "analogy": {    "en": "Swimming is the clearest demonstration of all three: you push the water backwards, the water pushes you forwards, your mass resists being accelerated, and without that resistance you would have no way to stop.",    "zh": "游泳是对三条定律最清晰的演示：你向后推水，水向前推你；你的质量抗拒被加速，而正是这种抗拒让你有办法停下来。"   },   "example": {    "en": "Two players of identical mass colliding head-on transfer momentum far more than one player stopping a much lighter opponent, because the lighter player's momentum is small in the direction of contact.",    "zh": "两名质量相同的球员正面相撞所传递的动量，远大于一名球员撞停一名体重轻得多的对手——因为轻的那一方在接触方向上的动量很小。"   }  },  "Stability, impulse and collisions": {   "sum": [    {     "en": "Stability comes from a low centre of gravity and a wide base of support. Move either the mass or the feet and the margin of stability changes immediately.",     "zh": "稳定性来自较低的重心和较宽的支撑面。重心或双脚位置任一改变，稳定余量都会立刻变化。"    },    {     "en": "**Torque** is force times the perpendicular distance from the line of action to the pivot. The same force produces a bigger rotation further from the joint.",     "zh": "**力矩**是力与其作用线到支点的垂直距离之积。同样的力，离关节越远产生的转动越大。"    },    {     "en": "**Impulse** is force times the time it acts. Two players can absorb the same collision force differently purely by changing how long they take to decelerate.",     "zh": "**冲量**是力与其作用时间之积。两名球员吸收同样的碰撞力，仅通过改变减速所花的时间就能得到不同结果。"    },    {     "en": "This is why a rigid, braced body transmits a bigger impulse into the tissues than a compliant one. Keeping the arms loose and the body relaxed lengthens the stopping time.",     "zh": "这就是为什么僵硬、绷紧的身体会把更大的冲量传入组织，而柔软的身体不会。放松手臂与身体可以延长减速时间。"    }   ],   "analogy": {    "en": "Catching a ball with a rigid hand hurts; catching it with a soft glove does not, though the force is identical. The glove simply spends longer bringing your hand to a stop.",    "zh": "用僵硬的手接球会疼，用柔软的手套接则不疼，尽管受力完全相同。手套只是让你的手停下来花的时间更长。"   },   "example": {    "en": "Rolling your shoulder forward and down as a tackle arrives lengthens the deceleration and lowers your centre of gravity at the same time — one adjustment that both reduces impulse and increases stability.",    "zh": "在擒抱到来时向前向下滚肩，可以延长减速时间、同时降低重心——一个动作同时减少冲量并提高稳定性。"   }  },  "Friction, work and power": {   "sum": [    {     "en": "**Friction** is what lets you push off without sliding. It is proportional to the normal force, which is why a heavier athlete grips the floor better.",     "zh": "**摩擦力**让你蹬地时不会滑倒。它与正压力成正比，这也是体重较大的运动员抓地力更强的原因。"    },    {     "en": "The **coefficient of restitution** measures how bouncy something is: near 1 returns almost all the energy, near 0 absorbs it. Balls and surfaces are chosen for a task, not for feel.",     "zh": "**恢复系数**衡量物体的弹性：接近1几乎返还全部能量，接近0则几乎全部吸收。球与场地是为任务而选，而不是凭手感选的。"    },    {     "en": "**Work** is force multiplied by the distance the point of application moves in the direction of the force. Lift a load twice as high and you have done twice the work.",     "zh": "**功**是力与力的作用点在力的方向上移动距离之积。把负荷举到两倍高度，你就做了两倍的功。"    },    {     "en": "**Power** is work divided by time, so it is force multiplied by velocity. Power is what separates a heavy lift from a fast lift that is actually harder.",     "zh": "**功率**是功与时间之比，也就是力乘以速度。功率正是区分“重举”与“更快因而更难”的动作的关键。"    },    {     "en": "That is why a heavy athlete and a light athlete are matched on power rather than on strength alone — the outcome of a sprint or a jump is decided by power.",     "zh": "因此，重运动员与轻运动员是以功率而非单纯力量来比较的——冲刺或跳跃的结果由功率决定。"    }   ],   "analogy": {    "en": "Power is work per second, so the same amount of work done quickly is more valuable. Sprinter and shot putter are not doing more work than a rower; they are finishing it before the boat does.",    "zh": "功率是每秒所做的功，因此同样的功完成得越快越有价值。短跑选手和铅球选手并不比赛艇运动员做更多的功，他们只是比船先做完。"   },   "example": {    "en": "Two athletes lift 100 kg. One takes 3 s, the other 1 s. Identical work; the second athlete has produced three times the power, which is why powerlifting separates them from weightlifting.",    "zh": "两名运动员都举起100公斤。一人用3秒，另一人用1秒。功完全相同；第二位运动员的功率是前者的三倍，这正是力量举与举重分属不同项目的原因。"   }  },  "Projectile motion and environmental forces": {   "sum": [    {     "en": "A projectile is the only movement you can predict exactly. Once it leaves the ground it is governed by two things: **drag** and gravity.",     "zh": "抛体运动是你唯一能够精确预测的动作。它一旦离地，就只受两件事支配：**阻力**与重力。"    },    {     "en": "Without drag, the only way to change range is to change the release angle or the speed. Drag makes speed fade and makes the optimal angle fall below 45°.",     "zh": "若没有阻力，改变远度的唯一方法就是改变出手角度或速度。阻力会让速度衰减，并使最优角度低于45度。"    },    {     "en": "**Drag** increases with speed and with the area facing the air, and it opposes motion. A discus is a flat disc so it presents little area; a shot is a sphere so it presents a small constant one.",     "zh": "**阻力**随速度和迎风面积增大，并与运动方向相反。铁饼是扁平的圆盘，迎风面积极小；铅球是球体，因而呈现一个小而恒定的迎风面积。"    },    {     "en": "Environmental forces then add to it: **wind** helps or hinders depending on direction, **air density** falls with altitude, and **temperature** changes both.",     "zh": "随后环境力叠加其上：**风**依方向或助或阻，**空气密度**随海拔下降，而**温度**同时影响两者。"    },    {     "en": "In practice these are corrected for rather than argued about: records are wind-legalised, and equipment is tested at competition conditions.",     "zh": "实践中这些因素是被校正而非被争论的：纪录要符合风速规定，器材也在比赛条件下检测。"    }   ],   "analogy": {    "en": "A javelin is a flat blade travelling through water rather than air. The same principle as a bullet — shape decides how much of itself it must drag along — is why a javelin carries a cord grip at its balance point.",    "zh": "标枪像一片薄刀在水中而非空气中穿行。它与子弹遵循同一原理——形状决定它必须拖着自己走多少空气——这也是标枪在平衡点处绑有绳带的原因。"   },   "example": {    "en": "A discus thrower releasing at 45° and complaining about the throw has almost certainly lost range to a headwind. The fix is not more effort, it is a lower release angle chosen for the conditions that day.",    "zh": "投铁饼运动员以45度出手却嫌投得不够远，问题几乎一定是逆风造成的。解决办法不是加大力量，而是根据当天的条件选择更低的角度。"   }  },  "Buoyancy, lift and drag": {   "sum": [    {     "en": "**Buoyancy** is an upward force equal to the weight of the fluid you displace. Float and swim, and the diver, both work because of it.",     "zh": "**浮力**是等于你所排开流体重量向上的力。漂浮、游泳以及潜水员的工作原理都源于此。"    },    {     "en": "**Lift** is the upward component of a force acting sideways to a surface. It needs flow, and it grows with the speed of that flow.",     "zh": "**升力**是作用力中垂直于物体表面的向上分量。升力需要气流，并随气流速度增加而增大。"    },    {     "en": "Drag is the same force acting backwards. So the shape of a body decides how it splits one force into lift and drag — you cannot have a lot of one without paying in the other.",     "zh": "**阻力**是同一作用力向后的分量。因此物体形状决定了它如何把一个力分解为升力与阻力——你不可能大量获得其中一个而不付出另一个的代价。"    },    {     "en": "That is the trade at the front of a ski or a fast-moving shuttlecock: high lift is bought with high drag, which is why the shape is always a compromise.",     "zh": "这正是滑雪板前端或高速飞行的羽毛球所面对的取舍：高升力是用高阻力换来的，因此其形状总是妥协的结果。"    },    {     "en": "In water the same forces apply with different magnitudes, because water is far denser than air. It is why swimming suits and swimmers are both shaped by fluid mechanics.",     "zh": "在水中同样的力依然成立，只是量级不同，因为水的密度远大于空气。这正是泳衣与游泳运动员的形状都由流体力学决定的原因。"    }   ],   "analogy": {    "en": "Hold your hand flat and push it through the air: you feel nothing. Tilt it edge-on and the air pushes back hard. Skiers, swimmers and fast shuttlecocks all do the same thing with a surface.",    "zh": "手掌平伸在空气中推动，几乎感觉不到阻力；把它立成刃口朝前，空气就会狠狠推回来。滑雪者、游泳者与高速羽毛球都在用表面做同一件事。"   },   "example": {    "en": "A swimmer who swims flat and level creates lift as well as drag, but a swimmer who breaks the surface to breathe loses most of it for those strokes. This is why breathing technique is taught as a body-position problem.",    "zh": "平直水平的游泳者既产生升力也产生阻力，但每划一次臂都要破出水面呼吸的游泳者，在那些划幅上会失去大部分升力。这正是呼吸技术被当作身体位置问题来教的原因。"   }  },  "Angle of attack, Magnus effect and fairness": {   "sum": [    {     "en": "**Angle of attack** is the angle between the direction of travel and the surface. Too little and there is no lift; too much and the flow separates and the lift collapses.",     "zh": "**攻角**是运动方向与物体表面之间的夹角。太小则没有升力；太大则气流分离，升力随之崩塌。"    },    {     "en": "**Magnus effect** is the curved path a spinning ball takes, from the difference in air speed between the two sides. Fast bowlers, topspin and sidespin all use it.",     "zh": "**马格努斯效应**是旋转球所走的弯曲轨迹，来源于球两侧空气速度之差。快速投球手、上旋与侧旋都在利用它。"    },    {     "en": "Topspin dips the ball faster and is safer to bounce; backspin slows it and checks up; sidespin turns it, which is what makes a leg spin look like it is bending.",     "zh": "上旋使球更快下坠、弹跳更安全；下旋让球减速并止旋；侧旋则使球转向，这正是腿旋球看起来在“拐弯”的原因。"    },    {     "en": "**Fairness** is the part that is easy to overlook: above a threshold, a **seam** bowler is obliged to declare that he is one, because a ball that behaves unpredictably from the seam is the one thing both batters must be able to plan for.",     "zh": "**公平**这一点最容易被忽略：超过规定阈值后，**缝线球**投球手必须申报自己是缝线球，因为一颗因缝线而表现不可预测的球，是双方击球手都必须能够预判的底线。"    }   ],   "analogy": {    "en": "Put spin on a football and it does the same thing a model aeroplane does: the wing that is moving faster generates more lift, so the ball pushes towards the slower side and curves.",    "zh": "给足球加上旋转后，它的运动方式与模型飞机相同：速度更快的一侧产生更大升力，于是球被推向较慢的一侧并发生弯曲。"   },   "example": {    "en": "A leg-spinner will sometimes bowl the same delivery with two different breaks. That is not inconsistency; it is a small change in release angle rotating the seam orientation differently relative to the airflow.",    "zh": "腿旋投球手有时会用同一套动作投出两种不同的旋转。这并非不稳定，而是出手角度的细微改变使缝线相对于气流产生了不同的朝向。"   }  },  "Phases and the diagnosis loop": {   "sum": [    {     "en": "Movement analysis is only meaningful when it is broken into **phases**. A whole jump filmed as one piece tells you very little.",     "zh": "只有把动作分解为若干**阶段**，动作分析才有意义。把整个跳跃当作一个整体拍摄，说明不了多少问题。"    },    {     "en": "Phases are usually preparation, acceleration, flight or transition, and landing. Each has its own dominant forces and its own injury risks.",     "zh": "阶段通常包括准备、加速度、腾空或转换、以及落地。每个阶段都有自己的主导外力与各自的受伤风险。"    },    {     "en": "Inside each phase there is a **critical instant** — the single frame where the outcome is actually decided, usually where the joint angle is worst.",     "zh": "在每个阶段之内都存在一个**关键瞬间**——真正决定结果的那一帧，通常出现在关节角度最差的位置。"    },    {     "en": "Analysis runs as a loop: film, identify phases and the critical instant, measure what you can, compare to what the sport demands, then re-test after a change.",     "zh": "分析是一个循环：拍摄、识别阶段与关键瞬间、测量可测量的部分、与该项目的要求相比较，然后在改变方案后重新测试。"    },    {     "en": "The loop only closes if you go back to film. Measuring without re-filming tells you what happened once, not whether it changed.",     "zh": "只有回到影像，这个循环才算闭合。只测量而不重拍，得到的只是一次发生了什么，而不是它是否改变了。"    }   ],   "analogy": {    "en": "Analysing a race by its final time is like reading a novel by its last page. The phases are the plot; the critical instant is the sentence that turns it.",    "zh": "只靠最后成绩来分析比赛，就像只读小说的最后一页。阶段才是情节，而关键瞬间就是让情节转向的那一句。"   },   "example": {    "en": "In a long-jump take-off, the critical instant is the instant the foot contacts the board too far forward, because that single frame converts a forward drive into a braking impulse through the ankle.",    "zh": "在跳远起跳中，关键瞬间是脚在踏板上落得过前的那一帧，因为正是这一帧把向前的蹬伸变成了经踝关节的制动冲量。"   }  },  "Evidence sources and compensation": {   "sum": [    {     "en": "**Notational analysis** — counts of passes, shots, tackles, sprints per player or team — is cheap, repeatable and tells you what happened but never why.",     "zh": "**记名式分析**——传球、射门、擒抢、冲刺的计数——成本低、可重复，能说明发生了什么，却永远说明不了为什么。"    },    {     "en": "Video analysis adds the *how*: angles, timings, asymmetry. It needs skill, equipment and consent, and it is still only as good as the camera angle.",     "zh": "影像分析补充了“如何”：角度、时序、不对称性。它需要技术、设备与被拍摄者的同意，而且效果仍然受制于机位角度。"    },    {     "en": "Force plates, EMG and pressure insoles add *why*, at the cost of complexity and of measuring something that is not the movement itself.",     "zh": "测力台、肌电与压力鞋垫补充了“为什么”，代价是复杂，并且测得的并非动作本身。"    },    {     "en": "Then **compensation**: athletes adopt strategies that hide a weakness — favouring one limb, changing a technique, or reducing volume to avoid pain.",     "zh": "接下来是**代偿**：运动员会采取掩盖弱点的策略——偏好某一侧肢体、改变技术，或通过减少训练量来避免疼痛。"    },    {     "en": "Compensation is the trap in the loop. A metric can improve while the underlying capacity does not, so always pair the number with what the athlete can actually do.",     "zh": "代偿是这个循环中的陷阱。指标可能改善而实际能力并未提升，因此任何数字都必须与运动员真正能做到的事情配对来看。"    }   ],   "analogy": {    "en": "Counting goals tells you the score. Video tells you how one was scored. A force plate tells you why the shot went where it did — and a player who has learned to score with the weaker foot has changed the game without changing the tally.",    "zh": "数进球说明比分。影像说明一个球是怎么进的。测力台说明这一脚为什么落在那里——而一个学会用较弱脚射门的人，在不改变统计数字的情况下改变了比赛。"   },   "example": {    "en": "A sprinter whose left-right stride asymmetry improves after a boot change may have shortened their stride rather than fixed the asymmetry. Only re-filming reveals which.",    "zh": "一名短跑运动员换了钉鞋后左右步幅不对称改善，他可能是缩短了步幅，而不是修好了不对称。只有重拍才能分辨是哪种。"   }  },  "Rehabilitation and accessibility": {   "sum": [    {     "en": "Rehabilitation is a sequence of decisions: what can be loaded, when, and how much. Loading too early re-injures; loading too late loses tissue.",     "zh": "康复是一连串决策：什么可以负荷、何时开始、以及多少。过早负荷会再次损伤，过晚则损失组织。"    },    {     "en": "Progressive loading usually moves from **isometric** to **range** to **low-load exercise** to **high-load exercise** to **sport-specific** and finally **contact**.",     "zh": "渐进负荷通常从**等长**到**关节活动度**、到**低负荷练习**、到**高负荷练习**、再到**专项动作**，最后是**接触性**训练。"    },    {     "en": "**Accessibility** asks a different question: not how close to the original sport, but which parts of it can be adapted so the athlete competes rather than sits out.",     "zh": "**无障碍**提出的是另一个问题：不是“与原项目有多接近”，而是“其中哪些部分可以改编，使运动员能够参赛而不是只能旁观”。"    },    {     "en": "Classification is functional, not medical: swimming pools already drop starting blocks and allow a false start, and classification is exactly that kind of adjustment.",     "zh": "分级是功能性的而非医学性的：游泳池早已取消出发台并允许抢跳跳，而分级正是这种性质的调整。"    },    {     "en": "Adaptation works by changing the demand, not by lowering the athlete. A prosthetic or a rule change keeps the competition meaningful and the outcome honest.",     "zh": "改编的作用是改变需求，而不是降低运动员水平。假肢或规则调整既保持了比赛的真实性，也保证了结果的诚实。"    }   ],   "analogy": {    "en": "Rehabilitation is rebuilding a bridge while traffic still uses it. Accessibility is widening that bridge, not building a separate one on the other side of the river for the same traffic.",    "zh": "康复是在交通仍在通行的情况下重建桥梁。无障碍则是把那座桥加宽，而不是在河对岸另建一座桥给同样的交通使用。"   },   "example": {    "en": "A wheelchair basketball classification separates players by points scored after being classified in-game, so the contest stays equal between athletes with genuinely different impairments rather than between people with the same impairment and different training histories.",    "zh": "轮椅篮球的分级依据是经过场上判定后的得分，把能力确实不同的运动员分开，使比赛在真正的能力差异之间保持公平，而不是在同样的损伤却训练经历不同的人之间制造不公平。"   }  },  "Internal and external risk factors": {   "sum": [    {     "en": "Risk factors come from two directions. **Internal** factors are the athlete: age, sex, previous **injury**, fitness, technique, personality.",     "zh": "风险因素来自两个方向。**内部**因素来自运动员自身：年龄、性别、既往**损伤**、体能、技术与性格。"    },    {     "en": "**External** factors are everything the athlete meets: the surface, the equipment, the weather, the rules, the training load, and the people around them.",     "zh": "**外部**因素是运动员所遇到的一切：场地、器材、天气、规则、训练负荷以及身边的人。"    },    {     "en": "**Exposure** links the two. A common injury in a high-exposure sport is a different risk from the same injury in a low-exposure one, even for the same athlete.",     "zh": "**暴露**把两者联系起来。同一种常见损伤，在高暴露项目中的风险与在低暴露项目中是不同的，即使针对的是同一名运动员。"    },    {     "en": "The most reliable single predictor of future injury is a **previous injury** — which is why history taking is not paperwork.",     "zh": "对未来损伤最可靠的单一预测因素是**既往损伤**——这就是为什么问诊病史不是走形式。"    },    {     "en": "Risk is not a score to be minimised but a set of factors to be balanced: the aim is to lower the modifiable ones while keeping the exposure that makes the sport worth doing.",     "zh": "风险不是一个需要降到最低的分数，而是一组需要取得平衡的因素：目标是降低那些可改变的因素，同时保留让这项运动值得去做的暴露量。"    }   ],   "analogy": {    "en": "An ankle sprain is not caused by a bad ankle; it is caused by a bad ankle meeting a bad surface at a bad moment under a bad training load. Risk factors name which of those you can change.",    "zh": "踝关节扭伤并非由“糟糕的踝关节”造成，而是糟糕的踝关节在糟糕的时刻、糟糕的场地上、糟糕的训练负荷下相遇。风险因素的作用，就是指出其中哪几项是你能改变的。"   },   "example": {    "en": "A returning footballer who had an ankle sprain on the same artificial surface, in the same boots, under the same coach, is being offered exactly the conditions that caused it. The ankle may be healed and the risk unchanged.",    "zh": "一名复出的足球运动员，若仍在同一块人造草皮、同一双鞋、同一位教练的条件下被安排上场，那么他得到的正是当初造成损伤的条件。踝关节可能已经愈合，而风险丝毫未变。"   }  },  "Acute and cumulative trauma": {   "sum": [    {     "en": "**Acute trauma** has a single mechanism and a single moment: a fall, a collision, a sudden overload. It is easy to date and easy to name.",     "zh": "**急性创伤**只有一个机制、一个时刻：一次跌倒、一次碰撞、一次突然超负荷。它容易确定时间，也容易命名。"    },    {     "en": "**Cumulative trauma** is the same tissue failing repeatedly at sub-threshold loads. There is no single moment, which is why it is missed and why it is often blamed on age.",     "zh": "**累积性创伤**是同一种组织在低于阈值的负荷下反复失效。它没有单一时刻，因此常被忽视，也常被归咎于年龄。"    },    {     "en": "The two combine. A tendon that has been grumbling for weeks is more likely to give way at a single moment than a healthy one.",     "zh": "两者会互相结合。一条已经隐隐作痛数周的肌腱，比健康的肌腱更容易在某个单一时刻断裂。"    },    {     "en": "**Load** is therefore the shared variable: acute trauma is one load above capacity, cumulative trauma is many loads below it.",     "zh": "因此**负荷**是共同的变量：急性创伤是单次负荷超过能力，累积性创伤则是多次负荷低于阈值。"    },    {     "en": "Management follows the difference. Acute needs rest and protection early; cumulative needs a load plan that changes little each week but changes consistently.",     "zh": "处理方式也随之不同。急性损伤需要早期休息与保护；累积性损伤需要一份每周变化不大、但持续变化的负荷计划。"    }   ],   "analogy": {    "en": "A wave hitting a sea wall once is an acute event. The same wave every minute, with the wall never fully recovering between them, is what actually erodes it.",    "zh": "海浪只砸一次海堤是一次急性事件。同一道浪每分钟都来一次，而海堤每次都来不及恢复，这才是真正侵蚀它的力量。"   },   "example": {    "en": "A runner who increases mileage before the previous calf injury has settled has turned a healing acute injury into a cumulative one, and will typically be back on the same treatment plan in a month.",    "zh": "上一处小腿损伤尚未稳定就增加跑量的跑者，等于把正在愈合的急性损伤变成了累积性损伤，通常一个月后会回到同样的治疗方案。"   }  },  "Tissues and concussion": {   "sum": [    {     "en": "Body tissues differ in how they fail, and that is what tells you how long they will take. Bone fails suddenly and heals well. Tendon and ligament fail gradually and heal slowly.",     "zh": "不同组织失稳的方式不同，而这正是判断恢复时间的关键。骨会突然断裂但愈合良好；肌腱与韧带则逐渐失稳且愈合缓慢。"    },    {     "en": "A **functional injury** is a loss of capacity rather than a visible break: you cannot generate the same power, you cannot tolerate the same load, you cannot do what you did last week.",     "zh": "**功能性损伤**是能力的丧失而非可见的断裂：你无法产生同样的力量，无法承受同样的负荷，无法做到上周做过的事。"    },    {     "en": "The brain is unlike every other tissue here. It has no pain receptors, so it cannot report injury — which is precisely why concussion needs a symptom-led decision rather than a test.",     "zh": "大脑在这方面与其他组织都不同：它没有痛觉感受器，因此无法主动报告损伤——这正是脑震荡必须依据症状而非检测来决定的原因。"    },    {     "en": "Concussion is a **functional** injury to the brain caused by acceleration, and it resolves through the same graded load logic as any other tissue injury.",     "zh": "脑震荡是由加速造成的**功能性**脑损伤，它通过与其他组织损伤相同的分级负荷逻辑恢复。"    },    {     "en": "The risk with every head knock is **secondary**: an already-injured brain tolerates a far smaller next impact than a healthy one. This is the single most important reason the same knock is harmless once and serious the next time.",     "zh": "每一次头部撞击的风险在于**二次损伤**：已经受损的大脑能承受的下一次冲击远小于健康大脑。这正是同一次撞击第一次无害、下一次严重的最重要原因。"    }   ],   "analogy": {    "en": "A fractured bone is a snapped ruler: obvious, dated, and it mends. A functional injury is a ruler that is subtly bent — still present, still measurable, and it changes everything you measure with it.",    "zh": "骨折像一把折断的尺：明显、可定日期、而且能重新长好。功能性损伤则像一把轻微弯曲的尺——它还在，仍可测量，但它改变了你用它测量的一切。"   },   "example": {    "en": "A goalkeeper who takes a blow to the head on Saturday, feels fine by Sunday and takes another on Sunday may be the second knock that ends their season — because the first one removed the margin that protected them.",    "zh": "一名守门员周六头部受到撞击，周日感觉良好，周日又受一次撞击——第二次可能就终结了他的赛季，因为第一次已经拿走了保护他的余量。"   }  },  "Prevention and protection": {   "sum": [    {     "en": "**Prehabilitation** means building the capacity to tolerate the sport before you need it. The evidence base is strongest for strength, balance and landing mechanics.",     "zh": "**预康复**是指在需要之前先建立承受该项目的能力。证据最充分的是力量、平衡与落地技术。"    },    {     "en": "**Force absorption** is the principle behind protective equipment: pads, helmets and braces lengthen the stopping time of an impact rather than reducing the force.",     "zh": "**力的吸收**是防护器材背后的原理：护垫、头盔与支具通过延长冲击的减速时间来起作用，而不是降低冲击力本身。"    },    {     "en": "Warm-ups work on the same physics. A gradual increase in load lets stiffness fall and the body prepare; an immediate sprint into full effort does the opposite.",     "zh": "热身遵循同一物理原理。负荷逐步提升可使身体刚度下降、完成准备；而立刻全速冲刺则效果相反。"    },    {     "en": "Rule changes are prevention too: pitch size, contact limits, rest windows and concussion protocols all alter exposure rather than technique.",     "zh": "规则修改同样属于预防：场地尺寸、接触限制、休息窗口与脑震荡规程，改变的都是暴露而不是技术。"    },    {     "en": "Nothing prevents everything, so the honest framing is risk reduction with a known cost — and the cost of a prevention measure should be stated alongside the benefit.",     "zh": "没有任何措施能预防一切，因此诚实的表述是“降低风险并付出已知代价”——而一项预防措施的代价应当与它的收益一并说明。"    }   ],   "analogy": {    "en": "Prevention is the part of the sport you do when nothing is wrong. It is boring, invisible, and the only reason anyone ever notices it is that a team that stopped doing it started collecting injuries.",    "zh": "预防是运动中在“没事的时候”所做的部分。它枯燥、看不见，而人们唯一会注意到它的时刻，是某支球队一旦停下这项工作便开始不断出现伤病的时候。"   },   "example": {    "en": "Wearing a well-fitted mouthguard does not stop the jaw being hit; it absorbs and spreads the force so the teeth and jaw take a fraction of it. That is the whole idea in one object.",    "zh": "佩戴合适的护齿并不能阻止下颌被击打；它吸收并分散冲击力，使牙齿和下颌只承受其中一小部分。整个理念就浓缩在这样一件物品里。"   }  },  "PRICE, healing and rehabilitation": {   "sum": [    {     "en": "**PRICE** is the immediate response to an acute soft-tissue injury: Protection, Rest, Ice, Compression, Elevation.",     "zh": "**PRICE**是急性软组织损伤的即时处理：**保护（Protection）**、**休息（Rest）**、**冰敷（Ice）**、**加压（Compression）**、**抬高（Elevation）**。"    },    {     "en": "The purpose is not to heal faster but to keep the injury from becoming worse while the body starts its own repair.",     "zh": "其目的不是加快愈合，而是在身体启动自身修复之前，防止损伤进一步加重。"    },    {     "en": "Once the acute phase settles, the tissue goes through **remodelling** — collagen is laid down in an orientation that follows the new lines of stress, which is why an early, controlled return beats a long rest.",     "zh": "急性期稳定后，组织进入**重塑期**——胶原会沿着新的应力方向排列，因此早期在控制下回归训练优于长期休息。"    },    {     "en": "Remodelling is why a healed ligament is often strong but less forgiving, and why the last 20% of recovery is the part athletes lose to impatience.",     "zh": "重塑也解释了为何愈合后的韧带虽然强韧却不再宽容，以及运动员因急躁而失去的最后20%恢复究竟在哪里。"    },    {     "en": "Ice has a limit worth stating honestly: recent evidence on some soft-tissue injuries does not support prolonged icing, so PRICE is a starting point rather than a rulebook.",     "zh": "冰敷有一条值得坦白的界限：近期针对部分软组织损伤的证据并不支持长时间冰敷，因此PRICE是起点而不是规则手册。"    }   ],   "analogy": {    "en": "Remodelling is a scar learning a new job. The collagen does not disappear; it re-aligns to whatever it is repeatedly asked to do, which is why the rehab you do in week six decides what week six feels like.",    "zh": "重塑就像疤痕找到了新工作。胶原并没有消失，而是重新排列去适应它被反复要求做的事——因此你第六周做的康复，决定了第六周的感受。"   },   "example": {    "en": "Two athletes sprain an ankle to the same severity. The one who returns to controlled loading and rebuilds strength before cutting and pivoting gets an ankle that tolerates direction change; the one who rests until it stops hurting gets one that does not.",    "zh": "两名运动员踝扭伤程度相同。一名在接受控制的负荷训练、重建力量后才恢复急停变向，得到的是能承受方向变化的踝关节；另一名一直休息到不痛才动，得到的是不能承受方向变化的踝关节。"   }  },  "Staged concussion return": {   "sum": [    {     "en": "Concussion returns in **stages**, and each stage has a symptom ceiling. If symptoms rise above that ceiling, the athlete drops back a stage rather than pushing through.",     "zh": "脑震荡的回归分**阶段**进行，每个阶段都有症状上限。若症状超过该上限，运动员应退回上一阶段，而不是硬撑。"    },    {     "en": "The principle is graded exposure: light activity is symptom-free before heavier, which is symptom-free before contact.",     "zh": "其原则是分级暴露：轻活动无症状后，才能进入更重的负荷；更重负荷无症状后，才能进入接触性训练。"    },    {     "en": "Early rest is recommended only for the first 24 to 48 hours. After that, relative rest — meaning reduced intensity rather than no activity — is associated with faster recovery.",     "zh": "绝对休息只建议用于最初24到48小时。此后，**相对休息**（即降低强度而非完全停止活动）被发现与更快的恢复相关。"    },    {     "en": "**Return to sport** is the last stage and the one most often skipped, because the athlete feels well long before the system has finished reorganising.",     "zh": "**重返赛场**是最后一个阶段，也是最常被跳过的阶段——因为运动员往往在系统完成重组之前很久就已感觉良好。"    },    {     "en": "The decision belongs to a staged, symptom-limited **return to sport** process rather than to the athlete's own readiness. Judgement under pressure is the part that was never recovered.",     "zh": "这个决定应属于一套分阶段、以症状为限制的**重返赛场**流程，而不属于运动员自己是否觉得准备好了。在压力下的判断能力，正是从未真正恢复的那部分。"    }   ],   "analogy": {    "en": "Coming back from concussion is like restarting a tripped power supply: you do not switch everything back on at once, and you do not switch it on again the moment the lights are back. You bring the circuit up stage by stage and watch the readings.",    "zh": "从脑震荡恢复就像重新接通跳闸后的电源：不能一次性全部合上，也不能灯亮了就再次合闸。你要逐级接通电路，并观察读数。"   },   "example": {    "en": "A footballer who is symptom-free at rest and on the pitch but gets headache and nausea on a training collision is not ready for return, however convincingly they passed the earlier stages.",    "zh": "一名足球运动员在静息和场上都无症状，但一旦在训练中出现碰撞性头痛和恶心，无论他们此前多么顺利地通过了前面各阶段，都尚未准备好回归。"   }  },  "Trait-environment interaction": {   "sum": [    {     "en": "Neither **trait** nor **context** explains behaviour on its own. Personality is a predisposition, not a verdict: it biases what you notice and what you find rewarding.",     "zh": "单靠**特质**或单靠**情境**都无法解释行为。人格是一种倾向而非判决：它影响你注意什么、你觉得什么有回报。"    },    {     "en": "The same person behaves differently across contexts, and the same context produces different behaviour in different people. That is the whole of trait-environment interaction.",     "zh": "同一个人在不同的情境下行为不同，而同一种情境在不同人身上也产生不同的行为。这正是特质与情境交互的全部含义。"    },    {     "en": "So prediction is probabilistic. A trait tells you what is more likely, not what will happen — which is why a coach's job is to change the context rather than argue with the trait.",     "zh": "因此预测只能是概率性的。特质告诉你更可能发生什么，而不是一定会发生什么——这也是教练的工作重点在于改变情境，而不是与特质争辩。"    },    {     "en": "This is also why single-factor explanations fail: an athlete labelled lazy and an athlete labelled diligent can produce identical behaviour when the environment is identical.",     "zh": "这也是单一因素解释会失败的原因：一名被贴上“懒惰”标签的运动员与一名被贴上“勤奋”标签的运动员，在环境相同的情况下可能表现出完全相同的行为。"    },    {     "en": "The practical test is to ask what changed. If performance moves when the environment moves, context was doing the work.",     "zh": "实用的检验标准是问：什么发生了变化？如果当环境变化时表现也随之变化，那就是情境在起作用。"    }   ],   "analogy": {    "en": "A trait is the price a shop sets before anyone walks in, and the context is who is in the shop. The same price produces a completely different sale depending on the customer.",    "zh": "特质就像商店在顾客进门之前先定好的标价，而情境则是店里有什么样的顾客。同样的标价会因顾客不同而产生完全不同的成交结果。"   },   "example": {    "en": "The same young athlete runs faster in front of a supportive crowd than in a silent stadium. Nothing about her trait changed; the context did, and the behaviour followed.",    "zh": "同一位年轻运动员在支持者众多的观众面前，比在安静的体育场里跑得更快。她的特质没有改变，改变的是情境，行为随之改变。"   }  },  "Big Five and measurement": {   "sum": [    {     "en": "The **Big Five** — openness, conscientiousness, extraversion, agreeableness and neuroticism — describe where someone sits on five continuous dimensions, not whether they possess a trait.",     "zh": "**大五人格**——开放性、尽责性、外向性、宜人性、神经质——描述的是一个人在五条连续维度上的位置，而不是他是否具备某种特质。"    },    {     "en": "Everyone has all five to some degree. That is why these are dimensions and not categories, and why being high on one says very little on its own.",     "zh": "每个人在五者上都有一定程度。因此它们是维度而不是类别，这也意味着单说某一项分数高，几乎说明不了什么。"    },    {     "en": "Any measurement has to be judged on two things: **reliability** (does it give the same answer twice?) and **validity** (does it measure what it claims to?).",     "zh": "任何测量都必须在两件事上受到检验：**信度**（两次测量结果是否一致？）与**效度**（它测的是不是它声称要测的东西？）。"    },    {     "en": "A personality inventory can be highly reliable and still be invalid for predicting performance, because traits are weak predictors of behaviour in a specific situation.",     "zh": "人格测评可以信度很高，却仍然无法有效预测表现，因为特质在某一具体情境中对行为的预测力本来就弱。"    },    {     "en": "Which is why a coach should treat a profile as a starting hypothesis about the athlete, not a selection criterion applied in advance.",     "zh": "因此教练应把一份测评结果当作关于该运动员的初始假设，而不是事先套用的选拔标准。"    }   ],   "analogy": {    "en": "A bathroom scale can be perfectly reliable and still be invalid for training: it tells you your mass with great accuracy and nothing at all about what you can do.",    "zh": "一台体重秤可以完全可靠，却仍然在训练问题上不具备效度：它能极其准确地告诉你体重，却对你的能力一无所知。"   },   "example": {    "en": "A coach selects a team using conscientiousness scores alone. The high scorers turn up, and the low scorers — who would have attended every session — are cut. The test was reliable and useless.",    "zh": "一位教练仅凭尽责性得分选拔队伍。高分者都到场了，而低分者——那些本会出席每一次训练的人——被淘汰了。这个测评很可靠，却没有用。"   }  },  "Social learning and development": {   "sum": [    {     "en": "Social learning theory holds that much of what we learn we observe rather than discover: we attend to, retain and reproduce what a model does.",     "zh": "社会学习理论认为，我们所学的大部分内容是通过观察而非亲身发现获得的：我们注意、保留并再现示范者的行为。"    },    {     "en": "Four processes do the work: attention, retention, motor reproduction and motivation. The last one is why watching a skill does not automatically produce it.",     "zh": "这一过程由四个环节完成：注意、保持、动作再现与动机。最后一环说明了为什么仅仅观察一项技能并不会自动掌握它。"    },    {     "en": "Development is **self-fulfilling** when the expectations of others become true. That is not mysticism: attention, retention and motivation are all shaped by what a coach expects.",     "zh": "当他人的期待变成现实时，发展就是**自我实现**的。这不是玄学：注意、保持与动机都会受到教练期待的塑造。"    },    {     "en": "The bandy legs example is the standard demonstration: label a child clumsy, treat them as clumsy, and the treatment produces the clumsiness it predicted.",     "zh": "“长短腿”是经典例证：把一个孩子贴上笨拙的标签、按笨拙的方式对待他，于是这种对待制造出了它所预言的笨拙。"    },    {     "en": "The mechanism works in both directions, which is the hopeful half: changing how a coach speaks to an athlete is a real intervention, not a motivational slogan.",     "zh": "这一机制双向运作，这也是令人希望的一面：改变教练对运动员说话的方式是一种真实的干预，而不是一句励志口号。"    }   ],   "analogy": {    "en": "Expectation works like a mould: it does not create the material, but it decides the shape the material is allowed to take. Change the mould and the same child produces different work.",    "zh": "期待如同一个模具：它不制造材料，却决定了材料被允许塑成什么形状。改变模具，同一个孩子就会产出不同的结果。"   },   "example": {    "en": "A coach tells a novice they will be dropped if they miss the last session. The novice attends every session and performs better — the prediction produced the behaviour it claimed to describe.",    "zh": "一位教练告诉新手，如果缺席最后一次训练就会被淘汰。新手于是每次都到场且表现更好——这个预言制造了它所声称描述的行为。"   }  },  "The five core attributes": {   "sum": [    {     "en": "**Resilience** is the ability to recover from a setback and keep going. It is not a personality type and not the absence of emotion; everyone has it to a degree.",     "zh": "**心理韧性**是从挫折中恢复并继续前行的能力。它既不是一种人格类型，也不是“没有情绪”；每个人在一定程度上都有韧性。"    },    {     "en": "**Challenge appraisal** is the judgement an athlete makes about a difficult situation before deciding how to respond. The same demand can be read as threat or as opportunity.",     "zh": "**挑战评估**是运动员在决定如何应对之前，对困难情境所作的判断。同一个要求，既可能被解读为威胁，也可能被解读为机会。"    },    {     "en": "So resilience is mostly the ability to revise an appraisal, not the absence of distress. That is why it is trainable.",     "zh": "因此韧性主要是修正评估的能力，而不是免于痛苦的能力。这也正是它可以被训练的原因。"    },    {     "en": "The practical chain is: demand → appraisal → response → outcome. Interventions work at whichever link is weak, and coaches who only change the demand are ignoring the appraisal.",     "zh": "实际的链条是：要求 → 评估 → 应对 → 结果。干预可以在任何薄弱环节上起作用，而只改变要求的教练，等于忽略了评估这一环。"    },    {     "en": "A coach who treats a poor result as information rather than as identity raises resilience; one who treats it as proof of the athlete's ability lowers it.",     "zh": "把差成绩视为信息而非身份认同的教练会提升韧性；把成绩当作能力证明的教练则会削弱它。"    }   ],   "analogy": {    "en": "Resilience is not the wall standing; it is the ability to start rebuilding after it comes down. A building that is never allowed to be damaged is not strong, it is untouched.",    "zh": "韧性不是墙还立着，而是墙倒之后重新开始建造的能力。从未被允许损坏的建筑并不坚固，只是从未被触碰过。"   },   "example": {    "en": "Two athletes lose the same final. One says the season was a waste; the other says the final was the first time they held the lead for a full half. Same result, different appraisal, different next season.",    "zh": "两名运动员输掉同一场决赛。一人认为整个赛季都白费了；另一人则认为这是他第一次在整整半场内保持领先。结果相同，评估不同，下个赛季也随之不同。"   }  },  "Malleability and self-fulfilling belief": {   "sum": [    {     "en": "Abilities are **malleable** to different degrees. Strength is highly malleable with training; height and bone structure are not. Believing a fixed ability is fixed is itself a belief, and it is testable.",     "zh": "能力的可塑性程度各不相同。力量通过训练高度可塑；身高与骨骼结构则不可塑。相信某种能力是固定不变的，本身就是一种信念，而且它是可以被检验的。"    },    {     "en": "Fixed beliefs raise performance early, because they let an athlete specialise where talent already lies. That is the benefit, and it is also the cost.",     "zh": "固定型信念在早期会提高表现，因为它让运动员在自己有天赋的领域集中投入。这既是好处，也是代价。"    },    {     "en": "The cost appears when the ceiling is reached. An athlete whose identity is built on being the strongest has no account for what to do next, and often selects only tasks that protect the identity.",     "zh": "代价出现在触及天花板的时候。一个把身份建立在“最强”之上的运动员，对“接下来做什么”毫无准备，往往只选择能保护该身份的任务。"    },    {     "en": "So the useful position is not pure growth-mindset cheerfulness but knowing *which* attributes are malleable and being precise about it.",     "zh": "因此有用的立场不是单纯宣扬成长型思维，而是弄清楚**哪些**属性具有可塑性，并且精确地说明。"    },    {     "en": "Precision is what makes it usable: “strength is malleable” is a training plan; “you can do anything” is not, and it fails at exactly the moment it is needed.",     "zh": "精确性使它变得可用：“力量具有可塑性”是一项训练计划；“你什么都能做到”不是，而且它恰恰在最需要的时候失效。"    }   ],   "analogy": {    "en": "Telling someone every ability is like mud is like telling them the sky is mud too. It is technically defensible and practically useless when the sky starts to rain.",    "zh": "告诉一个人所有能力都如同泥土，等于告诉他们天空也是泥土。这在技术上站得住脚，而当下雨时它毫无用处。"   },   "example": {    "en": "A sprinter told that aerobic capacity is highly malleable trains it deliberately. Told that sprinting ability is fixed, the same sprinter treats every interval session as a waste of a scarce talent.",    "zh": "一名短跑运动员被告知有氧能力高度可塑，于是有针对性地训练它。而当被告知短跑能力固定时，同一名运动员会把每一次间歇训练都当作对稀缺天赋的浪费。"   }  },  "Learned helplessness, attribution and health": {   "sum": [    {     "en": "Learned helplessness is what happens when effort repeatedly fails to change the outcome. The athlete stops trying — not because effort is useless, but because experience has taught them that it is.",     "zh": "习得性无助发生在努力反复无法改变结果的时候。运动员不再尝试——并非因为努力无用，而是因为经验教会了他们努力无用。"    },    {     "en": "Attribution theory describes how athletes explain outcomes, along two dimensions: internal or external cause, and stable or unstable cause.",     "zh": "归因理论描述运动员如何解释结果，沿两个维度：内部或外部原因，以及稳定或不稳定原因。"    },    {     "en": "**Locus of control** is the first of those. An internal locus attributes outcomes to one's own action, which is uncomfortable but keeps behaviour connected to results.",     "zh": "**控制点**是其中第一个维度。内部控制点把结果归因于自己的行为，这虽然令人不适，却使行为与结果保持联系。"    },    {     "en": "**Stability** is the second. Attributing a loss to a stable cause (bad talent) is the version that damages motivation, because it closes off the future as well as the present.",     "zh": "**稳定性**是第二个维度。把失败归因于稳定的原因（天赋不足）是会损害动机的那一种版本，因为它不仅关上了未来，也关上了现在。"    },    {     "en": "Because attribution is learned in conversation, a coach who attributes effort to luck teaches instability: if the win was luck, the next loss is deserved.",     "zh": "由于归因方式是在交谈中习得的，把努力归因于运气的教练教会了不稳定性：如果胜利来自运气，那么下一次失败就是应得的。"    },    {     "en": "There is a health cost too. Sustained helplessness is associated with depression, and the athletic population is not immune to it.",     "zh": "这也有健康代价。持续的无助感与抑郁相关，而运动员群体对此同样并不免疫。"    }   ],   "analogy": {    "en": "Learned helplessness is a ratchet: once an athlete concludes that trying does not work, the only way back is evidence. Every session where effort visibly changes the result turns that ratchet one notch.",    "zh": "习得性无助是一个棘轮：一旦运动员认定尝试没有用，唯一的回途就是证据。每一个努力明显改变了结果的训练课，都会把这个棘轮转过��格。"   },   "example": {    "en": "A runner who improved all winter and was still left out of selection may start performing worse without any change in fitness. The cause is not the training; it is the conclusion reached about what training is worth.",    "zh": "一名整个冬天都在进步却仍被排除在选拔之外的跑者，可能在体能毫无变化的情况下开始表现更差。原因不是训练，而是他对“训练值多少”所得出的结论。"   }  },  "Learning, performance and schemas": {   "sum": [    {     "en": "**Motor learning** is the permanent change in capability that comes from practice and experience. **Performance** is what you produce on a given attempt. They are not the same quantity.",     "zh": "**动作学习**是通过练习与经验带来的能力的永久性改变。**表现**是你在某一次尝试中产出的结果。两者并不是同一个量。"    },    {     "en": "**Schema** is the stored mental structure that lets you do a familiar action without thinking about it. Once a schema exists, the movement is cheap and attention is free.",     "zh": "**图式**是储存于心智中的结构，使你无需思考就能完成熟悉的动作。一旦图式形成，动作成本降低，注意力的负担被释放。"    },    {     "en": "Novices therefore have to spend attention on the parts. Experts do not — they spend it on the situation, which is why a coach's job changes as the athlete progresses.",     "zh": "因此初学者必须把注意力花在各个动作环节上。专家则不必如此——他们把注意力放在情境上，这正是教练的工作内容会随运动员水平而改变的原因。"    },    {     "en": "The practical consequence is that a beginner coached like an expert learns nothing, because the verbal instructions have nowhere to attach.",     "zh": "实际后果是：把初学者当专家来教，学生什么也学不到，因为那些口头指令无处可以附着。"    },    {     "en": "Day-to-day variation is normal and it is also the measure. An athlete whose best performance only happens in competition has a schema under pressure, not a schema for life.",     "zh": "日常表现的波动是正常的，同时也是一项指标。若运动员的最佳表现只在比赛中出现，说明他掌握的是“压力下的动作”，而不是“生活中通用的动作”。"    }   ],   "analogy": {    "en": "A schema is a road you have driven so often it needs no attention. A novice is driving the road and the steering wheel at once; the coach's job is to take the wheel first.",    "zh": "图式就像一条你开过太多次、根本不需要注意的路。初学者要同时驾驶道路和方向盘；教练的工作是先把方向盘接过来。"   },   "example": {    "en": "A cyclist asked to “keep the cadence at 90” while learning to corner will try to do both badly. The same cyclist told to think only about the pedal stroke acquires the cornering for free.",    "zh": "一名车手在学习过弯时被要求“把踏频保持在90”，结果两件事都做得很差。而当被要求只想着踏板动作时，他反而免费学会了过弯。"   }  },  "Linear and non-linear pedagogy": {   "sum": [    {     "en": "The **schema teaching** approach is linear: explain, demonstrate, practise, correct, repeat. It suits a beginner with no schema to attach anything to.",     "zh": "**图式教学**法是线性的：讲解、示范、练习、纠正、重复。它适合完全没有图式可供依附的初学者。"    },    {     "en": "Non-linear approaches ask the athlete to discover the movement from a problem, so the schema is built from the athlete's own solutions rather than borrowed from the coach's.",     "zh": "非线性教学法让运动员从问题中自行发现动作，因此图式是从运动员自己的方案中构建的，而不是从教练那里借来的。"    },    {     "en": "The **constraints-led approach** works this way: change one constraint of the task and let the athlete find a movement that solves the new task.",     "zh": "**以约束为导向的方法**正是这样运作：改变任务的一个约束，让运动员找到能解决新任务的动作。"    },    {     "en": "Constraints-led work tends to produce more versatile athletes, because the athlete has solved the problem rather than copied the answer — and copying is fragile under fatigue.",     "zh": "以约束为导向的训练往往培养出适应性更强的运动员，因为运动员是解决了问题而非复制了答案——而在疲劳状态下，复制出来的动作是脆弱的。"    },    {     "en": "Linear teaching is not wrong. It is the right tool for phase one and the wrong tool for phase three, and using the wrong one produces athletes who only perform under conditions exactly as practised.",     "zh": "线性教学并没有错。它是第一阶段的正确工具、第三阶段的错误工具；用错工具会培养出只有在完全照练习条件才能发挥的运动员。"    }   ],   "analogy": {    "en": "Linear teaching is a recipe handed to a beginner. Constraints-led teaching is the same dinner with one ingredient missing, so the beginner has to find out what it was.",    "zh": "线性教学是把食谱交给初学者。以约束为导向的教学则是同一顿饭少给了一种食材，让初学者必须自己弄清少了什么。"   },   "example": {    "en": "Ask a goalkeeper to save from a distance and they will invent a technique for it that no coach taught, because the constraint forces the discovery. Then add a constraint and the technique adapts again.",    "zh": "要求守门员扑救远射，他会由此发明出教练从未教过的技术，因为约束迫使他去发现。然后再增加一个约束，这项技术会再次适应。"   }  },  "Stages, PRP and transfer": {   "sum": [    {     "en": "Learning moves through stages: cognitive, associative, autonomous. The athlete's attention shifts from the movement to its consequences, and the movement stops needing words.",     "zh": "学习要经历认知、联结、自主三个阶段。运动员的注意力从动作本身转向动作带来的结果，动作不再需要语言指挥。"    },    {     "en": "The transition is not a moment but a long overlap, and it is where most learners plateau: the cognitive stage still feels necessary but performance is starting to drift.",     "zh": "这种过渡不是某个瞬间，而是漫长的重叠期，也正是大多数学习者停滞的地方：认知阶段仍感觉必要，但表现已开始波动。"    },    {     "en": "**Performance and potential** (PRP) separates the level you can produce when fresh from the level your practice is actually building.",     "zh": "**表现与潜力（PRP）**把你新鲜时能产出的水平，与训练真正正在建立的水平区分开来。"    },    {     "en": "**Transfer** is whether what you learned in practice appears in competition. Poor transfer is common because the two contexts differ in pressure, fatigue and opponents.",     "zh": "**迁移**是指训练中学到的东西能否在比赛中出现。迁移不良很常见，因为两种情境在压力、疲劳与对手上都存在差异。"    },    {     "en": "Transfer is therefore designed, not assumed: the practice has to contain the pressure, the time limit and the decision-making that the competition will contain.",     "zh": "因此迁移需要被设计，而不是被假定：训练中必须包含比赛将要包含的压力、限时与决策。"    }   ],   "analogy": {    "en": "Learning a language in the country and then only speaking it at home is a transfer problem. Vocabulary does not fail; the context does.",    "zh": "在国外学会一门语言，却只在家里说，这是迁移问题。词汇没有出问题，出问题的是情境。"   },   "example": {    "en": "A penalty taker who trains only from a dead ball will often miss in a shoot-out, because the distraction, the wait and the crowd are all missing from the rehearsal.",    "zh": "一名只在死球状态下训练的点球手，在点球大战中常常罚失，因为干扰、等待与观众全都缺席于排练之外。"   }  },  "Internal, external, broad and narrow": {   "sum": [    {     "en": "Attention can be directed inward (how the body feels and moves) or outward (the task and its surroundings), and broadly across many stimuli or narrowly onto few.",     "zh": "注意力可以向内（身体的感觉与动作）或向外（任务及其环境），也可以广泛地分布于众多刺激或狭窄地集中于少数刺激。"    },    {     "en": "Both **external focus** and **attentional narrowing** improve performance under pressure, and both work by taking attention off the body's own output.",     "zh": "**外部焦点**与**注意窄化**都能提高压力下的表现，两者都通过把注意力从身体自身的输出上移开来发挥作用。"    },    {     "en": "Internal focus is not wrong — it is simply costly in competition, where self-monitoring competes with the decision you are trying to make.",     "zh": "内部焦点并没有错，只是在比赛中代价高昂，因为自我监测会与你正要做出的决策争夺资源。"    },    {     "en": "External focus gives the brain a simpler instruction to run while leaving judgement to the part of the brain that is not busy monitoring.",     "zh": "外部焦点给了大脑一条更简单的执行指令，同时把判断留给未被监测占用的那部分大脑。"    },    {     "en": "So the practical change is small in wording and large in effect: “push the ground away” instead of “push harder”, “recover the handle” instead of “steady your hands”.",     "zh": "因此实际改变在用词上很小、在效果上很大：用“把地面推开”代替“再用力点”，用“找回杆把”代替“稳住手”。"    }   ],   "analogy": {    "en": "Telling a driver to concentrate on the noise in the engine guarantees they hear it. Telling them to listen for the change in the road noise lets them drive.",    "zh": "让司机专注于发动机的声音，保证他一定听得见；而让他去留意路噪的变化，他反而能把车开好。"   },   "example": {    "en": "A free-throw shooter who narrates the wrist position performs worse than one who simply says “see the rim go in”. The first spends attention on a body part that is already doing its job.",    "zh": "一名一边解说手腕位置一边投罚球的球员，表现不如只说“看着篮筐进去”的球员。前者把注意力花在了本就在正常工作的身体部位上。"   }  },  "Distractors and control strategies": {   "sum": [    {     "en": "A **distractor** is anything that takes attention away from the task — a crowd, a score, an opponent's noise, or your own previous mistake.",     "zh": "**干扰源**是把注意力从任务上移开的任何事物——观众、比分、对手的喊声，或你自己上一次的动作失误。"    },    {     "en": "**Controlled distraction** is managing them deliberately: a pre-match routine that decides in advance what you will attend to and what you will ignore.",     "zh": "**可控干扰**是指有意识地管理它们：赛前的固定流程预先决定你要注意什么、忽略什么。"    },    {     "en": "Routines work because they move the decisions out of the moment of pressure. Deciding what to attend to while under pressure is itself a source of pressure.",     "zh": "固定流程之所以有效，是因为它把决策移出了压力时刻。在压力中决定“该注意什么”，本身就是一个压力来源。"    },    {     "en": "**Self-talk** is the internal half of the same idea: a short, rehearsed phrase that carries the instruction instead of a stream of thoughts.",     "zh": "**自我对话**是同一理念的内部一半：一句简短、预演过的短语，用来承载指令，而不是一串流动的念头。"    },    {     "en": "The most effective self-talk is instrumental and present-tense — “smooth”, “strong”, “first step” — because it describes an action the athlete can still take.",     "zh": "最有效的自我对话是工具性的、现在时的——“顺”“有力”“第一步”——因为它描述的是运动员此刻仍然能采取的行动。"    }   ],   "analogy": {    "en": "A pre-shot routine is a set of traffic lights on a road you drive daily: not faster, but predictable, so you arrive without having to decide anything.",    "zh": "赛前流程相当于你每天都走的那条路上的红绿灯：它不会让你更快，但可预测，因此你到达时无需做任何决定。"   },   "example": {    "en": "A tennis player who loses a point mid-match has two options: replay the mistake and think about the next point, or reset with the same three-step routine used before every point regardless of score.",    "zh": "一名网球选手在比赛中间丢掉一分时有两个选择：反复回想失误并想着下一分，或者用每一分前同样的三步流程重新开始，无论比分如何。"   }  },  "Task matching and self-talk": {   "sum": [    {     "en": "Instructions work best when they match the stage. A beginner needs **goal setting** that fixes one thing; an expert needs feedback that leaves the decision open.",     "zh": "指令要与所处阶段匹配。初学者需要那种只锁定一件事的**目标设定**；而专家需要的是不封死决策空间的反馈。"    },    {     "en": "Too many instructions at once is the most common beginner error, because each one asks for a separate attention slot and the beginner does not have spares.",     "zh": "一次给出太多指令是初学者最常见的错误，因为每一条指令都需要一个独立的注意资源，而初学者并没有富余。"    },    {     "en": "Feedback follows the same logic. Knowledge of result says the outcome was right or wrong; knowledge of performance says what the athlete did.",     "zh": "反馈遵循同样的逻辑。结果反馈只说明结果是对是错；表现反馈则说明运动员做了什么。"    },    {     "en": "For a beginner, knowledge of result is often enough, because the correct action is not yet available to be described. For an expert it is useless on its own.",     "zh": "对初学者而言，结果反馈往往已经足够，因为正确的动作尚不存在、无从描述；而对专家而言，单靠它毫无用处。"    },    {     "en": "So the instruction should get shorter and the feedback should get richer as the athlete progresses — which is the opposite of what most coaching sessions do.",     "zh": "因此随着运动员进步，指令应当更短、反馈应当更丰富——而这与多数训练课的做法恰恰相反。"    }   ],   "analogy": {    "en": "A beginner is being driven with directions at every turn; an expert only wants to be told where the destination is, and how it felt.",    "zh": "初学者像是在每个路口都被报路；专家只想知道目的地在哪，以及刚才开得感觉如何。"   },   "example": {    "en": "Telling a novice “bend the knees, keep the chest up, drive the arms, land on the balls of the feet” gives four instructions. Telling an advanced player “own it” gives one, and they can use it.",    "zh": "对新手说“屈膝、抬头挺胸、摆臂、用前脚掌落地”等于给了四条指令；而对进阶球员说“把它拿下”只有一条，他却能用得上。"   }  },  "Need achievement and orientations": {   "sum": [    {     "en": "**Task orientation** judges success by your own standards: did I do what I came to do? **Ego orientation** judges it by comparison with other people.",     "zh": "**任务定向**用自己的标准判断成功：我做到自己来做的了吗？**自我定向**则用与他人的比较来判断。"    },    {     "en": "Both motivate. They simply motivate different behaviours, which is why labelling someone “ego oriented” is as unhelpful as labelling them lazy.",     "zh": "两者都能激励人，只是激励的行为不同——这也是把某人称作“自我中心”无益正如称其懒惰的原因。"    },    {     "en": "Task orientation predicts persistence after a setback. Ego orientation predicts performance when someone is watching.",     "zh": "任务定向可以预测人在受挫后的坚持；自我定向则可以预测“有人在看”时的表现。"    },    {     "en": "The practical implication is about which situation you are building for, because a championship final and a training block reward different things.",     "zh": "实际含义在于你是在为哪种情境做准备，因为锦标赛决赛与训练周期所回报的东西并不相同。"    },    {     "en": "Coaching that only ever addresses one of the two produces athletes who are either persistent but indifferent to results, or competitive but brittle.",     "zh": "如果教练只针对其中一面，就会培养出要么坚持却对成绩无所谓、要么好胜却脆弱的运动员。"    }   ],   "analogy": {    "en": "Task orientation is running your own race against your own last time. Ego orientation is running it against the person on the next lane.",    "zh": "任务定向是把自己的成绩与上一次相比；自我定向则是与旁边跑道的人相比。"   },   "example": {    "en": "A sprinter who loses a heat but runs his fastest ever split has been task oriented all afternoon. The same athlete may then lose the final to someone else, which is what ego orientation was for.",    "zh": "一名百米选手预赛被淘汰却跑出了个人最快的分段成绩，说明他整个下午都是任务定向的。同一位选手也可能因此在决赛中输给对手——那正是自我定向所追求的。"   }  },  "High ego with low ability and coach influence": {   "sum": [    {     "en": "**Perceived ability** is what the athlete believes they can do, which is not the same as what they can do — and is the better predictor of whether they will try.",     "zh": "**知觉能力**是运动员相信自己能做什么，这与实际能做什么不同——但它才是“会不会去尝试”的更好预测因素。"    },    {     "en": "High ability plus low perceived ability produces avoidance: the athlete withdraws from situations where competence would be visible.",     "zh": "实际能力高而知觉能力低会产生回避：运动员会躲开那些会暴露自己能力不足的情境。"    },    {     "en": "Low ability plus high perceived ability produces **approach behaviour** without the skill to sustain it, so early effort is high and early results are misleading.",     "zh": "实际能力低而知觉能力高会产生缺乏技能支撑的**接近行为**，因此早期努力很高、早期结果具有误导性。"    },    {     "en": "Either way the coach's judgement of “ability” is usually based on exactly this misreading, and then treats the cause as the problem.",     "zh": "无论哪种情况，教练对“能力”的判断通常正是建立在这一误读之上，随后又把成因当成了问题。"    },    {     "en": "The correction is to raise **perceived ability** accurately: mastery experiences that are genuinely earned, feedback that is specific and truthful, and tasks hard enough to succeed at.",     "zh": "纠正的方法是准确地提升**知觉能力**：真正靠努力赢得的掌握经验、具体而诚实的反馈，以及难度适中以至于能够成功的任务。"    }   ],   "analogy": {    "en": "An athlete who has never beaten a hill sprint will not enter one, however fast they are. The race is not the problem; the forecast is.",    "zh": "一名从未赢过坡道冲刺的运动员不会去参加那项比赛，无论他有多快。问题不在比赛，而在预判。"   },   "example": {    "en": "A coach labels a young sprinter “not a sprinter” after two poor races caused by a hamstring injury. The athlete begins to avoid sprints, and the label becomes true — not of their talent, but of their participation.",    "zh": "一名年轻短跑运动员因腿筋受伤连续两场表现不佳，被教练贴上“不是短跑运动员”的标签。于是他开始回避短跑，这个标签变成了现实——不是关于他的天赋，而是关于他的参与。"   }  },  "Coaching the environment": {   "sum": [    {     "en": "**Social climate** is what a group repeatedly rewards and punishes, independent of what anyone says it values. It is read from behaviour, not from mission statements.",     "zh": "**社会氛围**是一个群体反复奖励和惩罚的东西，与任何人宣称重视什么无关。它从行为中读出，而不是从口号中读出。"    },    {     "en": "If effort is rewarded, effort appears. If effort is punished by comparison, effort disappears and only talent is defended.",     "zh": "如果努力被奖励，努力就会出现；如果努力因比较而被惩罚，努力就会消失，运动员只会守住天赋。"    },    {     "en": "So coaching the environment is often more effective than coaching the individual: changing what is rewarded changes behaviour faster than changing what is explained.",     "zh": "因此引导环境往往比指导个人更有效：改变被奖励的东西，比改变被解释的东西更快改变行为。"    },    {     "en": "The practical levers are small and concrete: what gets praised in public, what is recorded, who is selected, and what is allowed to fail without punishment.",     "zh": "实际的杠杆都很小很具体：公开表扬什么、记录什么、选拔谁，以及允许什么在没有惩罚的情况下失败。"    },    {     "en": "None of this requires anyone to change their personality. It requires noticing what the group already rewards and deciding whether that is what it wanted.",     "zh": "这一切都不要求任何人改变性格，而是要求注意群体已经在奖励什么，并判断那是否是它想要的。"    }   ],   "analogy": {    "en": "A culture is what a school reports rather than what it declares. Ask which student got the prize, and you have found the values.",    "zh": "文化是一所学校实际汇报的东西，而不是它宣称的价值观。问问谁拿了奖，你就找到了真正的价值取向。"   },   "example": {    "en": "A squad where the fastest player always starts wins games and, within a season, stops producing anyone else. Nothing about coaching was wrong; the environment was simply teaching exactly what it rewarded.",    "zh": "一支总是让最快的球员首发的队伍赢了比赛，却在一个赛季之内再也培养不出其他人。教练本身没有错，环境只是在教它所奖励的东西。"   }  },  "Three basic needs and continuum": {   "sum": [    {     "en": "Self-determination theory rests on three needs: **autonomy** (I chose this), **competence** (I can do this) and **relatedness** (I belong here).",     "zh": "自我决定理论建立在三种基本需要之上：**自主性**（这是我选的）、**胜任感**（我能做到）与**关系需要**（我属于这里）。"    },    {     "en": "Motivation quality runs along a continuum rather than a ladder. Deprivation at any one need does not simply remove motivation; it makes the remaining regulated behaviour brittle.",     "zh": "动机的质量沿连续体而非阶梯变化。任一需要的缺失不只是移除动机，而是使其余受调节的行为变得脆弱。"    },    {     "en": "This is why the same athlete can be well trained and still not persist: performance can be externally regulated while none of the three needs is met.",     "zh": "这就是为什么同一名运动员可以训练良好却依然无法坚持：表现可以是外部调节的，同时三种需要一种都没有得到满足。"    },    {     "en": "Coaching for the needs means removing specific things: choices that were made for them, tasks they are certain to fail at, and language that separates them from the group.",     "zh": "围绕这些需要进行教练指导，就是去掉具体的那些东西：替他们做出的选择、他们注定会失败的任务，以及将他们与群体割裂的语言。"    },    {     "en": "It is not softness. Athletes who meet the three needs tend to persist longer and to return after setbacks, which over a season is worth more than any session.",     "zh": "这不是软弱。满足三种需要的运动员往往坚持更久、在挫折后更愿意回归，而在一个赛季的尺度上，这比任何一节课都更有价值。"    }   ],   "analogy": {    "en": "Motivation is not a tap you open. It is more like three pilot lights, and you can have the engine running with two of them out.",    "zh": "动机不是你打开的水龙头，更像三盏指示灯：其中两盏熄灭了，发动机仍然可以运转。"   },   "example": {    "en": "A coach makes every decision for a talented athlete, gives only tasks the athlete already excels at, and speaks of “my team” rather than “us”. The athlete keeps performing, for a while.",    "zh": "一位教练为有天赋的运动员做每一个决定，只布置他本就擅长的任务，并且说“我的队”而不是“我们”。这名运动员会继续表现一阵子，仅此而已。"   }  },  "Controlled, autonomous and four extrinsic regulations": {   "sum": [    {     "en": "Extrinsic motivation is not one thing. It varies in how much of the person it leaves inside the behaviour.",     "zh": " extrinsic 动机不是单一事物，它在多大程度上把人留在行为内部上有所不同。"    },    {     "en": "**Internalisation** is that measure. At one end, a regulation is controlled: the reason for doing it sits outside and has to be watched. At the other it is autonomous: the reason is now internal.",     "zh": "**内化**就是这一尺度。在一端，调节是受控的：做这件事的理由位于外部，必须时时盯着；在另一端则是自主的：理由已经内化。"    },    {     "en": "Autonomous extrinsic regulation means valuing the outcome for its own sake — the trophy, the selection, the fact that it matters to you.",     "zh": "自主的外在调节意味着你本身就珍视这个结果——奖杯、入选，以及“它对我很重要”这件事。"    },    {     "en": "The classic demonstration is the **overjustification effect**: pay children for drawing and they draw less afterwards, because a reason that used to be enjoyable is now a paid job.",     "zh": "经典例证是**过度理由效应**：给孩子发钱让他们画画，之后他们反而画得更少，因为一个原本令人愉快的理由变成了有偿工作。"    },    {     "en": "The practical warning for sport: an activity an athlete freely chose can be ruined by the reward, and the same outcome reached the other way round can be safe.",     "zh": "对体育的实用警示是：运动员自由选择的某项活动，可能被奖励毁掉；而同样结果若以相反方式达成则安然无恙。"    }   ],   "analogy": {    "en": "Someone waters a plant because they love plants, and someone else waters it because they were told to. The plant receives the same water and grows identically.",    "zh": "有人因为喜欢植物而浇水，也有人因为被要求而浇水。植物得到的水完全一样，长势也完全一样。"   },   "example": {    "en": "A club pays attendance bonuses and, within a month, its most committed players stop coming to the optional sessions. The payment was not too small; it was too external.",    "zh": "一家俱乐部为出勤发奖金，不到一个月，最投入的球员就不再参加自愿训练。奖金不是太少了，而是太外在了。"   }  },  "Six mini-theories": {   "sum": [    {     "en": "**Goal content** asks what the goal is about: performance goals, learning goals or outcome goals. Learning goals produce more adaptation, especially early and for beginners.",     "zh": "**目标定向**问目标的内容是什么：表现目标、学习目标还是结果目标。学习目标带来更多适应，在早期阶段和对初学者尤其如此。"    },    {     "en": "**Internalisation** asks how far the athlete has taken ownership of the goal, which is what links the goal to sustained effort.",     "zh": "**内化**问运动员在多大程度上接受了目标的所有权，这也正是目标与持续努力之间的连接点。"    },    {     "en": "The two also interact: a learning goal that has been imposed stays external however well it is phrased.",     "zh": "两者还会相互作用：一个被强加的学习目标，无论表述得多好，本质上仍然是外在的。"    },    {     "en": "Mini-theories are useful because they each name one mechanism, which lets a coach choose an intervention instead of arguing about motivation in general.",     "zh": "小理论之所以有用，是因为它们各自指明一种机制，让教练可以选择干预方式，而不必笼统地空谈动机。"    },    {     "en": "None of them predicts a specific athlete on a specific day. They describe tendencies, and tendencies are what a session plan can reasonably work with.",     "zh": "它们都无法预测某位运动员在某一天的表现。它们描述的是倾向，而倾向正是训练计划能够据以安排的东西。"    }   ],   "analogy": {    "en": "A mini-theory is a single instrument in a bag. None of them tunes the whole guitar, but knowing which one is broken tells you which one to reach for.",    "zh": "小理论就像琴包中的一件乐器。没有任何一件能调好整把吉他，但知道哪一件坏了，就知道该拿哪一件。"   },   "example": {    "en": "An athlete who enjoys the shootout itself may sustain it voluntarily for years; the identical athlete paid a bonus per competition may abandon it. Goal content and internalisation differ; the outcome looks the same.",    "zh": "一名本身就享受点球大战的运动员，可能自愿坚持多年；而条件完全相同、却按场次发奖金的运动员可能很快放弃。目标内容与内化程度不同，看起来的结果却一样。"   }  },  "Mastery and ego climates": {   "sum": [    {     "en": "A **mastery climate** makes effort, strategy and learning the criteria for success. An **ego climate** makes being better than other people the criterion.",     "zh": "**掌握型氛围**把努力、策略与学习作为成功的标准。**自我导向氛围**则把比别人更强作为标准。"    },    {     "en": "Both feel like good coaching. They differ in what they teach when a task is hard, which is exactly when it matters.",     "zh": "两者都让人觉得是好教练。它们在任务困难时教给运动员的东西不同，而这恰恰是最关键的时候。"    },    {     "en": "In a mastery climate a failure is information about method. In an ego climate it is information about the self, and so has to be hidden or explained away.",     "zh": "在掌握型氛围中，失败是关于方法的信息；在自我导向氛围中，失败是关于自我的信息，因此必须被掩饰或另作解释。"    },    {     "en": "The measurable consequence is participation under adversity: athletes in mastery climates keep attempting; athletes in ego climates withdraw or perform.",     "zh": "可测量的后果是在逆境中的参与度：掌握型氛围中的运动员会继续尝试；自我导向氛围中的运动员会退缩或只求表现。"    },    {     "en": "So a coach does not need to choose one label for a session. The question is which criterion is visible in the moment a task gets hard.",     "zh": "因此教练并不需要为某一节课贴一个标签。问题在于：当任务变难的那一刻，究竟哪个标准是可见的。"    }   ],   "analogy": {    "en": "Two coaches shout the same encouragement during a match. One means “you are getting better at this” and one means “you are better than them”. Only one of those is worth saying to someone who is losing.",    "zh": "两位教练在比赛中喊出同样的鼓励。一位的意思是“你在这件事上进步了”，另一位的意思是“你比他们强”。对正在落后的人来说，只有其中一句值得说。"   },   "example": {    "en": "A youth player who finishes third is praised for the two things she did well and is told the next step. The same finish in an ego climate produces silence, because there is no way to say it that is not about winning.",    "zh": "一名青少年选手获得第三名，教练表扬她做好的两点并说明下一步。同样的名次在自我导向氛围下只会换来沉默，因为没有任何说法能绕开“输赢”本身。"   }  },  "TARGET framework": {   "sum": [    {     "en": "**TARGET** is a set of questions for building trust in a teaching relationship: Task, Authority, Rapport, Environment, Trust and Goals.",     "zh": "**TARGET**是一组用于建立师生信任的问题：任务（Task）、权威（Authority）、融洽（Rapport）、环境（Environment）、信任（Trust）与目标（Goals）。"    },    {     "en": "Each letter is a question a coach asks rather than a principle they assert, which is what makes it usable with a resistant group.",     "zh": "每个字母都是教练要**问**的问题，而不是他们要宣称的道理，这正是它在抵触型群体中仍然可用的原因。"    },    {     "en": "Trust is both the first and the last letter on purpose. It is a precondition for the other five and also their most durable result.",     "zh": "信任被有意放在首尾两端：它既是其余五项的前提，也是它们最持久的结果。"    },    {     "en": "The authority question is the one coaches skip, and skipping it is why being corrected can feel like a verdict about competence rather than an update to the plan.",     "zh": "权威这一问是教练最容易跳过的，而跳过它正是为什么被纠正会像是对胜任力的判决，而不是对计划的更新。"    },    {     "en": "The framework is not decorative: each question has a concrete answer, and an unanswered one is a piece of the relationship still missing.",     "zh": "这个框架并非装饰：每个问题都有具体的答案，而未被回答的那个，就是这段关系中仍然缺失的一块。"    }   ],   "analogy": {    "en": "TARGET is a pre-flight checklist. Nothing on it makes the aircraft fly better, but skipping items is how you discover the problem at altitude.",    "zh": "TARGET就像起飞前的检查单。上面没有一项能让飞机飞得更好，但漏掉检查项，就是让你在高空才发现问题。"   },   "example": {    "en": "A coach asks a player what they want to be doing in three years before prescribing anything. The answer reframes the session from a chore into a step, without the coach having to motivate anyone.",    "zh": "教练在开出任何训练处方之前，先问一名球员三年后希望自己在做什么。这个答案把那一节课从一件苦差重新定义为一步——而教练并没有去激励任何人。"   }  },  "Links to motivation and SDT": {   "sum": [    {     "en": "The practical payoff of the motivation literature is **long-term participation**: keeping people in the sport, which is exactly what most single-season outcomes ignore.",     "zh": "动机研究的实际价值在于**长期参与**：让人们留在这项运动中，而这恰恰是多数单一赛季指标所忽略的。"    },    {     "en": "Participation falls at the points where the athlete stops seeing the activity as a good way to spend time. That judgement is made continuously, and it is not the same as whether they are performing.",     "zh": "参与度会在运动员不再认为这项活动是打发时间的好方式时下降。这个判断是持续做出的，而且与“表现好不好”并不等同。"    },    {     "en": "So the practical target is usually not the next competition. It is whether the athlete would still choose this next month, with no prize in sight.",     "zh": "因此实际目标通常不是下一场比赛，而是：即便没有任何奖赏，运动员下个月是否仍会选择这项运动。"    },    {     "en": "That reorders a lot of coaching. Mastery climates, autonomous regulation and need satisfaction all look like they cost something short-term and buy something that only shows up over seasons.",     "zh": "这会重排很多教练工作的优先级。掌握型氛围、自主调节与需要满足，看起来都像是短期有代价、换来的是只有在多个赛季后才显现的东西。"    },    {     "en": "Which is why a single good result can hide a sport that is losing its athletes, and a single bad month can be survived by a sport that is not.",     "zh": "这就是为什么一次好成绩可以掩盖一项正在流失运动员的运动，而一个糟糕的月份也可以被一项并非如此的运动扛过去。"    }   ],   "analogy": {    "en": "Running a club on this year's results is like judging a tree by this year's leaves. The question that matters is whether anyone is still planting it.",    "zh": "用本年度的成绩来经营俱乐部，就像用本年度的叶子来判断一棵树。真正重要的问题是：还有人在种它吗？"   },   "example": {    "en": "A club finishes second in its league and loses eleven of its fourteen under-16s to other clubs. The season looks respectable and the club is smaller in a year.",    "zh": "一家俱乐部在联赛中排名第二，同时 16 岁以下组别 14 人中有 11 人转投其他俱乐部。这个赛季看起来体面，而俱乐部一年之内变小了。"   }  },  "Arousal and theories": {   "sum": [    {     "en": "**Arousal** is general activation: how alert, excited or switched-on someone is. It is not the same as anxiety, which is arousal plus a negative interpretation.",     "zh": "**唤醒**是一般性的激活水平：一个人有多警觉、多兴奋、多投入。它与焦虑并不相同，焦虑是唤醒加上负面的解释。"    },    {     "en": "Different tasks want different arousal. A fine motor skill wants less; a maximal power effort wants more. So there is no such thing as a universally optimal level.",     "zh": "不同的任务需要不同的唤醒水平。精细动作技能需要更低；最大力量输出则需要更高。因此并不存在一个普遍最优的唤醒水平。"    },    {     "en": "**Inverted-U** theory describes performance rising to a moderate level and falling on either side of it. Drive theory describes arousal and performance rising together.",     "zh": "**倒U型**理论描述表现先升至中等水平再在两侧下降。驱力理论则描述唤醒与表现同步上升。"    },    {     "en": "Zone of optimal functioning (**IZOF**) is the practical version: each athlete has an individual band, found by measurement rather than assumption.",     "zh": "**最佳功能区（IZOF）**是它的实用版本：每位运动员都有一个个体化的区间，需要通过测量而非假设来找到。"    },    {     "en": "The evidence also has an inverted-U quality: the relationship is real but moderate, which is why telling an anxious athlete to relax is often the least useful instruction available.",     "zh": "这一证据本身也带有倒U特征：关系真实存在但强度中等，这正是为什么告诉紧张的运动员“放松一点”往往是最没用的指令。"    }   ],   "analogy": {    "en": "Arousal is the rev counter, not the gear. Revs too low and the engine bogs; too high and it bogs as well. Which gear you want depends entirely on the hill.",    "zh": "唤醒水平就像转速表，而不是挡位。转速过低发动机憋闷，过高同样憋闷。想用哪一挡，完全取决于坡度。"   },   "example": {    "en": "A penalty shooter who performs best half-sleepy is not inconsistent; their IZOF is genuinely lower than a teammate's, and asking both to compete at the same heart rate will fail for one of them.",    "zh": "一名半睡半醒状态发挥最好的点球手并不是不稳定；他的最佳功能区确实低于队友，而要求两人在同样的心率下比赛，其中一人必然失败。"   }  },  "Anxiety dimensions and catastrophe": {   "sum": [    {     "en": "Anxiety has at least two dimensions: **cognitive anxiety** (worrying thoughts) and somatic anxiety (physical arousal). They are related but not identical, and they respond differently.",     "zh": "焦虑至少有两个维度：**认知焦虑**（担忧的想法）与躯体焦虑（生理唤醒）。二者相关但并不相同，反应方式也不同。"    },    {     "en": "Cognitive anxiety is the one that damages technique, because it takes up the attention the task needs. Somatic anxiety can even be adaptive — it prepares the body.",     "zh": "损害技术的是认知焦虑，因为它占用了任务所需的注意力。躯体焦虑甚至可能是有适应性的——它在为身体做准备。"    },    {     "en": "**Catastrophising** is the pattern that converts a threat into a disaster. In sport it has a specific shape: the athlete's own error becomes proof of inadequacy, and inadequacy becomes an inevitable outcome.",     "zh": "**灾难化**是把威胁转化为灾难的心理模式。在体育中它有特定形态：运动员自己的失误成了能力不足的证明，而能力不足又成了注定的结局。"    },    {     "en": "The sequence is more damaging than the event, which is why removing the stressor alone often changes nothing.",     "zh": "真正比事件本身更具破坏性的是这条推演链条，因此仅仅移除压力源往往什么也改变不了。"    },    {     "en": "Interventions that work tend to target the interpretation: how the athlete talks to themselves afterwards, and whether the error is treated as information or as identity.",     "zh": "真正有效的干预往往针对解释过程：运动员事后如何与自己对话，以及该错误是被当作信息还是被当作身份。"    }   ],   "analogy": {    "en": "Catastrophising is a fire drill that has forgotten to distinguish a smoke alarm from a fire, and has already called the demolition team.",    "zh": "灾难化就像一次忘了区分烟雾报警与真实火情的消防演练，而且已经叫来了拆迁队。"   },   "example": {    "en": "A midfielder mispasses, and the thought is “they will not pass to me again”. That single sentence turns one mispass into a prediction, a reputation and a reason to stop asking for the ball.",    "zh": "一名中场球员传球失误，脑中出现的念头是“他们以后不会再传给我了”。这一句话把一次失误变成了预测、变成了评价，也变成了不再要球的理由。"   }  },  "Measurement and regulation": {   "sum": [    {     "en": "Arousal can be measured, and the two common routes are different in kind. Self-report (Spitalser) asks the athlete to rate their own state; physiological measures do not ask.",     "zh": "唤醒可以被测量，常见的两条路径在性质上不同。自我报告（如Spitalser量表）要求运动员评定自己的状态；生理测量则不问。"    },    {     "en": "**Galvanic skin response** measures skin conductance, which rises with sweat gland activity and therefore with sympathetic arousal. It is sensitive but not specific.",     "zh": "**皮肤电反应**测量皮肤电导，它随汗腺活动而升高，因而随交感神经唤醒而升高。它灵敏但不特异。"    },    {     "en": "Heart rate does the same job more cheaply and is available in training, but it lags and it is contaminated by everything that raises temperature.",     "zh": "心率以更低成本完成同样的工作且在训练中可得，但它滞后，并且会被一切升高体温的因素污染。"    },    {     "en": "So regulation has to be chosen, not just measured. Breathing slows heart rate; progressive recall lengthens the gap between matches and replays.",     "zh": "因此调节必须被选择，而不只是被测量。呼吸可以减慢心率；渐进式回想则拉长比赛与回放之间的间隔。"    },    {     "en": "The practical protocol is fixed before the event: what is measured, at what point, and what the athlete does with the number.",     "zh": "实用的方案必须在赛前就固定：测量什么、在什么时点测量，以及运动员拿到这个数字后要做什么。"    }   ],   "analogy": {    "en": "A thermometer tells you the temperature but not whether the room is comfortable. Measurement and regulation are different jobs, and only one of them changes anything.",    "zh": "温度计能告诉你温度，却不能告诉你房间是否舒适。测量与调节是两件不同的工作，而其中只有一件能改变现状。"   },   "example": {    "en": "A wearable shows a heart rate of 165 before a final. The protocol says breathe and re-measure in ninety seconds; a coach who simply reacts to the number has measured something and regulated nothing.",    "zh": "某次决赛前，可穿戴设备显示心率165。方案要求呼吸并在九十秒后复测；而仅仅对这个数字作出反应的教练，是只做了测量、什么都没调节。"   }  },  "Stressors and strain": {   "sum": [    {     "en": "A **stressor** is the demand. **Strain** is the effect on the athlete. The two are not the same quantity and the relationship is not linear.",     "zh": "**压力源**是要求，**紧张（strain）**是对运动员造成的效果。二者不是同一个量，其关系也不是线性的。"    },    {     "en": "The same stressor produces different strain in different people, because strain depends on appraisal, coping and resources rather than on the demand alone.",     "zh": "同一种压力源在不同人身上产生不同的紧张，因为紧张取决于评估、应对方式与资源，而不单取决于要求本身。"    },    {     "en": "Negative **distress** is strain that has gone beyond useful activation and is now impairing performance or wellbeing. It is not defined by the stressor.",     "zh": "负面的**困扰**是已经超出有用激活范围、并开始损害表现或健康的紧张。它并不是由压力源来定义的。"    },    {     "en": "So the intervention is usually not to remove the stressor — often that is impossible — but to change the appraisal or the coping that turns it into distress.",     "zh": "因此干预通常不是移除压力源——那往往不可能——而是改变把要求转化为困扰的评估过程或应对方式。"    },    {     "en": "This is why two athletes in the same fixture, one about to be dropped, can produce completely different physiology from the same situation.",     "zh": "这就是为什么同一场比赛中即将被淘汰的两人，可能从同一种情境中产生完全不同的生理反应。"    }   ],   "analogy": {    "en": "A wave hitting two boats is one wave, but the smaller boat pitches further because it is lighter. Strain is the pitching; the stressor is only the wave.",    "zh": "同一道浪打向两条船只是一道浪，但较小的船颠簸得更厉害，因为它更轻。颠簸才是“紧张”，浪只是压力源。"   },   "example": {    "en": "A final-round penalty shootout is the same stressor for both teams. The striker who has spent the week worrying about selection will be in higher strain than the one who has already secured a medal.",    "zh": "决赛轮点球大战对两队而言是同一个压力源。那位整周都在担心是否会被淘汰的球员，其紧张程度会高于已经锁定奖牌的那位。"   }  },  "Three coping categories": {   "sum": [    {     "en": "Coping falls into two broad kinds. **Problem-focused coping** changes the stressor; **emotion-focused coping** changes the athlete's relationship to it.",     "zh": "应对分为两大类。**问题聚焦应对**改变压力源本身；**情绪聚焦应对**改变运动员与压力源之间的关系。"    },    {     "en": "Problem-focused coping works when the stressor is controllable and the athlete can see what to do. Emotion-focused coping works when it is not.",     "zh": "当压力源可控、且运动员能看到该做什么时，问题聚焦应对有效；当不可控时，情绪聚焦应对有效。"    },    {     "en": "The third category, and the one most often overlooked, is **avoidance coping**: not dealing with it at all. It reduces distress immediately and predictably worsens it later.",     "zh": "第三类也是最常被忽视的一类是**回避应对**：干脆不去处理。它会立刻减轻困扰，并且可预测地使情况随后变得更糟。"    },    {     "en": "Injury is where the three are easiest to separate. An athlete can change the problem, change how they feel about it, or refuse to look at it — and the third is the one a physio is least likely to notice.",     "zh": "伤病是这三者最容易区分的场景。运动员可以改变问题、改变自己对问题的感受，或者拒绝去看它——而第三种恰恰是理疗师最不容易察觉的。"    },    {     "en": "So coping assessment belongs in the review, alongside tissue healing, because the mechanism of the problem may no longer be tissue.",     "zh": "因此应对评估应与组织愈合一起纳入复查，因为问题的机制可能已经不再是组织了。"    }   ],   "analogy": {    "en": "Rain is the stressor. Problem-focused coping is an umbrella; emotion-focused coping is a coat; avoidance coping is closing your eyes and hoping it does not get you wet.",    "zh": "雨是压力源。问题聚焦应对是一把伞；情绪聚焦应对是一件雨衣；回避应对则是闭上眼睛，希望雨不会淋到你。"   },   "example": {    "en": "A footballer three weeks from a knee operation keeps training as if nothing has changed. Nothing about the knee will improve, and the scan at week four shows why.",    "zh": "一名膝部手术前三周的足球运动员仍像没事一样训练。膝部情况不会有任何改善，第四周的检查结果说明了原因。"   }  },  "Decision flow and maladaptive responses": {   "sum": [    {     "en": "Decision flow under pressure is usually described as a sequence: appraisal, options, choice, action. Maladaptive responses enter at particular points in that sequence rather than randomly.",     "zh": "压力下的决策流程通常被描述为一个序列：评估、选项、选择、行动。适应不良的反应是在这个序列的特定环节介入的，而不是随机出现。"    },    {     "en": "At appraisal, threat appraisal recruits **avoidance** and rumination. At option generation the list narrows; at choice the athlete picks the option with the lowest predicted regret.",     "zh": "在评估环节，威胁型评估会引发**回避**与反刍。在生成选项时，列表收窄；在做选择时，运动员会挑出预测遗憾最小的那个选项。"    },    {     "en": "Two reliable maladaptive patterns exist: impulsive escape (leaving a situation to reduce immediate discomfort) and avoidance (never arriving at the decision at all).",     "zh": "存在两种可靠的适应不良模式：冲动逃离（离开情境以减少当下的不适）与回避（根本没有走到做决定这一步）。"    },    {     "en": "Both feel like relief at the time. That is why they are so hard to remove by instruction alone — the athlete has to be shown a cost to the relief, not told that it is costly.",     "zh": "两者当下都像是解脱。正因如此，仅凭口头劝说是很难去除的——必须让运动员看到解脱的代价，而不是告诉他解脱是有代价的。"    },    {     "en": "In sport the usual trigger is an imminent, visible consequence: a penalty miss, a final, a selection meeting. Anticipating the decision point and pre-deciding removes the moment that maladaptive responses exploit.",     "zh": "体育中常见的触发点是即将到来的、可见的后果：罚球未进、决赛、选拔面谈。预判这个决策点并提前决定，就能消除适应不良反应所利用的那个瞬间。"    }   ],   "analogy": {    "en": "Escape is the emergency exit. It is not a fault in the building; it is a door that was put there for a reason and is now being used as a shortcut.",    "zh": "逃离就像是紧急出口。它不是建筑本身的缺陷，而是一扇出于特定原因设置、如今却被当作捷径使用的门。"   },   "example": {    "en": "A player who must take a decisive penalty has already decided, in the dressing room, to go down the middle. On the second kick of a shoot-out, with the goalkeeper diving, there is no decision left to spoil.",    "zh": "一名必须罚进决定性点球的球员，在更衣室里就已经决定走中路。在点球大战的第二罚、守门员扑救时，已经没有任何决定可以被搞砸。"   }  },  "Three goal types": {   "sum": [    {     "en": "Three goal types are worth separating: **outcome goals** (win, qualify), performance goals (run a time, hit a percentage) and process goals (what you do, repeatably).",     "zh": "值得区分三种目标类型：**结果目标**（获胜、晋级）、表现目标（跑出某个成绩、命中某个百分比）与过程目标（你反复会做的事）。"    },    {     "en": "The hierarchy is about controllability. Process goals are entirely controllable, performance goals partly, outcome goals not at all.",     "zh": "这一层级的差别在于可控性。过程目标完全可控，表现目标部分可控，结果目标则完全不可控。"    },    {     "en": "So their value differs by situation. An outcome goal motivates before the event and is useless during it, because the athlete cannot change the outcome in the moment.",     "zh": "因此它们在不同情境下的价值不同。结果目标在赛前能激励人，而在比赛进行中毫无用处，因为运动员当下无法改变结果。"    },    {     "en": "A performance goal is a compromise: specific enough to aim at, external enough to be measurable.",     "zh": "表现目标是一种折中：足够具体可以作为瞄准对象，又足够外在因而是可测量的。"    },    {     "en": "A process goal is the only one that can be followed during play, which is why it is the one that survives a difficult middle section.",     "zh": "过程目标是唯一能在比赛过程中被持续遵循的目标，因此它也是唯一能在困难的中段存活下来的那一种。"    }   ],   "analogy": {    "en": "Outcome is the weather, performance is the temperature you recorded, and process is whether you brought the thermometer out. Only the third is worth checking when the forecast changes.",    "zh": "结果是天气，表现是你记录的温度，而过程是你有没有把温度计带出来。只有当天预报改变时，第三项才值得检查。"   },   "example": {    "en": "A cyclist told to “win” has a plan that is accurate until the first attack. Told to “hold the front group for twenty kilometres”, the same rider has a plan that still applies when the plan for winning has already failed.",    "zh": "被要求“获胜”的车手，在第一次进攻前计划都是准确的；而被要求“在前集团领骑二十公里”的同一位车手，即使获胜计划已告失败，他的计划依然适用。"   }  },  "Goal purpose and paradox": {   "sum": [    {     "en": "**Goal setting** works, but it can fail in a way that looks like success. The usual finding is a paradox: setting a specific, difficult goal improves performance — until the task becomes hard.",     "zh": "**目标设定**是有效的，但它可能以看似成功的方式失败。常见的发现是一个悖论：设定具体而困难的目标会提高表现——直到任务变得困难为止。"    },    {     "en": "Below a difficulty threshold, the goal raises effort and attention. Above it, the athlete becomes anxious, narrows attention and may abandon the task rather than fail in public.",     "zh": "在某个难度阈值以下，目标会提高努力与注意力；超过该阈值，运动员会变得焦虑、注意收窄，甚至宁可放弃任务也不愿当众失败。"    },    {     "en": "That produces the disappointing pattern where an athlete performs well at easy tasks and deteriorates as tasks harden.",     "zh": "由此产生一种令人失望的模式：运动员在容易的任务上表现良好，而随着任务变难反而退步。"    },    {     "en": "So goals need a difficulty range, not a single aspiration. The same goal that produced the breakthrough can produce the plateau.",     "zh": "因此目标需要一个难度区间，而不是单一的志向。使运动员突破的那个目标，同样可能使他们陷入平台期。"    },    {     "en": "The practical move is to set goals in bands — a challenge, a target and a floor — so there is always one still within reach when the hardest one fails.",     "zh": "实用的做法是把目标设定为区间：一个挑战、一个目标和一个底线，这样当最难的那个失败时，永远还有一个够得着的。"    }   ],   "analogy": {    "en": "A stretch target is the top rung of a ladder. Reaching it is the point; it is not somewhere to be left standing while someone waits to see whether you can jump.",    "zh": "挑战性目标是梯子的最高一级。登上它才是目的；而不是在上面杵着，等别人看你能不能再跳一下。"   },   "example": {    "en": "A weightlifter given a personal best plus ten kilos as the only target may hit it once and then avoid the platform, because every attempt is now a test of an identity rather than of a lift.",    "zh": "一名举重运动员若只被赋予“个人最好成绩加十公斤”这一个目标，可能达标一次之后就不再走上台面——因为每一次尝试都不再是对一次举重的检验，而是对身份的检验。"   }  },  "Adjustment and flexible goals": {   "sum": [    {     "en": "When a goal becomes unreachable, the athlete has to revise it. **Goal adjustment** covers two very different moves, and they are not equally healthy.",     "zh": "当目标变得无法达成时，运动员必须修正它。**目标调整**包含两种截然不同的做法，而它们并不同样健康。"    },    {     "en": "**Open goal** is a goal that can be revised in scope, difficulty or method without changing its identity. Learning a new skill is usually an open goal.",     "zh": "**开放目标**是可以在范围、难度或方法上调整、而不改变其本质的目标。学习一项新技能通常就是开放目标。"    },    {     "en": "**Flexible goal** means accepting an outcome you did not originally set. Learning to live with a changed career, a career-ending injury or a redefined level is a flexible goal.",     "zh": "**弹性目标**意味着接受一个你最初并未设定的结果。带着改变的职业生涯、终结性的伤病或被重新定义的水平继续生活，就是弹性目标。"    },    {     "en": "Adjustment is not defeat, but it has to be active. Abandoning a goal quietly and then reporting it as adjusted is how a coach misses the point at which the athlete stopped coping.",     "zh": "调整不是失败，但必须是主动的。悄悄放弃目标然后把它说成是“调整过的”，正是教练会错过运动员停止应对的那个时间点的方式。"    },    {     "en": "So the useful question is not whether the goal changed but whether the athlete is still choosing the next one.",     "zh": "因此有用的问题不是目标有没有改变，而是运动员是否还在主动选择下一个目标。"    }   ],   "analogy": {    "en": "A goal is a route, not the destination town. Adjusting the route is ordinary; continuing to drive towards a destination that no longer exists is something else entirely.",    "zh": "目标是路线，而不是目的地小镇。调整路线是常事；而继续驶向一个已不存在的目的地，则完全是另一回事。"   },   "example": {    "en": "A selected athlete who is deselected may revise the goal from making the squad to making the squad next year, and to something they can practise this week — that is a goal still owned. Waiting for selection to happen again without changing anything is not.",    "zh": "一名入选后又被淘汰的运动员，可以把目标从“入选”调整为“明年入选”，并调整为本周就能练习的某件事——这仍是自己掌握的目标；而什么都不改变、只是等着再次被选中，则不是。"   }  },  "Sensory imagery and functions": {   "sum": [    {     "en": "Imagery means using sensory experience without the sensory stimulus. Athletes rehearse movements, situations and outcomes entirely in their head.",     "zh": "意象是指在没有感觉刺激的情况下运用感觉经验。运动员完全在头脑中排练动作、情境与结果。"    },    {     "en": "It has two families: **skill rehearsal** (the movement itself) and **strategy rehearsal** (what you will do with it in a situation).",     "zh": "意象分两族：**技能排练**（动作本身）与**策略排练**（你将在情境中如何运用它）。"    },    {     "en": "There are three images: kinaesthetic, visual and auditory, and they are not interchangeable. Imagery works best when the image matches the question.",     "zh": "意象有三种：动觉、视觉与听觉，且不可互换。意象在图像与问题相匹配时效果最好。"    },    {     "en": "**Skill rehearsal** supports motor learning, particularly when physical practice is unavailable — a cast, an injury or a travel week.",     "zh": "**技能排练**支持动作学习，在无法进行身体练习时尤其有用——例如上石膏、受伤或旅行的一周。"    },    {     "en": "**Strategy rehearsal** supports confidence: rehearsing the decision is closer to the thing that actually has to happen than rehearsing the movement is.",     "zh": "**策略排练**支持自信：排练决策，比排练动作更接近真正需要发生的事情。"    }   ],   "analogy": {    "en": "Imagery is a dress rehearsal with no audience. It changes nothing on the stage tonight, which is exactly why it has to be done now rather than five minutes before.",    "zh": "意象是一场没有观众的彩排。它对今晚台上的演出没有任何改变——这恰恰说明它必须现在就做，而不是在开演前五分钟。"   },   "example": {    "en": "A goalkeeper with a shoulder injury cannot practise saves, but can rehearse reading the striker's body shape, setting the feet and moving across. On return, the decision has already been practised.",    "zh": "一名肩部受伤的守门员无法练习扑救，却可以排练判断射门者的身体姿势、站位与横移。回归之时，决策早已演练过。"   }  },  "PETTLEP and imagery quality": {   "sum": [    {     "en": "**PETTLEP** is a checklist for making an image usable: Physical, Environment, Task, Timing, Learning, Emotion, Perspective.",     "zh": "**PETTLEP**是一份让图像变得可用的检查表：身体（Physical）、环境（Environment）、任务（Task）、时间（Timing）、学习（Learning）、情绪（Emotion）、视角（Perspective）。"    },    {     "en": "Each element exists because a mismatch makes the rehearsal useless. Imagery with the wrong environment trains a response the athlete will never need.",     "zh": "每个要素的存在都是因为不匹配会让排练失效。环境错误的意象，训练的是运动员永远用不上的反应。"    },    {     "en": "**Perspective** is the one most often wrong. Imagining from your own eyes is appropriate for motor rehearsal and inappropriate for some strategic ones.",     "zh": "**视角**是最常出错的一项。从自己的眼睛想象，适用于动作排练，而对某些策略排练则不适用。"    },    {     "en": "Image quality is what determines whether a rehearsal counts. Vague imagery is closer to daydreaming than to rehearsal.",     "zh": "图像质量决定一次排练是否算数。模糊的意象更接近走神，而不是排练。"    },    {     "en": "So the practical test is not how long someone imagines but whether the image contained the detail the task will demand.",     "zh": "因此实用的检验标准不是某人想象了多久，而是图像中是否包含了任务将要需要的那些细节。"    }   ],   "analogy": {    "en": "Rehearsing a penalty in an empty stadium and then taking it in front of a crowd is not more realistic practice. It is a different, easier task wearing the same clothes.",    "zh": "在空场中排练点球，然后却要在观众面前罚，这不是更真实的练习，而是换了一个更容易的任务穿着同一身衣服。"   },   "example": {    "en": "A tennis player rehearsing a serve should build the image from behind the baseline, hear the ball being tossed, feel the leg drive and see the target. Leave out the sound and the rehearsal is incomplete.",    "zh": "一名网球运动员排练发球，应从底线后方构建图像、听到抛球声、感到蹬腿动作并看到落点。漏掉声音，这次排练就是不完整的。"   }  },  "Paivio, specificity and applications": {   "sum": [    {     "en": "Paivio's theory holds that performance improves when imagery matches reality in **specificity**, in modality and in timing.",     "zh": "佩维奥的理论认为，当意象在**具体程度**、通道与时序上与现实匹配时，表现会得到改善。"    },    {     "en": "**Specific imagery** means rehearsing the actual situation rather than a generic version of it. Generic imagery is easier to produce and transfers less.",     "zh": "**具体意象**指排练真实情境而非其笼统版本。笼统的意象更容易产生，却迁移得更少。"    },    {     "en": "Modality matters too: if the task is judged by feel, kinaesthetic imagery; if by sight and sound, a visual and auditory image.",     "zh": "通道同样重要：若任务靠感觉判断，动觉意象更合适；若靠视觉与听觉，则用视觉加听觉的图像。"    },    {     "en": "Timing is the third: imagery of the whole performance and imagery of the critical moment can produce different results, because only one of them rehearses the decision.",     "zh": "第三是时序：整场比赛的意象与关键时刻的意象会产生不同结果，因为只有后者排练了决策。"    },    {     "en": "Applications follow directly: pre-performance for confidence, post-performance for review, and during a task for self-talk and routine.",     "zh": "应用由此而来：赛前用于建立自信，赛后用于复盘，任务过程中用于自我对话与固定流程。"    },    {     "en": "And for injury, where the application is rehabilitation itself — rehearsing a movement that cannot yet be performed is how the movement is kept alive while the tissue heals.",     "zh": "在伤病中，应用本身就是康复——排练暂时还做不出来的动作，是组织愈合期间让该动作不被遗忘的方法。"    }   ],   "analogy": {    "en": "Imagery is a rehearsal of a place you are not. The further it resembles the actual place, the less useful it is as practice and the more useful it is as planning.",    "zh": "意象是在你不去的地方进行的一次排练。它越接近真实地点，作为练习就越没用，作为谋划就越有用。"   },   "example": {    "en": "A high jumper rehearsing “jump over the bar in a stadium” is planning; the same athlete rehearsing the bar at their training height, hearing the crowd, feeling the approach rhythm, is practising.",    "zh": "一名跳高运动员排练“跳过横杆、在体育场里”，那是谋划；同一名运动员排练在训练高度上的横杆、听到观众声、感到助跑节奏，那才是练习。"   }  } };
